_UTTER_PREFIX = "utter_"
_NO_KNOWLEDGE_FOUND_NOTE = "No relevant knowledge found for the query."
_EMPTY_QUERY_NOTE = "Provide a non-empty search query."

# Key under ``SkillActivated.metadata`` carrying the timestamp of the user
# message that triggered the activation. The Inspector resolves the message
# text by matching this timestamp against the ``UserUttered`` on the tracker,
# so no message text (and thus no PII) is stamped on the event. Long term this
# will be replaced by a stable event id.
TRIGGERING_USER_MESSAGE_TIMESTAMP_METADATA_KEY = "triggering_user_message_timestamp"


def _search_result_note(note: str) -> str:
    """Serialise an empty knowledge result with an explanatory *note*.

    A ``note`` (not an ``error`` payload) so the turn is not flagged as failed
    and the model can decide how to respond. The message distinguishes a genuine
    empty retrieval from a malformed call (e.g. an empty query).
    """
    return json.dumps({"results": [], "note": note})


def _format_search_results(results: SearchResultList) -> str:
    """Serialise retrieved knowledge for the LLM as a JSON tool result.

    Each chunk carries its text plus the ``scope`` (``"global"`` or the owning
    skill id) and per-file ``source`` from the reference index. An empty result
    set returns the "no knowledge found" note.
    """
    if not results.results:
        return _search_result_note(_NO_KNOWLEDGE_FOUND_NOTE)
    # Same public passage fields as knowledge-results hooks (without score).
    return json.dumps(
        {
            "results": passages_from_results(results, include_score=False),
        }
    )


structlogger = structlog.get_logger()


def _latest_user_message_text(events: List[Event]) -> str:
    """Return the text of the most recent ``UserUttered`` event, or ``""``."""
    for event in reversed(events):
        if isinstance(event, UserUttered):
            return event.text or ""
    return ""


def _humanize_identifier(identifier: str) -> str:
    """Turn a skill id into a short user-facing label."""
    return identifier.replace("_", " ").strip().title()


def _skill_id_for_display(
    target_id: str, catalog: Optional[SkillCatalog] = None
) -> str:
    """Return the skill id from a skill id or a compiled block id.

    A compiled address is ``{skill_id}__{block_id}``. The block id is not
    part of the resume label. With a catalog, a skill id that itself
    contains ``__`` stays whole. Without one, the first ``__`` is the block
    separator.
    """
    if catalog is not None:
        skill = catalog.owning_skill_for_target_id(target_id)
        if skill is not None:
            return skill.id
        skill_id, separator, _block_id = target_id.partition(
            ORDERED_BLOCK_TARGET_ID_SEPARATOR
        )
        if separator and catalog.skill_by_id(skill_id) is not None:
            return skill_id
        return target_id
    skill_id, separator, _block_id = target_id.partition(
        ORDERED_BLOCK_TARGET_ID_SEPARATOR
    )
    if separator and skill_id:
        return skill_id
    return target_id


def _normalize_task_display_name(name: str, skill_id: str) -> str:
    """Normalize a skill frontmatter ``name`` for user-facing resume prompts.

    Authors may set ``name`` to an internal id or PascalCase slug
    (``card_replace``, ``CardReplace``). When the value already contains
    spaces it is treated as natural language and returned unchanged.
    """
    label = name.strip()
    if not label:
        return label

    if " " in label:
        return label

    if label.replace("_", "").lower() == skill_id.replace("_", "").lower():
        if label.isupper():
            return label
        return _humanize_identifier(skill_id)

    # Insert spaces at PascalCase / camelCase boundaries
    # (e.g. CardReplace → Card Replace).
    spaced = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", label)
    spaced = spaced.replace("_", " ").strip()
    if spaced.isupper():
        return spaced
    return spaced.title()


_DTMF_TYPED_SCALAR_TYPES = frozenset(
    {
        MEMORY_FIELD_TYPE_BOOL,
        MEMORY_FIELD_TYPE_INT,
        MEMORY_FIELD_TYPE_FLOAT,
    }
)


def _coerce_dtmf_value(raw_value: str, field: MemoryField) -> Any | None:
    """Coerce keypad text to a declared memory field type, or return ``None``."""
    if field.type == MEMORY_FIELD_TYPE_LIST:
        try:
            parsed = json.loads(raw_value)
        except (TypeError, ValueError):
            return None
        return parsed if isinstance(parsed, list) else None

    if field.type == MEMORY_FIELD_TYPE_JSON:
        try:
            return json.loads(raw_value)
        except (TypeError, ValueError):
            return None

    coerced = coerce_to_field_type(raw_value, field)
    if field.type == MEMORY_FIELD_TYPE_CATEGORICAL and field.enum_values:
        allowed = {str(value) for value in field.enum_values}
        return coerced if str(coerced) in allowed else None
    if field.type in _DTMF_TYPED_SCALAR_TYPES and isinstance(coerced, str):
        return None
    return coerced


class _SettableFieldsTurnContext(BaseModel):
    """Resolved scope for one ``settable_fields_for_turn`` call."""

    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)

    memory: MemoryManager
    skill_id: str
    flow_id: str
    overwrite_ok_field: Optional[str]


def _is_settable_entry_eligible(
    ctx: _SettableFieldsTurnContext,
    entry_name: str,
    field: Optional[MemoryField],
) -> bool:
    """Return whether *entry_name* may appear on the batch ``set_fields`` tool."""
    if field is None:
        return False
    try:
        entry = ctx.memory.get(ctx.skill_id, ctx.flow_id, entry_name)
    except ValueError:
        return False
    if (
        entry is not None
        and entry.value is not None
        and entry_name != ctx.overwrite_ok_field
    ):
        return False
    return True


def _append_settable_entries(
    eligible: list[str],
    descriptions: dict[str, Optional[str]],
    ctx: _SettableFieldsTurnContext,
    *,
    skill: Skill,
    entry_names: Iterable[str],
    fields_by_name: Mapping[str, MemoryField],
    collect_descriptions: Mapping[str, Optional[str]],
    skip_if_already_collected: bool = False,
) -> None:
    """Extend *eligible* / *descriptions* with entries that pass turn gating."""
    for entry_name in sorted(entry_names):
        if skip_if_already_collected and entry_name in descriptions:
            continue
        field = fields_by_name.get(entry_name)
        if not _is_settable_entry_eligible(ctx, entry_name, field):
            continue
        eligible.append(entry_name)
        descriptions[entry_name] = resolved_memory_field_description(
            skill,
            entry_name,
            collect_descriptions=collect_descriptions,
        )


class _StepLoopSignal(Enum):
    """Control signal returned by per-step handlers in ``advance_steps``.

    ``CONTINUE`` means the step was transparent and the loop should run again.
    ``BREAK`` means the step requires LLM involvement and the loop should stop.
    """

    CONTINUE = "continue"
    BREAK = "break"


# Return type for per-step handlers:
#   _StepLoopSignal.CONTINUE  → advance the loop
#   _StepLoopSignal.BREAK     → stop, let LLM handle; advance_steps returns None
#   AgentResponse             → stop, return this utterance to the orchestrator
_StepOutcome = Union[_StepLoopSignal, AgentResponse]

_EMPTY_TOOL_FUNCS: Mapping[str, Mapping[str, Callable[..., Any]]] = {}

# Bounds tool-driven handoffs per turn so tools that keep activating each other
# cannot loop the engine.
_MAX_TOOL_DRIVEN_ACTIVATIONS_PER_TURN = 10


class SkillExecutor:
    """Executes skill and phase logic for one engine turn.

    Constructed per turn by the ``Orchestrator`` from the ``ModelBootstrap``.
    All flows are resolved from the ``SkillCatalog`` — there is no separate
    ``FlowsList``.  Stateless between construction and the end of the turn —
    safe to discard after ``Orchestrator.run_turn`` returns.
    """

    def __init__(
        self,
        skill_catalog: SkillCatalog = SkillCatalog(),
        tool_funcs: Mapping[str, Mapping[str, Callable[..., Any]]] = _EMPTY_TOOL_FUNCS,
        response_registry: ResponseRegistry = ResponseRegistry(),
        mcp_runtime: Optional[MCPRuntime] = None,
        tool_timeout: Optional[float] = None,
        completion_judge: Optional[CompletionJudgeProtocol] = None,
        hooks: Optional[HookRegistry] = None,
        preconditions: Mapping[str, PreconditionBinding] | None = None,
        builtin_tool_constraints: Mapping[str, BuiltinToolConstraint] | None = None,
    ) -> None:
        self._skill_catalog = skill_catalog
        self._tool_funcs = tool_funcs
        self._response_registry = response_registry
        self._mcp_runtime = mcp_runtime
        self._tool_timeout = resolve_tool_timeout(tool_timeout)
        self._hooks = hooks if hooks is not None else HookRegistry.empty()
        self._preconditions = dict(preconditions or {})
        self._builtin_tool_constraints = dict(builtin_tool_constraints or {})
        self._cancel_skill_confirmation = cancel_skill_confirmation(
            self._builtin_tool_constraints
        )
        self._completion_gate = SkillCompletionGate(
            skill_catalog=skill_catalog,
            completion_judge=completion_judge,
        )
        self._verbatim_trigger_evaluator = VerbatimTriggerEvaluator(
            skill_catalog=skill_catalog,
            resolve_utterance=self.resolve_response_name,
        )
        self._tool_invoker = ToolInvoker(
            mcp_runtime=mcp_runtime,
            tool_timeout=self._tool_timeout,
            verbatim_trigger_evaluator=self._verbatim_trigger_evaluator,
        )
        # Owns cross-phase correction dispatch + replay. Injected collaborators
        # avoid a back-reference to this executor: the tool registry, the
        # registered-tool invoker, and the active-collect-step resolver.
        self._correction = CorrectionExecutor(
            skill_catalog=skill_catalog,
            tool_funcs=tool_funcs,
            mcp_runtime=mcp_runtime,
            call_tool_func=self.call_tool_func,
            active_collect_step=self.active_collect_step,
        )
        self._tool_constraints = ToolConstraintsExecutor(
            skill_catalog=skill_catalog,
            tool_funcs=tool_funcs,
            mcp_runtime=mcp_runtime,
            tool_invoker=self._tool_invoker,
            resolve_utterance=self.resolve_response_name,
            current_memory_values=self.current_memory_values,
            resolve_activation_target=self.resolve_activation_target,
            advance_or_complete=self._advance_or_complete,
            on_confirmed_cancel=self._cancel_skill,
        )
        # ``(frame_id, step_id)`` of the collect step the conversation was
        # already parked on when this turn began, or ``None``. Read by
        # :meth:`collect_question_already_asked`. Cleared by
        # :meth:`_take_parked_collect_deferral` and :meth:`_consume_collect_ask`.
        self._parked_collect_step: Optional[Tuple[str, str]] = None
        # ``(frame_id, step_id)`` of every collect that advanced with a value
        # during this turn. See :meth:`_consume_collect_ask`.
        self._consumed_collect_asks: set[Tuple[str, str]] = set()
        self._hangup_requested = False
        self._tool_driven_activation_count = 0
        self._tool_driven_cap_logged = False

    def begin_user_turn(self, tracker_handle: Optional[TrackerHandle] = None) -> None:
        """Reset per-turn confirmation, verbatim, and tool-instruction state.

        Pending ``ToolResult.next`` instructions from a cancelled turn are
        dropped. When *tracker_handle* is supplied, records whether the conversation was
        already parked on a collect step before this turn advanced anything.
        That snapshot is the signal :meth:`_handle_collect_step` uses to route
        the incoming message to the LLM instead of re-asking the question.
        """
        self._tool_constraints.begin_user_turn()
        self._verbatim_trigger_evaluator.begin_user_turn()
        self._tool_invoker.begin_user_turn()
        self._tool_driven_activation_count = 0
        self._tool_driven_cap_logged = False
        self._hangup_requested = False
        self._parked_collect_step = (
            self._collect_step_position(tracker_handle)
            if tracker_handle is not None
            else None
        )
        self._consumed_collect_asks = set()

    def _collect_step_position(
        self, tracker_handle: TrackerHandle
    ) -> Optional[Tuple[str, str]]:
        """Return ``(frame_id, step_id)`` when the active step is a collect step."""
        frame = tracker_handle.active_frame
        if (
            not isinstance(frame, (UserFlowStackFrame, OrderedBlockStackFrame))
            or self.active_collect_step(tracker_handle) is None
        ):
            return None
        return frame.frame_id, frame.step_id

    def set_completion_judge(self, completion_judge: CompletionJudgeProtocol) -> None:
        """Inject the orchestrator-owned completion-criteria judge."""
        self._completion_gate.set_completion_judge(completion_judge)

    def consume_confirmation_ask(self) -> Optional[AgentResponse]:
        """Return and clear a confirmation ask produced during tool dispatch."""
        return self._tool_constraints.consume_confirmation_ask()

    @property
    def hangup_requested(self) -> bool:
        """Return whether the current turn requested conversation termination."""
        return self._hangup_requested

    def clear_hangup_request(self) -> None:
        """Clear a pending hangup when another response must take precedence."""
        self._hangup_requested = False

    def consume_confirmation_denial(self) -> Optional[AgentResponse]:
        """Return and clear a denial utter queued on confirmation decline."""
        return self._tool_constraints.consume_confirmation_denial()

    def consume_verbatim_responses(self) -> List[AgentResponse]:
        """Return and clear verbatim responses queued during the turn."""
        return self._verbatim_trigger_evaluator.consume_responses()

    @property
    def tool_funcs(self) -> Mapping[str, Mapping[str, Callable[..., Any]]]:
        """Skill-scoped local tool registry: ``{skill_id: {tool_name: func}}``."""
        return self._tool_funcs

    @property
    def mcp_runtime(self) -> Optional[MCPRuntime]:
        """Processor-owned MCP runtime for this turn, if any."""
        return self._mcp_runtime

    def _is_builder_defined_tool(self, skill_id: str, tool_name: str) -> bool:
        """Return whether the skill exposes *tool_name* locally or via MCP import."""
        if tool_name in self._tool_funcs.get(skill_id, {}):
            return True
        return bool(
            self._mcp_runtime is not None
            and self._mcp_runtime.has_mcp_tool(skill_id, tool_name)
        )

    def mcp_server_for_tool(
        self, tool_name: str, tracker_handle: TrackerHandle
    ) -> Optional[str]:
        """Return the MCP server backing the active skill's tool, if any."""
        skill_id, _ = tracker_handle.memory_scope()
        if self._mcp_runtime is None or not self._mcp_runtime.has_mcp_tool(
            skill_id, tool_name
        ):
            return None
        return self._mcp_runtime.server_id_for(skill_id, tool_name)

    # ------------------------------------------------------------------
    # Activation / step lookup
    # ------------------------------------------------------------------

    def resolve_activation_target(
        self, target_id: str
    ) -> Optional[ResolvedActivationTarget]:
        """Return the :class:`ResolvedActivationTarget` for *target_id*, or ``None``."""
        return self._skill_catalog.resolve_activation_target(target_id)

    def _resolve_catalog_step(
        self,
        frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
    ) -> Optional[BaseStep]:
        """Return the catalog step for *frame*, or a virtual end at ``END``.

        Callers can park on ``END`` even when the ordered block omits an
        explicit end step; catalog lookup alone would then miss it. Skill
        frames have no persisted ``step_id``; the virtual prose step is
        synthesized from the skill (not stored in ``body``).
        """
        if isinstance(frame, SkillStackFrame):
            skill = self._skill_catalog.skill_by_id(frame.skill_id)
            if skill is None or not skill_has_prose(skill):
                return None
            return virtual_prose_step_for_skill(skill)

        step_id = frame.step_id
        if isinstance(frame, OrderedBlockStackFrame):
            block = self._skill_catalog.ordered_block_for_target_id(
                target_id_for_frame(frame)
            )
            if block is None:
                return None
            step = block.step_by_id(step_id)
            if step is None and step_id == END_STEP:
                return EndStep()
            return step

        target = self.resolve_activation_target(target_id_for_frame(frame))
        if target is None:
            return None
        step = target.step_by_id(step_id)
        if step is None and step_id == END_STEP:
            return EndStep()
        return step

    def _active_catalog_step(self, tracker_handle: TrackerHandle) -> Optional[BaseStep]:
        """Return the step object for the active frame, or ``None``."""
        frame = tracker_handle.active_frame
        if frame is None:
            return None
        return self._resolve_catalog_step(frame)

    def active_collect_step(
        self, tracker_handle: TrackerHandle
    ) -> Optional[CollectStep]:
        """The active frame's :class:`CollectStep`, or ``None``.

        Used by the orchestrator to expose the active collect field (and its
        setter tool or batch ``set_fields`` tool) to the LLM while the
        conversation is parked on a collect step.
        """
        step = self._active_catalog_step(tracker_handle)
        return step if isinstance(step, CollectStep) else None

    def collect_question_already_asked(self, tracker_handle: TrackerHandle) -> bool:
        """Whether the active collect step still counts as already asked.

        True only while the conversation is still on the collect step it was
        parked on when this turn began (see :meth:`begin_user_turn`). A step
        with no fixed utterance does not scan history: parked at turn start is
        enough. A fixed utterance clears the marker when that ask is missing
        from history, and advancing the step with a value clears it too.
        """
        position = self._collect_step_position(tracker_handle)
        return position is not None and position == self._parked_collect_step

    def _ask_before_filling_field_at_step(
        self, tracker_handle: TrackerHandle
    ) -> Optional[str]:
        """Return the active ``ask_before_filling`` collect field, if any.

        An ``ask_before_filling`` collect step is always asked when reached, even
        when its value is already set, so its field must stay settable via
        ``set_fields`` at that step to record the re-asked answer (the one entry
        allowed to overwrite an existing value there). Returns the collect entry
        name when the active step is such a step, otherwise ``None``.
        """
        step = self.active_collect_step(tracker_handle)
        if step is not None and step.ask_before_filling:
            return step.collect
        return None

    def settable_fields_for_turn(
        self, tracker_handle: TrackerHandle
    ) -> tuple[list[str], dict[str, Optional[str]]]:
        """Return skill-wide settable entry names and descriptions for ``set_fields``.

        The settable set is skill ``llm_settable`` fields union collect
        targets, minus entries denied for the active frame
        scope. Project fields are never included.

        Already-filled entries are withheld too, because ``set_fields`` never
        overwrites an existing value — corrections go through the ``correct``
        tool. The one exception is the active ``ask_before_filling`` collect
        field: that step is always asked (even when already filled), so its
        field stays settable here so the re-asked answer can be recorded.
        """
        frame = tracker_handle.active_frame
        if frame is None:
            return [], {}

        memory = tracker_handle.memory
        skill_id, flow_id = memory.resolve_scope(frame)
        skill = self._skill_catalog.skill_by_id(skill_id)
        if skill is None:
            return [], {}

        collect_owned = self._skill_catalog.collect_owned_entries.get(
            skill_id, frozenset()
        )
        settable_names = skill_settable_entry_names(skill, collect_owned=collect_owned)
        all_fields = skill.memory.definition.all_fields()
        # The active ``ask_before_filling`` collect field is always asked at its
        # step, so it stays settable even when already filled (overwrite allowed
        # via ``set_fields``) — the one exception to withholding filled entries.
        ctx = _SettableFieldsTurnContext(
            memory=memory,
            skill_id=skill_id,
            flow_id=flow_id,
            overwrite_ok_field=self._ask_before_filling_field_at_step(tracker_handle),
        )

        eligible: list[str] = []
        descriptions: dict[str, Optional[str]] = {}
        _append_settable_entries(
            eligible,
            descriptions,
            ctx,
            skill=skill,
            entry_names=settable_names,
            fields_by_name=all_fields,
            collect_descriptions=collect_step_descriptions(skill),
        )

        return eligible, descriptions

    async def write_dtmf_collect_value(
        self,
        tracker_handle: TrackerHandle,
        field_name: str,
        value: str,
    ) -> SettableWriteResult:
        """Write keypad input to the active collect through the settable path.

        The active collect check prevents a completed buffer from writing after
        the engine has moved to another step. This path applies schema coercion
        and reuses the normal write policy, memory validation tools, provenance,
        and ``when`` trigger evaluation.

        Args:
            tracker_handle: Handle for the current engine turn.
            field_name: Collect field targeted when the digits were buffered.
            value: Completed keypad input.

        Returns:
            The validated memory-write outcome.
        """
        frame = tracker_handle.active_frame
        active_collect = self.active_collect_step(tracker_handle)
        # Do not retarget digits if the active collect changed while queued.
        if (
            frame is None
            or active_collect is None
            or active_collect.dtmf is None
            or active_collect.collect != field_name
        ):
            return SettableWriteResult(
                ok=False,
                error="The DTMF collect is no longer active.",
            )

        # Enforce the same memory-write eligibility as set_fields.
        eligible_fields, _ = self.settable_fields_for_turn(tracker_handle)
        if field_name not in eligible_fields:
            return SettableWriteResult(
                ok=False,
                error="The active DTMF collect is not writable.",
            )

        memory = tracker_handle.memory
        skill_id, flow_id = memory.resolve_scope(frame)
        skill = self._skill_catalog.skill_by_id(skill_id)
        field = (
            skill.memory.definition.all_fields().get(field_name)
            if skill is not None
            else None
        )
        if field is None:
            return SettableWriteResult(
                ok=False,
                error="The active DTMF collect field is not declared.",
            )

        # DTMF arrives as text; coerce it to the declared memory type.
        coerced_value = _coerce_dtmf_value(value, field)
        if coerced_value is None:
            return SettableWriteResult(
                ok=False,
                error="The DTMF input does not match the collect field type.",
            )

        # Preserve pre-write values for false-to-true `when:` triggers.
        memory_values_before = snapshot_accessible_memory(memory, skill_id, flow_id)
        result = await write_settable_field(
            tracker_handle,
            skill_id,
            flow_id,
            field_name,
            coerced_value,
            self._tool_funcs,
            self.call_tool_func,
        )
        # Apply queued validation events before evaluating `when:` triggers.
        tracker_handle.apply_events(tracker_handle.drain_memory_validation_events())
        if result.ok:
            self._verbatim_trigger_evaluator.evaluate_when_triggers(
                skill_id,
                flow_id,
                tracker_handle,
                memory_values_before=memory_values_before,
            )
        return result

    # ------------------------------------------------------------------
    # Skill lifecycle helpers
    # ------------------------------------------------------------------

    def _activation_target_id(self, target_id: str) -> str:
        """Map a skill id to the entry target id the stack actually pushes.

        A compiled block id is left unchanged. A skill id becomes that skill's
        entry: the skill id for prose, or the entry block's compiled id for a
        blocks-only skill.
        """
        skill = self._skill_catalog.skill_by_id(target_id)
        if skill is None:
            return target_id
        return entry_target_id_for_skill(skill) or target_id

    def activate(
        self,
        target_id: str,
        session: TrackerHandle,
        *,
        skill_id: Optional[str] = None,
        block_id: Optional[str] = None,
    ) -> bool:
        """Activate *target_id* on the stack as a regular frame.

        Public entry point used by callers outside the turn loop (e.g. the
        Mantle processor's session initialisation) to push the skill or
        ordered-block frame and emit its lifecycle events via the tracker
        handle. *target_id* is a skill id or a compiled block id. Returns
        ``True`` when the frame was pushed, ``False`` when *target_id* is
        unknown.

        When *block_id* is omitted, the authored ordered-block id is resolved
        from the catalog for compiled addresses. Callers that already know the
        block may pass it explicitly. ``_activate`` still emits
        ``OrderedBlockEntered`` only when a *block_id* is provided.
        """
        resolved_block_id = (
            block_id
            if block_id is not None
            else self._skill_catalog.ordered_block_id_for_target(target_id)
        )
        return self._activate(
            target_id,
            session,
            skill_id=skill_id,
            block_id=resolved_block_id,
        )

    def _discard_active_lifecycle_default(self, tracker_handle: TrackerHandle) -> bool:
        """Cancel the active lifecycle prompt without post-cancel routing."""
        new_stack = tracker_handle.stack.copy()
        popped = new_stack.pop()
        if not isinstance(
            popped, (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame)
        ):
            return False

        removed: list[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame] = [
            popped
        ]
        discarded_skill_id = lifecycle_skill_id_for_frame(self._skill_catalog, popped)
        if discarded_skill_id is None:
            return False
        while not new_stack.is_empty():
            family_frame = new_stack.top()
            if (
                not isinstance(
                    family_frame,
                    (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
                )
                or owning_skill_id_for_frame(self._skill_catalog, family_frame)
                != discarded_skill_id
            ):
                break
            removed.append(new_stack.pop())

        tracker_handle.apply_events(
            [
                *self._cancel_frames(tracker_handle, removed),
                *tracker_handle.create_stack_update_events(new_stack),
            ]
        )
        return True

    def discard_active_lifecycle_default(self, tracker_handle: TrackerHandle) -> bool:
        """Discard the active engine-managed lifecycle skill without rerouting."""
        return self._discard_active_lifecycle_default(tracker_handle)

    def _skill_is_on_user_stack(
        self,
        tracker_handle: TrackerHandle,
        skill_id: str,
    ) -> bool:
        """Return whether *skill_id* already owns a user frame on the stack."""
        for frame in tracker_handle.skill_and_block_frames():
            if frame.skill_id == skill_id:
                return True
        for user_frame in tracker_handle.user_flow_frames():
            owning_skill = skill_for_stack_frame(self._skill_catalog, user_frame)
            if owning_skill is not None and owning_skill.id == skill_id:
                return True
        return False

    def _reset_skill_memory_for_new_run(
        self,
        flow_id: str,
        tracker_handle: TrackerHandle,
        *,
        skill_id: Optional[str] = None,
    ) -> None:
        """Reset a skill's declared memory when this activation is a new run.

        Skip when the skill already has a frame on the stack (same run:
        in-flight ``call:``, duplicate activate). Callers that seeded
        memory or continue a same-skill ``link:`` pass
        ``reset_memory=False`` and never reach this helper.

        Fields that must be re-collected on every new run should leave
        ``initial_value`` unset; a non-``None`` schema default becomes the
        post-reset slot value.
        """
        skill = (
            self._skill_catalog.skill_by_id(skill_id)
            if skill_id is not None
            else self._skill_catalog.owning_skill_for_target_id(flow_id)
        )
        if skill is None:
            return
        if self._skill_is_on_user_stack(tracker_handle, skill.id):
            return
        tracker_handle.memory.reset_entries_to_initial(
            skill.id,
            flow_id,
            skill.memory.definition.all_fields(),
        )

    def _precondition_binding_for_skill(
        self, skill: Skill
    ) -> PreconditionBinding | None:
        if not skill.precondition:
            return None
        return self._preconditions.get(skill.precondition)

    def _activate_with_preconditions(
        self,
        flow_id: str,
        tracker_handle: TrackerHandle,
        memory_values: Dict[str, Any],
        *,
        frame_type: FlowStackFrameType = FlowStackFrameType.REGULAR,
        new_frame_type: FlowStackFrameType = FlowStackFrameType.REGULAR,
        skill_id: Optional[str] = None,
        block_id: Optional[str] = None,
        reset_memory: bool = True,
    ) -> bool:
        """Activate *flow_id* or start pending+resolver when a precondition applies."""
        owning_skill = self._skill_catalog.owning_skill_for_target_id(flow_id)
        if owning_skill is None:
            return self._activate(
                flow_id,
                tracker_handle,
                frame_type=frame_type,
                new_frame_type=new_frame_type,
                skill_id=skill_id,
                block_id=block_id,
                reset_memory=reset_memory,
            )

        binding = self._precondition_binding_for_skill(owning_skill)
        if binding is None:
            return self._activate(
                flow_id,
                tracker_handle,
                frame_type=frame_type,
                new_frame_type=new_frame_type,
                skill_id=skill_id,
                block_id=block_id,
                reset_memory=reset_memory,
            )

        if precondition_satisfied(binding, memory_values):
            return self._activate(
                flow_id,
                tracker_handle,
                frame_type=frame_type,
                new_frame_type=new_frame_type,
                skill_id=skill_id,
                block_id=block_id,
                reset_memory=reset_memory,
            )

        # If the resolver is already the live skill, park the consumer under
        # that run. A second resolver would interrupt the first, reset its
        # memory, and later offer continue_interrupted for work already done.
        if self._park_pending_under_live_resolver(
            flow_id,
            tracker_handle,
            resolver_skill_id=binding.resolve_with,
            new_frame_type=new_frame_type,
            skill_id=skill_id or owning_skill.id,
            block_id=block_id,
        ):
            return True

        if not self._push_pending_target(
            flow_id,
            tracker_handle,
            frame_type=frame_type,
            new_frame_type=new_frame_type,
            skill_id=skill_id or owning_skill.id,
            block_id=block_id,
        ):
            return False

        resolver_skill = self._skill_catalog.skill_by_id(binding.resolve_with)
        if resolver_skill is None:
            structlogger.error(
                "mantle.skill_executor.precondition.missing_resolver",
                resolver_skill_id=binding.resolve_with,
            )
            self._pop_pending_target(tracker_handle)
            return False

        resolver_flow_id = entry_target_id_for_skill(resolver_skill)
        if resolver_flow_id is None:
            structlogger.error(
                "mantle.skill_executor.precondition.resolver_no_entry",
                resolver_skill_id=binding.resolve_with,
            )
            self._pop_pending_target(tracker_handle)
            return False

        if not self._activate(
            resolver_flow_id,
            tracker_handle,
            frame_type=FlowStackFrameType.REGULAR,
            new_frame_type=FlowStackFrameType.CALL,
            skill_id=resolver_skill.id,
            block_id=self._skill_catalog.ordered_block_id_for_target(resolver_flow_id),
            reset_memory=True,
        ):
            self._pop_pending_target(tracker_handle)
            return False
        return True

    def _push_pending_target(
        self,
        flow_id: str,
        tracker_handle: TrackerHandle,
        *,
        frame_type: FlowStackFrameType = FlowStackFrameType.REGULAR,
        new_frame_type: FlowStackFrameType = FlowStackFrameType.REGULAR,
        skill_id: Optional[str] = None,
        block_id: Optional[str] = None,
    ) -> bool:
        """Push a precondition consumer frame without activation side effects."""
        return self._activate(
            flow_id,
            tracker_handle,
            frame_type=frame_type,
            new_frame_type=new_frame_type,
            skill_id=skill_id,
            block_id=block_id,
            reset_memory=False,
            defer_activation_side_effects=True,
            mantle_push_frame_type=MantleStackFrameType.PENDING,
        )

    def _park_pending_under_live_resolver(
        self,
        flow_id: str,
        tracker_handle: TrackerHandle,
        *,
        resolver_skill_id: str,
        new_frame_type: FlowStackFrameType,
        skill_id: str,
        block_id: Optional[str],
    ) -> bool:
        """Park a pending consumer under an already-running resolver.

        Returns ``True`` when the live top skill *is* the resolver and the
        pending consumer was inserted beneath it. Returns ``False`` when the
        resolver is not live so the caller should start a new resolver run.
        """
        original_frames = list(tracker_handle.stack.frames)
        below, family = split_live_resolver_family(original_frames, resolver_skill_id)
        if not family:
            return False

        peeled = tracker_handle.stack.copy()
        peeled.frames = below
        tracker_handle.apply_events(tracker_handle.create_stack_update_events(peeled))

        if not self._push_pending_target(
            flow_id,
            tracker_handle,
            frame_type=FlowStackFrameType.REGULAR,
            new_frame_type=new_frame_type,
            skill_id=skill_id,
            block_id=block_id,
        ):
            restored = tracker_handle.stack.copy()
            restored.frames = original_frames
            tracker_handle.apply_events(
                tracker_handle.create_stack_update_events(restored)
            )
            return False

        restored = tracker_handle.stack.copy()
        for frame in family:
            restored.push(frame)
        tracker_handle.apply_events(tracker_handle.create_stack_update_events(restored))
        structlogger.debug(
            "mantle.skill_executor.precondition.reuse_active_resolver",
            resolver_skill_id=resolver_skill_id,
            consumer_flow_id=flow_id,
        )
        return True

    def _pop_pending_target(self, tracker_handle: TrackerHandle) -> None:
        """Remove a pending consumer frame after a failed resolver push."""
        remaining = drop_top_pending_consumer(tracker_handle.stack.frames)
        if remaining is None:
            return
        new_stack = tracker_handle.stack.copy()
        new_stack.frames = remaining
        tracker_handle.apply_events(
            tracker_handle.create_stack_update_events(new_stack)
        )

    def _try_finish_precondition_resolution(
        self,
        popped: UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame,
        tracker_handle: TrackerHandle,
    ) -> bool:
        """Promote or abandon a pending consumer after its resolver completes."""
        if tracker_handle.stack.is_empty():
            return False
        pending_frame = tracker_handle.stack.top()
        if not isinstance(pending_frame, (SkillStackFrame, OrderedBlockStackFrame)):
            return False
        if pending_frame.frame_type != MantleStackFrameType.PENDING:
            return False

        consumer_skill = self._skill_catalog.skill_by_id(pending_frame.skill_id)
        if consumer_skill is None or not consumer_skill.precondition:
            return False
        binding = self._precondition_binding_for_skill(consumer_skill)
        if binding is None:
            return False

        completed_skill_id = owning_skill_id_for_frame(self._skill_catalog, popped)
        if completed_skill_id != binding.resolve_with:
            return False

        memory_values = self.current_memory_values(tracker_handle)
        if precondition_satisfied(binding, memory_values):
            self._promote_pending_precondition(
                consumer_skill, pending_frame, tracker_handle
            )
        else:
            self._abandon_pending_precondition(consumer_skill, binding, tracker_handle)
        return True

    def _promote_pending_precondition(
        self,
        consumer_skill: Skill,
        pending_frame: SkillStackFrame | OrderedBlockStackFrame,
        tracker_handle: TrackerHandle,
    ) -> None:
        """Turn a pending consumer frame into an active skill run."""
        flow_id = target_id_for_frame(pending_frame) or consumer_skill.id
        new_stack = tracker_handle.stack.copy()
        new_stack.frames = promote_pending_consumer_frames(
            new_stack.frames, consumer_skill.id
        )

        # The pending consumer is already on the stack, so
        # ``_reset_skill_memory_for_new_run`` would skip. Reset here: this is
        # the first real activation, deferred from the pending push.
        tracker_handle.memory.reset_entries_to_initial(
            consumer_skill.id,
            flow_id,
            consumer_skill.memory.definition.all_fields(),
        )
        events: List[Event] = [
            SkillActivated(
                skill_id=consumer_skill.id,
                metadata=self._skill_activation_metadata(tracker_handle),
            ),
        ]
        block_id = self._skill_catalog.ordered_block_id_for_target(flow_id)
        if block_id is not None:
            events.append(
                OrderedBlockEntered(skill_id=consumer_skill.id, block_id=block_id)
            )
        events.extend(tracker_handle.create_stack_update_events(new_stack))
        tracker_handle.apply_events(events)
        self._verbatim_trigger_evaluator.queue_activate_triggers(
            consumer_skill.id, tracker_handle
        )

    def _abandon_pending_precondition(
        self,
        consumer_skill: Skill,
        binding: PreconditionBinding,
        tracker_handle: TrackerHandle,
    ) -> None:
        """Drop a pending consumer after the resolver did not satisfy the gate."""
        new_stack = tracker_handle.stack.copy()
        new_stack.frames = drop_skill_frames(new_stack.frames, consumer_skill.id)
        events: List[Event] = list(tracker_handle.create_stack_update_events(new_stack))
        if binding.unmet_utterance:
            resolved = self.resolve_response_name(
                PRECONDITION_UNMET_RESPONSE, tracker_handle
            )
            events.append(
                BotUttered(
                    text=resolved.text,
                    metadata={
                        UTTER_ACTION_METADATA_KEY: PRECONDITION_UNMET_RESPONSE,
                    },
                )
            )
        tracker_handle.apply_events(events)

    def _activate(
        self,
        target_id: str,
        tracker_handle: TrackerHandle,
        *,
        frame_type: FlowStackFrameType = FlowStackFrameType.REGULAR,
        new_frame_type: FlowStackFrameType = FlowStackFrameType.REGULAR,
        skill_id: Optional[str] = None,
        block_id: Optional[str] = None,
        reset_memory: bool = True,
        defer_activation_side_effects: bool = False,
        mantle_push_frame_type: MantleStackFrameType | None = None,
    ) -> bool:
        """Push a new stack frame and emit the appropriate lifecycle events.

        The *frame_type* argument controls **how the existing top frame is
        treated**:

        * ``INTERRUPT`` → mark the current top frame as interrupted
          (digression path) before pushing; emits ``SkillInterrupted`` (and
          ``OrderedBlockInterrupted`` for block frames).
        * ``INLINE_REFERENCE`` → silently park the current top frame for a
          same-skill parent / inline-sub-flow switch (no digression resume
          prompt).
        * ``REGULAR`` (default) → push directly without touching existing
          frames.

        Note: ``LINK`` is accepted as *frame_type* but behaves identically
        to ``REGULAR`` — no existing frame is modified. A link to another
        skill completes the source via :meth:`_complete_skill` before this
        method runs. A same-skill link to another ordered block pops only
        that block via :meth:`_pop_block_keeping_skill` and leaves the skill
        frame in place.

        The *new_frame_type* argument controls the type of the **pushed**
        frame.  Defaults to ``REGULAR``; pass ``CALL`` when the new frame is a
        deterministic sub-flow invoked by a ``call:`` step, so cancellation can
        treat it as part of the calling task (see :meth:`_cancel_skill`).

        Args:
            target_id: Skill id or compiled block id to activate.
            tracker_handle: Live tracker wrapper for this turn.
            frame_type: Determines interruption behaviour for the existing
                top frame.  Use ``INTERRUPT`` for digressions and
                ``INLINE_REFERENCE`` when pushing a new inline sub-flow.
            new_frame_type: Frame type stored on the newly pushed frame.
                Use ``CALL`` for ``call:`` sub-flows.
            skill_id: The owning skill ID, if known.  Stored on the stack
                frame for observability; does not affect routing.
            block_id: The bare ordered-block ID when entering a block.
            reset_memory: When ``True`` (default), reset declared
                skill memory before pushing the frame if this is a new run
                (skill not already on the stack). Pass ``False`` when the
                caller has just seeded memory (e.g. ``cannot_help``) or for
                same-skill ``call:`` / ``link:`` so in-flight memory is
                preserved.
            defer_activation_side_effects: When ``True``, push stack frames
                only (no ``SkillActivated`` / ``OrderedBlockEntered``, memory
                reset, or activate utter triggers). Used for precondition ``pending``
                consumers.
            mantle_push_frame_type: When set, stored on pushed Mantle frames
                instead of deriving from *new_frame_type* (e.g. ``PENDING``).

        Returns:
            ``True`` if the frame was pushed; ``False`` when *target_id* is
            not found in the catalog, or when no Mantle skill/ordered-block
            frame applies (stack left unchanged — never pushes
            ``UserFlowStackFrame``).
        """
        # Only a blocks-only skill id changes, into its entry block.
        target_id = self._activation_target_id(target_id)
        if block_id is None:
            block_id = self._skill_catalog.ordered_block_id_for_target(target_id)
        target = self.resolve_activation_target(target_id)
        if target is None:
            structlogger.warning(
                "mantle.skill_executor.activate.unknown",
                target_id=target_id,
            )
            return False

        parent_skill_id, _ = tracker_handle.memory_scope()
        activated_skill_id, block_id, first_step = self._resolve_activation_ids(
            target_id=target_id,
            target=target,
            skill_id=skill_id,
            block_id=block_id,
        )

        if reset_memory and not defer_activation_side_effects:
            self._reset_skill_memory_for_new_run(
                target_id,
                tracker_handle,
                skill_id=skill_id,
            )

        events: List[Event] = []
        new_stack = tracker_handle.stack.copy()

        if frame_type in (
            FlowStackFrameType.INTERRUPT,
            FlowStackFrameType.INLINE_REFERENCE,
        ):
            new_stack, events = self._park_top_before_push(
                new_stack,
                events,
                park_type=frame_type,
                activated_flow_id=target_id,
                first_step=first_step,
                skill_id=skill_id,
            )

        if not self._push_mantle_activation_frames(
            new_stack=new_stack,
            flow_id=target_id,
            activated_skill_id=activated_skill_id,
            block_id=block_id,
            first_step=first_step,
            frame_type=frame_type,
            new_frame_type=new_frame_type,
            mantle_skill_frame_type=mantle_push_frame_type,
        ):
            return False

        if defer_activation_side_effects:
            events.extend(tracker_handle.create_stack_update_events(new_stack))
            tracker_handle.apply_events(events)
            return True

        skill_to_activate: Optional[str] = None
        if activated_skill_id is not None and self._is_new_skill_entry(
            frame_type=frame_type,
            activated_skill_id=activated_skill_id,
            parent_skill_id=parent_skill_id,
        ):
            skill_to_activate = activated_skill_id
            events.append(
                SkillActivated(
                    skill_id=skill_to_activate,
                    metadata=self._skill_activation_metadata(tracker_handle),
                )
            )
        if activated_skill_id is not None and block_id is not None:
            events.append(
                OrderedBlockEntered(
                    skill_id=activated_skill_id,
                    block_id=block_id,
                )
            )
        events.extend(tracker_handle.create_stack_update_events(new_stack))
        tracker_handle.apply_events(events)
        if skill_to_activate is not None:
            self._verbatim_trigger_evaluator.queue_activate_triggers(
                skill_to_activate, tracker_handle
            )
        return True

    def _skill_activation_metadata(
        self, tracker_handle: TrackerHandle
    ) -> Optional[Dict[str, Any]]:
        """Return ``SkillActivated`` metadata stamped with the trigger timestamp.

        Stamps the turn's current user message *timestamp* under
        :data:`TRIGGERING_USER_MESSAGE_TIMESTAMP_METADATA_KEY`. Only the
        timestamp is recorded, never the message text: the text would duplicate
        PII that ``UserUttered`` scrubbing cannot reach on this event. The
        Inspector resolves the text by matching the timestamp against the
        ``UserUttered`` on the tracker (a stable event id will replace this
        later). Returns ``None`` when no user message is available so the event
        carries no empty metadata.
        """
        triggering_timestamp = tracker_handle.current_user_message_timestamp
        if triggering_timestamp is None:
            return None
        return {TRIGGERING_USER_MESSAGE_TIMESTAMP_METADATA_KEY: triggering_timestamp}

    def _resolve_activation_ids(
        self,
        *,
        target_id: str,
        target: ResolvedActivationTarget,
        skill_id: Optional[str],
        block_id: Optional[str],
    ) -> tuple[Optional[str], Optional[str], str]:
        """Resolve skill id, block id, and first step for an activation push.

        Matches public ``activate``: omit *block_id* → the catalog entry
        activation target, else infer a skill-level ``{skill}__{block}`` suffix
        so guided defaults/tests without ordered blocks in ``body`` still get a
        Mantle block id.
        """
        first_step = target.steps[0].id if target.steps else START_STEP
        activated_skill_id = skill_id
        if activated_skill_id is None:
            owning_skill = self._skill_catalog.owning_skill_for_target_id(target_id)
            activated_skill_id = owning_skill.id if owning_skill else None

        resolved_block_id = block_id
        if resolved_block_id is None:
            resolved_block_id = self._skill_catalog.ordered_block_id_for_target(
                target_id
            )
        if (
            resolved_block_id is None
            and activated_skill_id is not None
            and self._is_skill_level_target(target_id, activated_skill_id)
        ):
            prefix = f"{activated_skill_id}__"
            if target_id.startswith(prefix):
                inferred = target_id[len(prefix) :]
                if inferred:
                    resolved_block_id = inferred

        return activated_skill_id, resolved_block_id, first_step

    def _push_mantle_activation_frames(
        self,
        *,
        new_stack: DialogueStack,
        flow_id: str,
        activated_skill_id: Optional[str],
        block_id: Optional[str],
        first_step: str,
        frame_type: FlowStackFrameType,
        new_frame_type: FlowStackFrameType,
        mantle_skill_frame_type: MantleStackFrameType | None = None,
    ) -> bool:
        """Push skill and/or ordered-block frames for a Mantle activation.

        Block-onto-live-same-skill wins over guided when both match (a same-skill
        block onto live prose) — otherwise a second skill frame would be
        pushed. Returns ``False`` when no Mantle frame applies or required ids
        are missing (caller discards *new_stack* without applying events).
        """
        skill_frame_type = (
            mantle_skill_frame_type
            if mantle_skill_frame_type is not None
            else (
                MantleStackFrameType.CALL
                if new_frame_type == FlowStackFrameType.CALL
                else MantleStackFrameType.REGULAR
            )
        )
        existing = self._is_block_onto_live_same_skill(
            new_stack=new_stack,
            activated_skill_id=activated_skill_id,
            block_id=block_id,
            new_frame_type=new_frame_type,
        )
        guided = self._is_guided_skill_plus_block_entry(
            flow_id=flow_id,
            activated_skill_id=activated_skill_id,
            block_id=block_id,
            frame_type=frame_type,
            new_frame_type=new_frame_type,
        )
        prose = self._is_prose_only_entry(
            flow_id=flow_id,
            activated_skill_id=activated_skill_id,
            block_id=block_id,
            frame_type=frame_type,
            new_frame_type=new_frame_type,
        )
        push_block = existing or guided
        push_skill = (guided or prose) and not existing
        if not push_skill and not push_block:
            structlogger.warning(
                "mantle.skill_executor.activate.no_mantle_frame",
                flow_id=flow_id,
                skill_id=activated_skill_id,
                block_id=block_id,
            )
            return False
        if push_skill:
            if activated_skill_id is None:
                return False
            previous_frame_type = (
                MantleStackFrameType.CALL
                if mantle_skill_frame_type == MantleStackFrameType.PENDING
                and new_frame_type == FlowStackFrameType.CALL
                else None
            )
            new_stack.push(
                SkillStackFrame(
                    skill_id=activated_skill_id,
                    frame_type=skill_frame_type,
                    previous_frame_type=previous_frame_type,
                )
            )
        if push_block:
            if activated_skill_id is None or block_id is None:
                return False
            previous_frame_type = None
            if (
                mantle_skill_frame_type == MantleStackFrameType.PENDING
                and new_frame_type == FlowStackFrameType.CALL
            ):
                previous_frame_type = (
                    MantleStackFrameType.REGULAR
                    if push_skill
                    else MantleStackFrameType.CALL
                )
            new_stack.push(
                OrderedBlockStackFrame(
                    skill_id=activated_skill_id,
                    block_id=block_id,
                    step_id=first_step,
                    frame_type=(
                        MantleStackFrameType.REGULAR
                        if push_skill and skill_frame_type == MantleStackFrameType.CALL
                        else skill_frame_type
                    ),
                    previous_frame_type=previous_frame_type,
                )
            )
        return True

    def _is_new_skill_entry(
        self,
        *,
        frame_type: FlowStackFrameType,
        activated_skill_id: str,
        parent_skill_id: str,
    ) -> bool:
        """Return whether this activate is entry into a different skill.

        Same-skill pushes (ordered blocks, inline subflows, same-skill ``CALL``)
        and inline-reference parks are not new skill entries. Callers use this
        to gate ``SkillActivated`` and ``on: activate`` utter triggers.
        """
        if frame_type == FlowStackFrameType.INLINE_REFERENCE:
            return False
        return parent_skill_id != activated_skill_id

    def _is_guided_skill_plus_block_entry(
        self,
        *,
        flow_id: str,
        activated_skill_id: Optional[str],
        block_id: Optional[str],
        frame_type: FlowStackFrameType,
        new_frame_type: FlowStackFrameType,
    ) -> bool:
        """Return whether this activation pushes a blocks-only skill and block.

        Regular starts, digressions, and ``call:`` into a blocks-only skill
        push ``SkillStackFrame`` then an ``OrderedBlockStackFrame``. A start
        by skill id uses the entry block. A ``call:`` or tool handoff that
        names another routable block of that skill starts there. An internal
        block does not. On ``call:`` the
        skill frame is ``call`` and the block stays ``regular``. Same-skill
        prose already on the stack uses
        :meth:`_is_block_onto_live_same_skill` (existing wins at the
        push site so a second skill frame is not pushed).
        """
        return (
            activated_skill_id is not None
            and block_id is not None
            and frame_type
            in (
                FlowStackFrameType.REGULAR,
                FlowStackFrameType.INTERRUPT,
            )
            and new_frame_type in (FlowStackFrameType.REGULAR, FlowStackFrameType.CALL)
            and (
                self._is_skill_level_target(flow_id, activated_skill_id)
                or self._is_routable_blocks_only_block(flow_id, activated_skill_id)
            )
        )

    def _is_routable_blocks_only_block(self, target_id: str, skill_id: str) -> bool:
        """Return whether *target_id* is a routable block of a blocks-only skill.

        A tool handoff or ``call:`` may name a block that is not the entry.
        An internal block stays closed until that skill is already on the
        stack. A block of a skill with prose does not start the skill by
        itself.
        """
        skill = self._skill_catalog.skill_by_id(skill_id)
        if skill is None or skill_has_prose(skill):
            return False
        target = self._skill_catalog.resolve_activation_target(target_id)
        if target is None or not target.routable:
            return False
        return self._skill_catalog.ordered_block_id_for_target(target_id) is not None

    def _is_block_onto_live_same_skill(
        self,
        *,
        new_stack: DialogueStack,
        activated_skill_id: Optional[str],
        block_id: Optional[str],
        new_frame_type: FlowStackFrameType,
    ) -> bool:
        """Return whether to push only an ordered-block frame onto a live same skill.

        The existing skill or block frame is left as-is — this is not a
        same-skill block park. ``call:`` into a same-skill routable block
        pushes the block as ``call``.
        """
        if activated_skill_id is None or block_id is None:
            return False
        if new_frame_type not in (
            FlowStackFrameType.REGULAR,
            FlowStackFrameType.CALL,
        ):
            return False
        top = new_stack.top()
        if not isinstance(top, (SkillStackFrame, OrderedBlockStackFrame)):
            return False
        if top.skill_id != activated_skill_id:
            return False
        if isinstance(top, SkillStackFrame):
            return top.frame_type in (
                MantleStackFrameType.REGULAR,
                MantleStackFrameType.CALL,
            )
        if new_frame_type == FlowStackFrameType.CALL:
            return top.frame_type in (
                MantleStackFrameType.REGULAR,
                MantleStackFrameType.CALL,
            )
        return top.frame_type in (
            MantleStackFrameType.REGULAR,
            MantleStackFrameType.INLINE_REFERENCE,
        )

    def _is_prose_only_entry(
        self,
        *,
        flow_id: str,
        activated_skill_id: Optional[str],
        block_id: Optional[str],
        frame_type: FlowStackFrameType,
        new_frame_type: FlowStackFrameType,
    ) -> bool:
        """Return whether this activation is hybrid/standalone prose only.

        Prose compiled flows use the skill id as the flow id (not an ordered
        block address). ``call:`` into prose uses the same skill frame with
        type ``call``. A blocks-only entry block uses
        :meth:`_is_guided_skill_plus_block_entry`.
        """
        if (
            activated_skill_id is None
            or block_id is not None
            or frame_type
            not in (FlowStackFrameType.REGULAR, FlowStackFrameType.INTERRUPT)
            or new_frame_type
            not in (FlowStackFrameType.REGULAR, FlowStackFrameType.CALL)
            or flow_id != activated_skill_id
            or self._skill_catalog.ordered_block_id_for_target(flow_id) is not None
        ):
            return False
        return self.resolve_activation_target(flow_id) is not None

    def _authored_block_id(
        self, frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
    ) -> Optional[str]:
        """Return the authored ordered-block ID for *frame*, if it is a block."""
        return authored_block_id_for_frame(self._skill_catalog, frame)

    def _is_skill_level_target(self, target_id: str, skill_id: Optional[str]) -> bool:
        """Return whether *target_id* is leaving or representing the skill itself.

        See :func:`~rasa.mantle.orchestration.cancel_events.is_skill_level_target`.
        """
        return is_skill_level_target(self._skill_catalog, target_id, skill_id)

    def _should_emit_skill_completed(
        self, completed_flow_id: str, skill_id: Optional[str]
    ) -> bool:
        """Return whether this completion is leaving the skill, not a block.

        Ordered-block and other internal (non-routable) frames emit
        ``OrderedBlockCompleted`` only. Skill-level completion also emits
        ``SkillCompleted``.
        """
        return self._is_skill_level_target(completed_flow_id, skill_id)

    def _cancelled_events_for_frames(
        self,
        frames: Sequence[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame],
    ) -> List[Event]:
        """Emit cancel events for the given frames.

        Writes ``OrderedBlockCancelled`` per block frame and ``SkillCancelled``
        once per skill. Shared with the A2A cancel handler through
        :func:`~rasa.mantle.orchestration.cancel_events.cancelled_events_for_frames`.
        """
        return cancelled_events_for_frames(self._skill_catalog, frames)

    def _clear_pending_confirmation_for_removed_frames(
        self,
        tracker_handle: TrackerHandle,
        frames: Sequence[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame],
    ) -> None:
        """Clear a pending confirmation when a bulk stack edit removes its owner."""
        for frame in frames:
            tracker_handle.clear_pending_tool_confirmation_if_owned_by(
                frame_id=frame.frame_id,
                skill_id=owning_skill_id_for_frame(self._skill_catalog, frame),
            )

    def _cancel_frames(
        self,
        tracker_handle: TrackerHandle,
        frames: Sequence[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame],
    ) -> List[Event]:
        """Cancel *frames* and drop any pending confirmation they own.

        Returns ``OrderedBlockCancelled`` / ``SkillCancelled`` events; callers
        persist the stack update themselves.
        """
        self._clear_pending_confirmation_for_removed_frames(tracker_handle, frames)
        return self._cancelled_events_for_frames(frames)

    def _reactivate_stacked_same_skill_block(
        self,
        target_flow_id: str,
        tracker_handle: TrackerHandle,
    ) -> bool:
        """Move an existing same-skill path frame to the top.

        Targets ``SkillStackFrame`` (prose), ``OrderedBlockStackFrame``, or
        legacy ``UserFlowStackFrame``. Marks every other same-skill family
        member ``INLINE_REFERENCE``, then appends the target as active again
        (restored prior type, or ``CALL`` / ``REGULAR``), preserving block
        ``step_id``. Stack update only — no digression interrupt/resume events.

        Hybrid stacks keep a prose ``SkillStackFrame`` under an active block.
        ``activate(skill_id)`` must promote that skill frame so parent-skill
        tools become available again (otherwise the LLM stays trapped in the
        block with ``Paused parent skill``).

        Returns:
            ``True`` when the target was found and reactivated; ``False`` otherwise.
        """
        # Work on a copy so we only commit via stack-update events.
        new_stack = tracker_handle.stack.copy()
        frames = list(new_stack.frames)

        # Locate the existing skill / block / user-flow frame (must already
        # be on stack below the top — activate no-ops when it is already top).
        target_index: Optional[int] = None
        target_frame: Optional[
            UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame
        ] = None
        for index, frame in enumerate(frames):
            if (
                isinstance(
                    frame,
                    (UserFlowStackFrame, OrderedBlockStackFrame, SkillStackFrame),
                )
                and target_id_for_frame(frame) == target_flow_id
            ):
                target_index = index
                target_frame = frame
                break
        if target_index is None or target_frame is None:
            return False

        # Pull the target out; remaining frames keep relative order.
        frames.pop(target_index)

        # Mark every other same-skill family member INLINE_REFERENCE
        # (CALL → INLINE_REFERENCE with previous=CALL). Skill frames unchanged
        # when the target is a block; when the target is the skill, sibling
        # blocks park as INLINE_REFERENCE.
        updated_frames: List[Any] = [
            self._mark_same_skill_family_inline(frame, target_flow_id)
            for frame in frames
        ]

        # Reactivate target (must already be below the top — activate
        # no-ops when the flow is already active on top):
        # * Active CALL below top (defensive / legacy sticky) — keep CALL.
        #   previous is cleared while active, so ``previous or REGULAR`` would
        #   wrongly demote it. Before: [caller | main CALL | sub]
        #   → activate(main). After: [caller | sub INLINE | main CALL].
        # * Previously rewritten target — restore previous, else REGULAR.
        #   Before: [caller | main INLINE(prev=CALL) | sub]
        #   → activate(main). After: [caller | sub INLINE | main CALL].
        # * Hybrid prose under a block — promote SkillStackFrame to top.
        #   Before: [Skill REGULAR | Block REGULAR]
        #   → activate(skill_id). After: [Block INLINE | Skill REGULAR].
        if isinstance(target_frame, SkillStackFrame):
            if target_frame.frame_type == MantleStackFrameType.CALL:
                skill_reactivate_type = MantleStackFrameType.CALL
            else:
                skill_reactivate_type = (
                    target_frame.previous_frame_type or MantleStackFrameType.REGULAR
                )
            reactivated_frame: (
                UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame
            ) = SkillStackFrame(
                frame_id=target_frame.frame_id,
                skill_id=target_frame.skill_id,
                frame_type=skill_reactivate_type,
                previous_frame_type=None,
            )
        elif isinstance(target_frame, OrderedBlockStackFrame):
            mantle_reactivate_type = (
                target_frame.previous_frame_type or MantleStackFrameType.REGULAR
            )
            reactivated_frame = OrderedBlockStackFrame(
                frame_id=target_frame.frame_id,
                skill_id=target_frame.skill_id,
                block_id=target_frame.block_id,
                step_id=target_frame.step_id,
                frame_type=mantle_reactivate_type,
                previous_frame_type=None,
            )
        else:
            if target_frame.frame_type == FlowStackFrameType.CALL:
                user_reactivate_type = FlowStackFrameType.CALL
            else:
                user_reactivate_type = (
                    target_frame.previous_frame_type or FlowStackFrameType.REGULAR
                )
            reactivated_frame = self._with_frame_type(
                target_frame,
                user_reactivate_type,
                previous_frame_type=None,
                preserve_previous=False,
            )
        updated_frames.append(reactivated_frame)
        new_stack.frames = updated_frames
        structlogger.debug(
            "mantle.skill_executor.reactivate_stacked_same_skill_block",
            target_flow_id=target_flow_id,
            step_id=catalog_step_id(target_frame),
        )
        tracker_handle.apply_events(
            tracker_handle.create_stack_update_events(new_stack)
        )
        return True

    def _mark_same_skill_family_inline(self, frame: Any, target_flow_id: str) -> Any:
        """Set same-skill family members to ``INLINE_REFERENCE`` under a reactivation.

        Non-family frames and ``SkillStackFrame`` are returned unchanged.
        Same-skill ordered blocks / legacy user-flows (including ``CALL``)
        become ``INLINE_REFERENCE``, remembering the prior active type in
        ``previous_frame_type``.
        """
        if isinstance(frame, OrderedBlockStackFrame):
            target_skill = self._skill_catalog.owning_skill_for_target_id(
                target_flow_id
            )
            if target_skill is None or frame.skill_id != target_skill.id:
                return frame
            return park_frame(frame, FlowStackFrameType.INLINE_REFERENCE)
        if not isinstance(frame, UserFlowStackFrame):
            return frame
        if not self._skill_catalog.is_same_inline_family(frame.flow_id, target_flow_id):
            return frame
        return park_frame(frame, FlowStackFrameType.INLINE_REFERENCE)

    def _frame_was_call(
        self,
        frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
    ) -> bool:
        """True if *frame* is ``CALL``, or parked with ``previous=CALL``."""
        if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
            return (
                frame.frame_type == MantleStackFrameType.CALL
                or frame.previous_frame_type == MantleStackFrameType.CALL
            )
        return (
            frame.frame_type == FlowStackFrameType.CALL
            or frame.previous_frame_type == FlowStackFrameType.CALL
        )

    def _frames_share_skill_family(
        self,
        left: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
        right: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
    ) -> bool:
        """Return whether *left* and *right* belong to the same skill family."""
        left_skill = owning_skill_id_for_frame(self._skill_catalog, left)
        right_skill = owning_skill_id_for_frame(self._skill_catalog, right)
        if left_skill is not None and left_skill == right_skill:
            return True
        if isinstance(left, UserFlowStackFrame) and isinstance(
            right, UserFlowStackFrame
        ):
            return self._skill_catalog.is_same_inline_family(
                left.flow_id, right.flow_id
            )
        return False

    def _should_teardown_family_after_cancel(
        self,
        deepest_cancelled: UserFlowStackFrame
        | SkillStackFrame
        | OrderedBlockStackFrame,
        new_top: DialogueStackFrame,
    ) -> bool:
        """Return whether remaining frames are parked family of *deepest_cancelled*."""
        if not isinstance(
            new_top,
            (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
        ):
            return False
        if not self._frames_share_skill_family(deepest_cancelled, new_top):
            return False
        if isinstance(new_top, UserFlowStackFrame):
            return new_top.frame_type in (
                FlowStackFrameType.INLINE_REFERENCE,
                FlowStackFrameType.CALL,
            )
        if isinstance(new_top, SkillStackFrame):
            return new_top.frame_type in (
                MantleStackFrameType.INLINE_REFERENCE,
                MantleStackFrameType.CALL,
            )
        return True

    def _pop_owning_skill_if_present(
        self,
        new_stack: DialogueStack,
        cancelled_frames: List[
            UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
        ],
        skill_id: Optional[str],
    ) -> None:
        """Pop a same-skill ``SkillStackFrame`` sitting under a cancelled block."""
        if skill_id is None or new_stack.is_empty():
            return
        below = new_stack.top()
        if isinstance(below, SkillStackFrame) and below.skill_id == skill_id:
            new_stack.pop()
            cancelled_frames.append(below)

    def _frame_is_call_type(
        self,
        frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
    ) -> bool:
        """True if *frame* is currently ``CALL`` (unlike :meth:`_frame_was_call`)."""
        if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
            return frame.frame_type == MantleStackFrameType.CALL
        return frame.frame_type == FlowStackFrameType.CALL

    def _pop_next_caller_to_cancel(
        self,
        new_stack: DialogueStack,
        cancelled_frames: List[
            UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
        ],
    ) -> tuple[
        bool,
        Optional[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame],
    ]:
        """Pop the next caller while abandoning the chain after a wiped ``CALL`` family.

        Returns ``(True, None)`` if a ``CALL`` was popped (keep walking);
        ``(False, owning_frame)`` if a non-``CALL`` owner was popped;
        ``(False, None)`` if top is interrupt / non-path (nothing popped).
        """
        top = new_stack.top()
        if is_parked_frame(top):
            return False, None
        if isinstance(top, SkillStackFrame):
            new_stack.pop()
            cancelled_frames.append(top)
            if self._frame_is_call_type(top):
                return True, None
            return False, top
        if isinstance(top, OrderedBlockStackFrame):
            new_stack.pop()
            cancelled_frames.append(top)
            if self._frame_is_call_type(top):
                return True, None
            self._pop_owning_skill_if_present(new_stack, cancelled_frames, top.skill_id)
            return False, top
        if not isinstance(top, UserFlowStackFrame):
            return False, None
        new_stack.pop()
        cancelled_frames.append(top)
        if self._frame_is_call_type(top):
            return True, None
        return False, top

    _CALL_LINK_INLINE_FRAME_TYPES = (
        FlowStackFrameType.CALL,
        FlowStackFrameType.LINK,
        FlowStackFrameType.INLINE_REFERENCE,
    )

    @staticmethod
    def _user_frame_is_call_link_or_inline(frame: UserFlowStackFrame) -> bool:
        """True for call/link/inline activation frames (not plain digressions).

        Opposite of a tangent (``REGULAR`` / ``INTERRUPT`` with
        ``previous=REGULAR``). Includes ``INTERRUPT`` parked via
        :func:`park_frame` with ``previous_frame_type`` preserved.
        """
        if frame.frame_type in SkillExecutor._CALL_LINK_INLINE_FRAME_TYPES:
            return True
        return (
            frame.frame_type == FlowStackFrameType.INTERRUPT
            and frame.previous_frame_type in SkillExecutor._CALL_LINK_INLINE_FRAME_TYPES
        )

    @staticmethod
    def _with_frame_type(
        frame: UserFlowStackFrame,
        frame_type: FlowStackFrameType,
        *,
        previous_frame_type: Optional[FlowStackFrameType] = None,
        preserve_previous: bool = True,
    ) -> UserFlowStackFrame:
        """Return a copy of *frame* with a new ``frame_type``.

        Legacy ``UserFlowStackFrame`` helper only — Mantle park/resume uses
        :func:`park_frame` on skill/block frames. Kept while historical or
        in-flight flow cursors may still appear on the stack.

        By default keeps ``previous_frame_type``. Pass
        ``preserve_previous=False`` to set or clear it via *previous_frame_type*
        (``None`` clears).
        """
        resolved_previous = (
            frame.previous_frame_type if preserve_previous else previous_frame_type
        )
        return UserFlowStackFrame(
            frame_id=frame.frame_id,
            flow_id=frame.flow_id,
            step_id=frame.step_id,
            skill_id=frame.skill_id,
            frame_type=frame_type,
            previous_frame_type=resolved_previous,
            suspended_agent_frames=frame.suspended_agent_frames,
        )

    def _park_top_before_push(
        self,
        new_stack: DialogueStack,
        events: List[Event],
        *,
        park_type: FlowStackFrameType,
        activated_flow_id: str,
        first_step: str,
        skill_id: Optional[str],
    ) -> tuple[DialogueStack, List[Event]]:
        """Park or interrupt the current top before pushing a new frame.

        Called from :meth:`_activate` when *park_type* is ``INTERRUPT`` or
        ``INLINE_REFERENCE``. Returns the updated stack and event list.

        * ``INTERRUPT`` — digression park via :meth:`_park_top_as_interrupted`
          (``CALL`` tops become ``INTERRUPT`` with ``previous=CALL``).
        * ``INLINE_REFERENCE`` — silent same-skill park (``CALL`` tops become
          ``INLINE_REFERENCE`` with ``previous=CALL``).
        """
        current_top = new_stack.top()
        if current_top is None:
            return new_stack, events
        if isinstance(current_top, SkillStackFrame):
            # Same-skill INLINE parks blocks only; bare skill tops stay regular.
            if park_type != FlowStackFrameType.INTERRUPT:
                return new_stack, events
        elif not isinstance(current_top, (UserFlowStackFrame, OrderedBlockStackFrame)):
            # Pattern/search/etc. — not a Mantle skill-path cursor.
            return new_stack, events
        # Skill (INTERRUPT), OrderedBlock, or UserFlow: park/interrupt below.
        # UserFlowStackFrame is transitional for historical / in-flight cursors;
        # activate itself never pushes that type.

        if park_type == FlowStackFrameType.INTERRUPT:
            # Attach digression metadata on SkillInterrupted for the eval report
            # (skipped for cannot_help / unsupported-request handler).
            interrupt_metadata = None
            if should_record_digression(target_skill_id=skill_id):
                interrupt_metadata = DigressionMetadata(
                    to_flow_id=activated_flow_id,
                    to_step_id=first_step,
                    to_skill_id=skill_id,
                ).as_event_metadata()
            new_stack, events, _interrupted = self._park_top_as_interrupted(
                new_stack, events, interrupt_metadata=interrupt_metadata
            )
            return new_stack, events

        new_stack.update(park_frame(current_top, park_type))
        parked_flow_id = (
            current_top.flow_id
            if isinstance(current_top, UserFlowStackFrame)
            else target_id_for_frame(current_top)
        )
        structlogger.debug(
            "mantle.skill_executor.activate.inline_reference",
            parked_flow_id=parked_flow_id,
            activated_flow_id=activated_flow_id,
        )
        return new_stack, events

    def _park_top_as_interrupted(
        self,
        new_stack: DialogueStack,
        events: List[Event],
        interrupt_metadata: Optional[Dict[str, Any]] = None,
    ) -> tuple[
        DialogueStack,
        List[Event],
        Optional[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame],
    ]:
        """Rewrite the top user frame to ``INTERRUPT`` and record ``SkillInterrupted``.

        Returns the updated stack, event list, and the interrupted frame (or
        ``None`` when the top is not a user flow). Shared by ``activate``
        digressions and the post-knowledge resume offer so both park a skill
        the same way.

        Stores the prior active type in ``previous_frame_type`` so a
        ``CALL`` callee can be restored or cancel-walked after the digression.

        *interrupt_metadata* is stamped on the ``SkillInterrupted`` event. The
        activate digression path passes digression metadata for the eval
        report (see :func:`should_record_digression`); the post-knowledge park
        passes ``None`` — a knowledge aside is not a flow-to-flow task switch and
        so is not recorded as a digression.
        """
        current_top = new_stack.top()
        if current_top is None or not isinstance(
            current_top,
            (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
        ):
            return new_stack, events, None
        interrupted_frame = park_frame(current_top, FlowStackFrameType.INTERRUPT)
        new_stack.update(interrupted_frame)
        park_hybrid_skill_wrapper(new_stack.frames, current_top)
        events = [
            *events,
            *self._events_for_interrupting_frame(
                current_top, interrupt_metadata=interrupt_metadata
            ),
        ]
        return new_stack, events, interrupted_frame

    def _events_for_interrupting_frame(
        self,
        frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
        interrupt_metadata: Optional[Dict[str, Any]] = None,
    ) -> List[Event]:
        """Return interrupt events for *frame* without mutating the stack.

        Block ends before the skill wrapper: ``OrderedBlockInterrupted`` first,
        then ``SkillInterrupted``. Digression metadata lives on
        ``SkillInterrupted``.
        """
        events: List[Event] = []
        skill_id = owning_skill_id_for_frame(self._skill_catalog, frame)
        block_id = self._authored_block_id(frame)
        step_id = catalog_step_id(frame)
        if skill_id is not None and block_id is not None:
            events.append(
                OrderedBlockInterrupted(
                    skill_id=skill_id,
                    block_id=block_id,
                    step_id=step_id,
                )
            )
        if skill_id is not None:
            events.append(
                SkillInterrupted(
                    skill_id=skill_id,
                    step_id=step_id,
                    metadata=interrupt_metadata,
                )
            )
        return events

    def should_park_active_skill(self, tracker_handle: TrackerHandle) -> bool:
        """Whether there is a genuine skill to park after a knowledge answer.

        Pure predicate — reads the stack but does not mutate it, so the
        orchestrator can decide whether to park before it commits to the
        stack-changing :meth:`park_active_skill_and_offer_resume`.

        ``True`` only for a ``REGULAR`` non-default active frame without a
        pending tool confirmation. ``False`` in routing mode (no active frame),
        for an already-``INTERRUPT`` frame, or for a lifecycle default (including
        the resume prompt itself).
        """
        frame = tracker_handle.active_frame
        return (
            frame is not None
            and frame.frame_type
            in (FlowStackFrameType.REGULAR, MantleStackFrameType.REGULAR)
            and lifecycle_skill_id_for_frame(self._skill_catalog, frame) is None
            and tracker_handle.pending_tool_confirmation_for_active_frame() is None
        )

    def park_active_skill_and_offer_resume(self, tracker_handle: TrackerHandle) -> None:
        """Park the active skill and offer to resume it after a knowledge answer.

        Mirrors a skill digression: mark the active skill ``INTERRUPT`` and
        activate ``default_continue_interrupted`` so the user is asked whether to
        continue the task they were in (the orchestrator calls this once the
        agent has answered an informational ``search_knowledge`` query).

        Precondition: :meth:`should_park_active_skill` is ``True`` — the caller
        checks that separately so this method only ever performs the stack
        mutation, never the decision.

        A knowledge aside is treated exactly like a skill digression, including
        when it happens on top of already-suspended parents: declining the resume
        prompt dismisses all suspended frames, matching the existing nested-
        digression decline behaviour (see ``_dismiss_suspended``).
        """
        events: List[Event] = []
        new_stack = tracker_handle.stack.copy()
        new_stack, events, interrupted = self._park_top_as_interrupted(
            new_stack, events
        )
        if interrupted is None:
            return
        events.extend(tracker_handle.create_stack_update_events(new_stack))
        tracker_handle.apply_events(events)

        self._offer_continue_interrupted(interrupted, tracker_handle)

    def _cancel_digressions_above_and_resume_target(
        self,
        *,
        target_index: int,
        flow_id: str,
        tracker_handle: TrackerHandle,
    ) -> str:
        """Park the live skill, drop lifecycle prompts, then resume the span.

        The span is the matched frame plus the same-skill skill or block
        attached to it. A normal skill above that span is parked
        (``INTERRUPT``) and stays under the span, including a hybrid pair and
        a half-parked wrapper that was still ``REGULAR``. Lifecycle defaults
        (the continue prompt, wrap-up) are cancelled. A ``REGULAR`` cursor of
        the skill being resumed is cancelled so the span is not split from
        its own block. Sibling ``INTERRUPT`` frames stay. The top frame is
        then resumed.

        Returns the tool result describing whether a live skill was paused,
        a user digression was cancelled, or other paused tasks were kept.
        """
        events: List[Event] = []
        new_stack = tracker_handle.stack.copy()
        frames = list(new_stack.frames)
        span_start, span_end = family_span_bounds(frames, target_index)
        below = frames[:span_start]
        span = frames[span_start:span_end]
        above = frames[span_end:]
        target_skill_id = span_owner_skill_id(self._skill_catalog, span)

        frames_to_cancel, frames_to_interrupt, parked = (
            rehome_frames_above_resume_target(
                above,
                catalog=self._skill_catalog,
                target_skill_id=target_skill_id,
            )
        )
        for frame in frames_to_interrupt:
            events.extend(self._events_for_interrupting_frame(frame))
        if frames_to_cancel:
            events.extend(self._cancel_frames(tracker_handle, frames_to_cancel))

        new_stack.frames = below + above + span
        events.extend(tracker_handle.create_stack_update_events(new_stack))
        tracker_handle.apply_events(events)

        active_frame = tracker_handle.active_frame
        if active_frame is not None:
            self._resume_interrupted_frame(active_frame, tracker_handle)

        structlogger.debug(
            "mantle.skill_executor.try_resume_suspended_flow_in_place.resumed",
            flow_id=flow_id,
            cancelled_above=len(frames_to_cancel),
            parked_live_skill=parked,
            event_info=(
                "Resume-in-place handled: parked the live skill, cancelled "
                "lifecycle prompts, kept sibling INTERRUPT frames, and resumed "
                "the suspended flow."
            ),
        )
        return resume_in_place_tool_result(
            flow_id,
            parked_live_skill=parked,
            cancelled_user_digression=any(
                lifecycle_skill_id_for_frame(self._skill_catalog, frame) is None
                for frame in frames_to_cancel
            ),
            kept_paused_task=self._stack_keeps_paused_user_task(tracker_handle),
        )

    def _stack_keeps_paused_user_task(self, tracker_handle: TrackerHandle) -> bool:
        """Return whether a non-lifecycle ``INTERRUPT`` frame is still stacked."""
        for frame in tracker_handle.stack.frames:
            if not isinstance(
                frame,
                (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
            ):
                continue
            if frame.frame_type not in (
                FlowStackFrameType.INTERRUPT,
                MantleStackFrameType.INTERRUPT,
            ):
                continue
            if lifecycle_skill_id_for_frame(self._skill_catalog, frame) is not None:
                continue
            return True
        return False

    def _try_resume_suspended_flow_in_place(
        self, flow_id: str, tracker_handle: TrackerHandle
    ) -> Optional[str]:
        """Try to resume a flow already parked (suspended) deeper in the stack.

        When the model re-issues ``activate`` for a task the user had
        digressed away from, treat it as *returning* to that task rather than
        starting a new one. A live user skill above the target is parked
        (``INTERRUPT``) and kept on the stack so it can be continued later.
        Lifecycle defaults above the target, including
        ``default_continue_interrupted``, are cancelled so the prompt itself
        does not linger (ENG-3020). Sibling ``INTERRUPT`` frames stay parked
        (ENG-3347). The target is lifted to the top and resumed in place
        (``SkillResumed``).

        Args:
            flow_id: The flow the LLM asked to (re)activate.
            tracker_handle: Live tracker wrapper for this turn.

        Returns:
            A short status note when resume-in-place was handled. ``None`` means
            this helper did *not* act — the caller must fall through to normal
            ``activate`` validation/promotion (not resume the suspended
            frame). That happens when there is no matching ``INTERRUPT`` frame,
            a non-user frame sits above the target, or a call/link/inline user
            frame sits above the target (see
            :meth:`_user_frame_is_call_link_or_inline`) — those must not be
            force-closed here.
        """
        frames = tracker_handle.stack.frames
        target_index = self._index_of_resume_target(frames, flow_id)
        if target_index is None:
            # No matching INTERRUPT frame — defer to normal activate path.
            structlogger.debug(
                "mantle.skill_executor.try_resume_suspended_flow_in_place.deferred.no_matching_interrupt",
                flow_id=flow_id,
                event_info=(
                    "Deferred resume-in-place: no INTERRUPT frame for this "
                    "flow_id; caller falls through to activate validation."
                ),
            )
            return None

        frames_above = frames[target_index + 1 :]
        if any(self._frame_blocks_resume_in_place(frame) for frame in frames_above):
            structlogger.debug(
                "mantle.skill_executor.try_resume_suspended_flow_in_place.deferred.blocked_frame_above",
                flow_id=flow_id,
                event_info=(
                    "Deferred resume-in-place: a call, inline, or non-user "
                    "frame sits above the target; caller falls through to "
                    "activate validation."
                ),
            )
            return None

        return self._cancel_digressions_above_and_resume_target(
            target_index=target_index,
            flow_id=flow_id,
            tracker_handle=tracker_handle,
        )

    def _interrupt_frame_matches_activation(
        self, frame: DialogueStackFrame, flow_id: str
    ) -> bool:
        """Return whether *frame* is the interrupted task *flow_id* refers to."""
        if isinstance(frame, UserFlowStackFrame):
            return (
                frame.frame_type == FlowStackFrameType.INTERRUPT
                and frame.flow_id == flow_id
            )
        if isinstance(frame, SkillStackFrame):
            return frame.frame_type == MantleStackFrameType.INTERRUPT and flow_id in {
                frame.skill_id,
                target_id_for_frame(frame),
            }
        if not isinstance(frame, OrderedBlockStackFrame):
            return False
        if frame.frame_type != MantleStackFrameType.INTERRUPT:
            return False
        # Skill id matches the skill wrapper only. A block matches its compiled
        # target (or the owning block id), not the parent skill id.
        if flow_id == target_id_for_frame(frame):
            return True
        owning = self._skill_catalog.owning_skill_for_target_id(flow_id)
        block_id = self._skill_catalog.ordered_block_id_for_target(flow_id)
        return (
            owning is not None
            and block_id is not None
            and frame.skill_id == owning.id
            and frame.block_id == block_id
        )

    def _index_of_resume_target(
        self,
        frames: Sequence[DialogueStackFrame],
        flow_id: str,
    ) -> Optional[int]:
        """Return the frame ``activate(flow_id)`` should resume.

        Prefers a parked ``INTERRUPT`` frame. When same-skill inline blocks
        sit between that skill and its parked block, the block is the target
        so ``activate(skill)`` lifts the family the same way ``activate(block)``
        does. Older stacks parked only the block and left the skill
        ``REGULAR`` or ``CALL``; that block is the target so the skill frame
        moves with it.
        """
        for index in range(len(frames) - 1, -1, -1):
            if self._interrupt_frame_matches_activation(frames[index], flow_id):
                block_index = resume_block_above_inline_span(frames, index)
                return block_index if block_index is not None else index
        for index in range(len(frames) - 1, 0, -1):
            if self._is_half_parked_block_for_skill(frames, index, flow_id):
                return index
        return None

    @staticmethod
    def _is_half_parked_block_for_skill(
        frames: Sequence[DialogueStackFrame],
        index: int,
        flow_id: str,
    ) -> bool:
        """Return whether *index* is a paused block under a still-active wrapper.

        The wrapper was not parked with the block, so it is ``REGULAR`` or
        ``CALL`` rather than ``INTERRUPT``. Same-skill ``INLINE_REFERENCE``
        blocks may sit between the wrapper and the block. A same-skill
        ``call:`` also leaves the caller block ``REGULAR`` or ``CALL`` in
        between; that caller is part of the run being resumed.
        """
        block = frames[index]
        if not isinstance(block, OrderedBlockStackFrame):
            return False
        if block.frame_type != MantleStackFrameType.INTERRUPT:
            return False
        if block.skill_id != flow_id:
            return False
        if block.previous_frame_type == MantleStackFrameType.INLINE_REFERENCE:
            return False
        under_block = skill_wrapper_below_call_chain(frames, index)
        if under_block is None:
            return False
        _wrapper_index, wrapper = under_block
        return wrapper.frame_type in (
            MantleStackFrameType.REGULAR,
            MantleStackFrameType.CALL,
        )

    def _frame_blocks_resume_in_place(self, frame: DialogueStackFrame) -> bool:
        """Return whether resume-in-place must not force-close *frame*."""
        if isinstance(frame, UserFlowStackFrame):
            return self._user_frame_is_call_link_or_inline(frame)
        if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
            call_or_inline = (
                MantleStackFrameType.CALL,
                MantleStackFrameType.INLINE_REFERENCE,
            )
            return (
                frame.frame_type in call_or_inline
                or frame.previous_frame_type in call_or_inline
            )
        return True

    def _complete_skill(self, tracker_handle: TrackerHandle) -> None:
        """Pop the active frame and emit its completion events.

        Skill-level completions also append ``SkillCompleted`` (not ordered
        blocks / other internal frames). A blocks-only skill also ends when
        the popped block was its last ordered-block frame, so a block
        reached by same-skill ``link:`` finishes the skill.

        Post-completion routing (defaults first — project flows override on
        duplicate IDs):

        * **Empty stack + non-default flow** → activate ``default_completed``
          to ask if the user needs further help.
        * **INLINE_REFERENCE frame on top after completing a sub-flow** →
          restore that parked same-skill block/main to ``REGULAR`` (LIFO;
          silent same-skill block park ends — no digression resume prompt).
        * **INLINE_REFERENCE internal sub-flow(s) left after completing
          main** → cancel **every** unfinished parked same-skill sub-flow
          (do not revive any of them).
        * **INTERRUPT frame on top + ``default_continue_interrupted``
          just completed** → check ``wants_to_resume`` memory entry:
            - Truthy → transition interrupted frame back to ``REGULAR``
              (resume), emit ``SkillResumed``.
            - Falsy → dismiss all interrupted frames.
        * **INTERRUPT frame on top + ``default_unsupported_request_handler``
          just completed**
          → resume the interrupted parent directly (scope digressions should
          return to the paused task without a separate resume prompt).
        * **INTERRUPT frame on top + other flow just completed** → activate
          ``default_continue_interrupted`` to offer the resume choice.
        * **No INTERRUPT frame** → nothing; stack stands as-is.
        """
        new_stack = tracker_handle.stack.copy()
        if new_stack.is_empty():
            structlogger.warning("mantle.skill_executor.complete_skill.no_active_frame")
            return

        popped = new_stack.pop()
        if not isinstance(
            popped, (UserFlowStackFrame, OrderedBlockStackFrame, SkillStackFrame)
        ):
            structlogger.warning("mantle.skill_executor.complete_skill.non_user_frame")
            return

        compiled_flow_id = target_id_for_frame(popped)
        last_block = self._completing_last_blocks_only_block(new_stack, popped)
        self._remove_block_only_skill_wrapper(new_stack, popped, last_block=last_block)

        tracker_handle.clear_pending_tool_confirmation_if_owned_by(
            frame_id=popped.frame_id,
            skill_id=popped.skill_id,
        )

        events: List[Event] = []
        completed_skill_id = owning_skill_id_for_frame(self._skill_catalog, popped)
        completed_block_id = self._authored_block_id(popped)
        # Block ends before the skill wrapper: OrderedBlockCompleted first,
        # then SkillCompleted.
        if completed_skill_id is not None and completed_block_id is not None:
            events.append(
                OrderedBlockCompleted(
                    skill_id=completed_skill_id,
                    block_id=completed_block_id,
                    step_id=catalog_step_id(popped),
                )
            )
        if completed_skill_id is not None and (
            last_block
            or self._should_emit_skill_completed(compiled_flow_id, completed_skill_id)
        ):
            events.append(SkillCompleted(skill_id=completed_skill_id))
        events.extend(tracker_handle.create_stack_update_events(new_stack))
        tracker_handle.apply_events(events)

        if self._try_finish_precondition_resolution(popped, tracker_handle):
            return

        # ── Post-completion routing ───────────────────────────────────────

        if new_stack.is_empty():
            # Empty stack: start default_completed for non-default user flows.
            self._activate_default_completed_for(popped, tracker_handle)
            return

        if isinstance(
            popped, (UserFlowStackFrame, OrderedBlockStackFrame, SkillStackFrame)
        ) and self._handle_complete_inline_family(
            popped, new_stack.top(), tracker_handle
        ):
            return

        new_top = tracker_handle.stack.top()
        if not (
            isinstance(
                popped,
                (UserFlowStackFrame, OrderedBlockStackFrame, SkillStackFrame),
            )
            and isinstance(
                new_top,
                (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
            )
            and new_top.frame_type
            in (FlowStackFrameType.INTERRUPT, MantleStackFrameType.INTERRUPT)
        ):
            return  # Revealed top is not INTERRUPT — no digression routing.

        self._route_complete_interrupt(popped, new_top, tracker_handle)

    def _completing_last_blocks_only_block(
        self,
        new_stack: DialogueStack,
        popped: UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame,
    ) -> bool:
        """Return whether *popped* was the last block of a blocks-only skill.

        A ``link:`` to another block of the same skill leaves that block as
        the one still running. Finishing it ends the skill, because no entry
        frame remains underneath to resume.
        """
        if not isinstance(popped, OrderedBlockStackFrame):
            return False
        skill = self._skill_catalog.skill_by_id(popped.skill_id)
        if skill is None or skill_has_prose(skill):
            return False
        return not any(
            isinstance(frame, OrderedBlockStackFrame)
            and frame.skill_id == popped.skill_id
            for frame in new_stack.frames
        )

    def _remove_block_only_skill_wrapper(
        self,
        new_stack: DialogueStack,
        popped: UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame,
        *,
        last_block: bool = False,
    ) -> List[SkillStackFrame]:
        """Drop the skill frames under *popped* when the skill has nothing left.

        A block-only skill runs entirely inside its ordered blocks; the
        ``SkillStackFrame`` beneath has no prose step to fall back to, so
        leaving it would park the stack on a frame no catalog entry resolves.
        Hybrid skills keep their prose frame. *last_block* covers a block
        reached by same-skill ``link:``, which is not the entry.

        Returns:
            The removed skill frames, top-most first, so callers can emit
            lifecycle events for them.
        """
        if not isinstance(popped, OrderedBlockStackFrame):
            return []
        if not last_block and not self._is_skill_level_target(
            target_id_for_frame(popped), popped.skill_id
        ):
            return []

        def _is_wrapper(frame: DialogueStackFrame) -> bool:
            return (
                isinstance(frame, SkillStackFrame) and frame.skill_id == popped.skill_id
            )

        wrappers = [frame for frame in new_stack.frames if _is_wrapper(frame)]
        new_stack.frames = [
            frame for frame in new_stack.frames if not _is_wrapper(frame)
        ]
        return list(reversed(wrappers))

    def _handle_complete_inline_family(
        self,
        completed_frame: UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame,
        new_top: Any,
        tracker_handle: TrackerHandle,
    ) -> bool:
        """Handle same-family ``INLINE_REFERENCE`` left after a completion pop.

        Returns:
            ``True`` when inline handling finished the turn (caller should
            stop). ``False`` when this was not an inline-family top, or when
            parked subs were cancelled but a digression ``INTERRUPT`` may
            still remain — caller should continue digression routing.
        """
        # Same-family INLINE_REFERENCE left on top after the pop — two cases:
        #
        # 1) Completed a sub-flow → restore what's under it (main or
        #    another same-skill block).
        #    e.g. [B INLINE_REFERENCE | B1 REGULAR] —complete B1→ [B REGULAR]
        #    Then return; the cancel branch below is not reached.
        #
        # 2) Completed the main → cancel parked unfinished subs (do not restore).
        #    e.g. [B1 INLINE | B2 INLINE | B] —complete B→ cancel B1/B2
        completed_flow_id = target_id_for_frame(completed_frame)
        completed_skill_id = owning_skill_id_for_frame(
            self._skill_catalog, completed_frame
        )
        same_inline_family = (
            (
                isinstance(new_top, UserFlowStackFrame)
                and new_top.frame_type == FlowStackFrameType.INLINE_REFERENCE
                and self._skill_catalog.is_same_inline_family(
                    completed_flow_id, new_top.flow_id
                )
            )
            or (
                isinstance(new_top, OrderedBlockStackFrame)
                and new_top.frame_type == MantleStackFrameType.INLINE_REFERENCE
                and new_top.skill_id == completed_skill_id
            )
            or (
                isinstance(new_top, SkillStackFrame)
                and new_top.frame_type == MantleStackFrameType.INLINE_REFERENCE
                and new_top.skill_id == completed_skill_id
            )
        )
        if not same_inline_family:
            return False

        # Case 1: just completed an internal sub-flow.
        if not self._is_skill_level_target(completed_flow_id, completed_skill_id):
            self._restore_inline_reference_frame(new_top, tracker_handle)
            return True

        # Case 2: just completed the main; new_top is a parked sub-flow.
        new_top_flow_id = target_id_for_frame(new_top)
        if not self._skill_catalog.is_internal_target(new_top_flow_id):
            return True

        self._cancel_parked_inline_sub_flows(completed_frame, tracker_handle)
        if tracker_handle.stack.is_empty():
            self._activate_default_completed_for(completed_frame, tracker_handle)
            return True
        # Older digression parent may remain under the wiped family.
        return False

    def _route_complete_interrupt(
        self,
        completed_frame: UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame,
        interrupt_top: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
        tracker_handle: TrackerHandle,
    ) -> None:
        """Route after completion when an ``INTERRUPT`` parent is on top."""
        completed_lifecycle_skill_id = lifecycle_skill_id_for_frame(
            self._skill_catalog, completed_frame
        )
        if completed_lifecycle_skill_id == DEFAULT_CONTINUE_INTERRUPTED:
            wants_to_resume = self._wants_to_resume_value(
                completed_frame, tracker_handle
            )
            if wants_to_resume is True:
                self._resume_interrupted_frame(interrupt_top, tracker_handle)
            elif wants_to_resume is False:
                self._dismiss_interrupt_frames(tracker_handle)
            else:
                self._offer_continue_interrupted(interrupt_top, tracker_handle)
            return

        if completed_lifecycle_skill_id == DEFAULT_UNSUPPORTED_REQUEST_HANDLER:
            # Scope handler is a short deterministic digression; resume the
            # paused task directly instead of routing through continue_interrupted.
            self._resume_interrupted_frame(interrupt_top, tracker_handle)
            return

        # Non-continuation skill completed with interrupt frames → offer choice.
        self._offer_continue_interrupted(interrupt_top, tracker_handle)

    def _wants_to_resume_value(
        self,
        frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
        tracker_handle: TrackerHandle,
    ) -> Optional[bool]:
        """Return the explicit resume decision for a continue-interrupted frame."""
        memory = tracker_handle.memory
        resolved_skill_id, flow_id = memory.resolve_scope(frame)
        skill_id = (
            lifecycle_skill_id_for_frame(self._skill_catalog, frame)
            or resolved_skill_id
        )
        entry = memory.get(skill_id, flow_id, WANTS_TO_RESUME_ENTRY)
        return entry.value if entry is not None else None

    def _cancel_skill(self, tracker_handle: TrackerHandle) -> bool:
        """Abandon the active task, emitting cancel events per cancelled frame.

        Cancels from the top of the stack down to **and including** the first
        non-``CALL`` user flow frame (see :meth:`_cancel_from_top_through_calls`).

        * **``call:`` sub-flow** — a called frame is a ``CALL`` frame that
          belongs to its parent task, so abandoning it walks up and cancels the
          parent chain too (the parent was waiting on the called frame's result).
        * **Digression** — the interrupting flow sits on top as a ``REGULAR``
          frame above the ``INTERRUPT``-marked parent, so the walk stops after
          the digression and leaves the suspended parent in place.

        This method only performs stack bookkeeping — it does not carry a reason
        on the event.

        Post-cancel routing (see :meth:`_route_after_cancel`):

        * **``default_continue_interrupted`` cancelled** (user said "drop it"
          via ``cancel`` instead of ``wants_to_resume=false``) →
          :meth:`_dismiss_interrupt_frames` — abandon the paused parent / hybrid
          family. Do **not** re-offer the resume prompt.
        * **Empty stack** (non-default task) → activate ``default_completed``.
        * **``INLINE_REFERENCE`` or ``CALL`` left on top** (cancelled a
          hybrid-skill family member) → cancel remaining same-family parked
          frames (whole skill abandon). If a wiped frame was or had been
          ``CALL`` (``previous=CALL``), or the walk already cancelled a
          same-family ``CALL`` main under parked ``INLINE`` frames, also
          abandon the outer call chain / owning parent. If the stack is then
          empty → wrap-up; if an older ``INTERRUPT`` digression parent
          remains → offer ``default_continue_interrupted`` for that parent.
        * **``INTERRUPT`` parent left on top** → activate
          ``default_continue_interrupted`` to offer resuming it, matching
          ``_complete_skill``.
        """
        if tracker_handle.active_frame is None:
            structlogger.warning("mantle.skill_executor.cancel_skill.no_active_frame")
            return False

        # Walk from the top down, cancelling CALL frames and the first non-CALL
        # user frame (the owning task). Returns:
        # - deepest_cancelled: that first non-CALL frame (or None)
        # - cancelled_hybrid_call_in_walk: True if a same-family CALL hybrid main
        #   was cancelled before that frame — routing must still abandon the
        #   outer caller (e.g. [caller | sub INLINE | main CALL] → left [caller])
        deepest_cancelled, cancelled_hybrid_call_in_walk = (
            self._cancel_from_top_through_calls(tracker_handle)
        )

        # Declining the resume prompt via cancel must abandon the paused
        # parent stack — same outcome as wants_to_resume=false → _complete_skill.
        # Otherwise _route_after_cancel would re-offer continue_interrupted.
        cancelled_lifecycle_skill_id = (
            lifecycle_skill_id_for_frame(self._skill_catalog, deepest_cancelled)
            if deepest_cancelled is not None
            else None
        )
        if cancelled_lifecycle_skill_id == DEFAULT_CONTINUE_INTERRUPTED:
            self._dismiss_interrupt_frames(tracker_handle)
            return True

        self._route_after_cancel(
            deepest_cancelled,
            tracker_handle,
            cancelled_hybrid_call_in_walk=cancelled_hybrid_call_in_walk,
        )
        return True

    def _cancel_from_top_through_calls(
        self, tracker_handle: TrackerHandle
    ) -> tuple[
        Optional[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame],
        bool,
    ]:
        """Cancel the active frame and any ``call:`` chain it belongs to.

        Walks from the top down, emitting cancel events for each frame,
        until (and including) the first non-``CALL`` user flow frame. ``CALL``
        frames are callees of the frame below them, so cancelling a callee also
        abandons the caller that was waiting on it. A digression on top as
        ``REGULAR`` stops the walk after that frame and leaves a suspended
        ``INTERRUPT`` parent in place.

        Examples below are **this walk only** (not full ``_cancel_skill``).
        Return value is the first non-``CALL`` cancelled. Same-family hybrid
        cleanup (cancel B when b1 was cancelled, then outer caller) happens
        afterwards in :meth:`_route_after_cancel`::

            [A REGULAR | B CALL | b1 REGULAR]  # b1 = inline sub-flow of B
                —walk→ cancels b1; returns b1; left [A | B CALL]
                —route→ wipe B, then A → []

            [A REGULAR | B CALL]
                —walk→ cancels B then A; returns A; left []

            [A REGULAR | B CALL | C CALL]
                —walk→ cancels C, B, then A; returns A; left []

            [A INTERRUPT | digression REGULAR]
                —walk→ cancels digression; returns digression; left [A INTERRUPT]

            # Promoted CALL hybrid main with parked inline sub-flow(s) under it:
            [caller REGULAR | sub INLINE | main CALL]
                —walk→ cancels main then sub; returns sub; left [caller]
                # second return value True → route must still cancel caller

        Returns:
            ``(deepest_cancelled, cancelled_hybrid_call_in_walk)`` where
            *deepest_cancelled* is the first non-``CALL`` cancelled frame (or
            ``None``), and *cancelled_hybrid_call_in_walk* is ``True`` when a
            same-family ``CALL`` hybrid main was cancelled before that frame
            (so post-cancel routing still needs to abandon the outer caller).
        """
        new_stack = tracker_handle.stack.copy()
        events: List[Any] = []
        cancelled_frames: List[
            UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
        ] = []
        deepest_cancelled: Optional[
            UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
        ] = None

        while not new_stack.is_empty():
            top = new_stack.top()
            if isinstance(top, SkillStackFrame):
                new_stack.pop()
                cancelled_frames.append(top)
                tracker_handle.clear_pending_tool_confirmation_if_owned_by(
                    frame_id=top.frame_id,
                    skill_id=top.skill_id,
                )
                if top.frame_type == MantleStackFrameType.CALL:
                    continue
                deepest_cancelled = top
                break
            if isinstance(top, OrderedBlockStackFrame):
                new_stack.pop()
                cancelled_frames.append(top)
                tracker_handle.clear_pending_tool_confirmation_if_owned_by(
                    frame_id=top.frame_id,
                    skill_id=top.skill_id,
                )
                if top.frame_type == MantleStackFrameType.CALL:
                    continue
                deepest_cancelled = top
                self._pop_owning_skill_if_present(
                    new_stack, cancelled_frames, top.skill_id
                )
                break
            if not isinstance(top, UserFlowStackFrame):
                break
            new_stack.pop()
            cancelled_frames.append(top)
            tracker_handle.clear_pending_tool_confirmation_if_owned_by(
                frame_id=top.frame_id,
                skill_id=top.skill_id,
            )
            if top.frame_type != FlowStackFrameType.CALL:
                deepest_cancelled = top
                below = new_stack.top() if not new_stack.is_empty() else None
                if isinstance(
                    below, SkillStackFrame
                ) and below.skill_id == owning_skill_id_for_frame(
                    self._skill_catalog, top
                ):
                    new_stack.pop()
                    cancelled_frames.append(below)
                break

        if not cancelled_frames:
            # Empty stack, or top was not a user flow frame — nothing cancelled.
            return None, False

        events.extend(self._cancelled_events_for_frames(cancelled_frames))

        if deepest_cancelled is None:
            # CALL-only stack (no non-CALL owner) — malformed; still emit
            # the CALL cancellations below, then return None.
            structlogger.warning(
                "mantle.skill_executor.cancel_skill.no_owning_user_frame",
                cancelled=len(cancelled_frames),
            )

        events.extend(tracker_handle.create_stack_update_events(new_stack))
        tracker_handle.apply_events(events)

        # Needed when cancel hits a *promoted* CALL hybrid main (main on top)
        # with parked same-family INLINE sub-flow(s) underneath::
        #
        #   [caller REGULAR | sub… INLINE | main CALL]
        #       —this walk→ cancels main CALL, then first INLINE; left [caller]
        #         (or [caller | remaining INLINE…])
        #
        # Family wipe only sees frames still on the stack, so it never observes
        # that CALL main and would skip outer-caller cleanup. Flag True so
        # _route_after_cancel still cancels *caller*. Not set when cancel starts
        # on an inline child with main INLINE(prev=CALL) parked below — that
        # frame is wiped later and triggers caller cleanup from cancelled_family.
        cancelled_hybrid_call_in_walk = deepest_cancelled is not None and any(
            self._frame_was_call(frame)
            and self._frames_share_skill_family(deepest_cancelled, frame)
            for frame in cancelled_frames
        )
        return deepest_cancelled, cancelled_hybrid_call_in_walk

    def _cancel_owning_parent_after_call_family_wipe(
        self, tracker_handle: TrackerHandle
    ) -> Optional[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame]:
        """Cancel outer callers left after a wiped ``CALL`` hybrid family.

        Cancelling a ``CALL`` callee also abandons its caller chain. Walks from
        the stack top, cancelling through ``CALL`` frames, and stops at the
        first non-``CALL`` owning frame (returned). Leaves ``INTERRUPT``
        digression parents for a resume offer.
        """
        new_stack = tracker_handle.stack.copy()
        cancelled_frames: List[
            UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
        ] = []
        owning_frame: Optional[
            UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
        ] = None

        while not new_stack.is_empty():
            keep_walking, owning_frame = self._pop_next_caller_to_cancel(
                new_stack, cancelled_frames
            )
            if not keep_walking:
                break

        if not cancelled_frames:
            return None

        events: List[Any] = self._cancel_frames(tracker_handle, cancelled_frames)

        if owning_frame is None:
            structlogger.warning(
                "mantle.skill_executor.cancel_owning_parent.no_owning_user_frame",
                cancelled=len(cancelled_frames),
            )

        events.extend(tracker_handle.create_stack_update_events(new_stack))
        tracker_handle.apply_events(events)
        return owning_frame

    def _route_after_cancel(
        self,
        deepest_cancelled: Optional[
            UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
        ],
        tracker_handle: TrackerHandle,
        *,
        cancelled_hybrid_call_in_walk: bool = False,
    ) -> None:
        """Route the conversation after :meth:`_cancel_skill` popped frames.

        Post-cancel routing:

        * empty stack → ``default_completed`` wrap-up (non-default task only);
        * ``INLINE_REFERENCE`` or ``CALL`` same-family top → cancel remaining
          family frames (main and/or parked inline sub-flows) so the hybrid
          skill is abandoned as a whole; when a wiped frame was or had been
          ``CALL`` (``previous=CALL``), or the walk already cancelled a
          same-family ``CALL`` main, also abandon the outer call chain; then
          re-evaluate the (possibly new) stack top. Examples (after the active
          frame was already cancelled)::

              # Cancelled an inline sub-flow → abandon the rest of the family
              deepest=sub-flow, top=[main INLINE]  → wipe main → []
              deepest=sub-flow, top=[caller | main INLINE(prev=CALL)]
                  → wipe main, then caller → []
              deepest=sub-flow, top=[older INTERRUPT | main INLINE]
                  → wipe main → [older INTERRUPT] → resume offer

              # Cancelled promoted CALL main → wipe parked sub-flows, then caller
              deepest=sub-flow, top=[caller | sub INLINE]
                  → wipe sub; CALL already cancelled in walk → cancel caller → []
              deepest=sub-flow, top=[caller]
                  → CALL already cancelled in walk → cancel caller → []

              # Cancelled main → wipe parked sub-flows still below
              deepest=main, top=[sub-flow INLINE]  → wipe sub-flow(s) → []

        * a genuine suspended (``INTERRUPT``) parent → offer
          ``default_continue_interrupted``, falling back to a direct resume when
          the default flow is not loaded.

        Hybrid wipe and digression resume are sequential: abandoning an inline
        family that was started as a digression can reveal an older ``INTERRUPT``
        parent that still needs a resume offer.
        """
        new_stack = tracker_handle.stack

        if new_stack.is_empty():
            self._activate_default_completed_for(deepest_cancelled, tracker_handle)
            return

        new_top = new_stack.top()  # Frame revealed after cancel popped the active one.
        if deepest_cancelled is not None and self._should_teardown_family_after_cancel(
            deepest_cancelled, new_top
        ):
            # Cancel any frame in a hybrid skill abandons the whole skill:
            # the active frame is already gone; wipe remaining parked family.
            # e.g. [main INLINE | sub REGULAR] —cancel sub→ [] (main wiped too)
            # or [older INTERRUPT | main INLINE | sub] —cancel sub→ [older INTERRUPT]
            # or [A REGULAR | main CALL | sub] —cancel sub→ wipe main, then A → []
            if self._teardown_inline_family_after_cancel(
                deepest_cancelled,
                tracker_handle,
                call_main_already_cancelled=cancelled_hybrid_call_in_walk,
            ):
                return  # Stack empty — wrap-up already activated.
            new_top = tracker_handle.stack.top()
        elif cancelled_hybrid_call_in_walk and deepest_cancelled is not None:
            # Walk cancelled CALL main + the first INLINE under it; no family left
            # on top (only the outer caller). Still abandon that caller.
            # e.g. [caller | sub INLINE | main CALL] —cancel→ [caller] —here→ []
            owning_parent = self._cancel_owning_parent_after_call_family_wipe(
                tracker_handle
            )
            if tracker_handle.stack.is_empty():
                self._activate_default_completed_for(
                    owning_parent or deepest_cancelled, tracker_handle
                )
                return
            new_top = tracker_handle.stack.top()

        if not (
            isinstance(
                new_top,
                (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
            )
            and new_top.frame_type
            in (FlowStackFrameType.INTERRUPT, MantleStackFrameType.INTERRUPT)
        ):
            return  # Revealed top is not INTERRUPT — no digression routing.

        # Genuine suspended parent (digression) → offer to resume it.
        self._offer_continue_interrupted(new_top, tracker_handle)

    @staticmethod
    def _interrupted_task_display_name(
        frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
        skill: Optional[Skill],
        catalog: Optional[SkillCatalog] = None,
    ) -> str:
        """Short label for the paused task: normalized ``name`` or humanized id."""
        if skill is not None and skill.name:
            return _normalize_task_display_name(skill.name, skill.id)
        if skill is not None:
            return _humanize_identifier(skill.id)
        if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
            return _humanize_identifier(frame.skill_id)
        if frame.skill_id:
            return _humanize_identifier(frame.skill_id)
        return _humanize_identifier(_skill_id_for_display(frame.flow_id, catalog))

    @staticmethod
    def _interrupted_task_description_hint(
        skill: Optional[Skill], display_name: str
    ) -> str:
        """First-line skill description when it adds context beyond *display_name*."""
        if skill is None or not skill.description:
            return ""
        first_line = skill.description.strip().split("\n", 1)[0].strip().rstrip(".")
        if not first_line or first_line.lower() == display_name.lower():
            return ""
        return first_line

    @staticmethod
    def _interrupted_task_resume_label(
        frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
        skill: Optional[Skill],
        catalog: Optional[SkillCatalog] = None,
    ) -> str:
        """User-facing paused-task label seeded into ``interrupted_task_name``.

        Uses :meth:`_interrupted_task_display_name` plus an optional bracketed
        skill ``description`` when its first line adds context.
        """
        display_name = SkillExecutor._interrupted_task_display_name(
            frame, skill, catalog
        )
        hint = SkillExecutor._interrupted_task_description_hint(skill, display_name)
        if hint:
            return f"{display_name} ({hint})"
        return display_name

    def _offer_continue_interrupted(
        self,
        interrupted_top: (
            UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
        ),
        tracker_handle: TrackerHandle,
    ) -> None:
        """Offer to resume a suspended (``INTERRUPT``) parent frame.

        Activate ``default_continue_interrupted`` so the user is asked whether to
        resume the interrupted task. When that default flow is not loaded (e.g. a
        minimal test setup), auto-resume *interrupted_top* directly instead.

        Shared by :meth:`_complete_skill` and :meth:`_route_after_cancel`.
        """
        # ENG-3020 defense-in-depth: never offer the resume prompt for parked
        # engine default skills (e.g. wrap-up left INTERRUPT after
        # ``cannot_help``). New tasks from ``default_completed`` are handled
        # upstream (#6278); resume any other suspended default silently here.
        interrupted_compiled_id = target_id_for_frame(interrupted_top)
        if (
            lifecycle_skill_id_for_frame(self._skill_catalog, interrupted_top)
            is not None
        ):
            structlogger.debug(
                "mantle.skill_executor.offer_continue_interrupted.skip_default",
                flow_id=interrupted_compiled_id,
            )
            self._resume_interrupted_frame(interrupted_top, tracker_handle)
            return

        continue_entry_id = entry_id_for_skill_id(
            self._skill_catalog, DEFAULT_CONTINUE_INTERRUPTED
        )
        if continue_entry_id is not None:
            self._activate(
                continue_entry_id,
                tracker_handle,
                block_id=self._skill_catalog.ordered_block_id_for_target(
                    continue_entry_id
                ),
            )
            skill = skill_for_stack_frame(self._skill_catalog, interrupted_top)
            task_name = self._interrupted_task_resume_label(
                interrupted_top, skill, self._skill_catalog
            )
            self._seed_interrupted_task_name(
                tracker_handle, task_name, flow_id=continue_entry_id
            )
        else:
            self._resume_interrupted_frame(interrupted_top, tracker_handle)

    @staticmethod
    def _seed_interrupted_task_name(
        tracker_handle: TrackerHandle,
        task_name: str,
        *,
        flow_id: str = DEFAULT_CONTINUE_INTERRUPTED_FLOW_ID,
    ) -> None:
        """Write the paused-task label for the resume prompt; degrade on deny.

        A project override of ``default_continue_interrupted`` may drop
        ``interrupted_task_name`` from ``memory.yml``. Hard-failing would leave
        the user with no resume offer, so denied writes are logged and the
        substitution path falls back to :data:`INTERRUPTED_TASK_NAME_FALLBACK`.
        """
        candidates = (
            (task_name, INTERRUPTED_TASK_NAME_FALLBACK)
            if task_name != INTERRUPTED_TASK_NAME_FALLBACK
            else (INTERRUPTED_TASK_NAME_FALLBACK,)
        )
        for value in candidates:
            try:
                tracker_handle.memory.set(
                    DEFAULT_CONTINUE_INTERRUPTED,
                    flow_id,
                    INTERRUPTED_TASK_NAME_ENTRY,
                    value,
                )
                return
            except MemoryWriteError:
                structlogger.warning(
                    "mantle.skill_executor.continue_interrupted."
                    "task_name_write_failed",
                    attempted=value,
                )
        structlogger.warning(
            "mantle.skill_executor.continue_interrupted.task_name_unavailable",
        )

    def _activate_default_completed_for(
        self,
        popped: Optional[UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame],
        tracker_handle: TrackerHandle,
    ) -> None:
        """Activate ``default_completed`` for a wrapped-up non-default user skill.

        Shared by ``_complete_skill``, ``_cancel_skill``, and
        ``_dismiss_interrupt_frames``: when the stack is empty after a user
        (non-default) skill ends, start the polite "anything else?" wrap-up.
        No-op for default skills or when the wrap-up skill is not loaded.
        """
        completed_entry_id = entry_id_for_skill_id(
            self._skill_catalog, DEFAULT_COMPLETED
        )
        if popped is None or completed_entry_id is None:
            return
        if lifecycle_skill_id_for_frame(self._skill_catalog, popped) is None:
            self._activate(
                completed_entry_id,
                tracker_handle,
                block_id=self._skill_catalog.ordered_block_id_for_target(
                    completed_entry_id
                ),
            )

    def _restore_inline_reference_frame(
        self,
        frame: UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame,
        session: TrackerHandle,
    ) -> None:
        """Restore a parked inline frame after a same-skill block completes.

        Called from :meth:`_complete_skill` when popping an inline sub-flow leaves
        another family member (main or same-skill block) on top as
        ``INLINE_REFERENCE``. Restores ``previous_frame_type`` when set (else
        ``REGULAR``), clears ``previous``, and updates the stack only — no
        ``SkillResumed`` and no ``default_continue_interrupted`` (unlike digression
        resume). LIFO: the frame immediately under the completed sub-flow becomes
        active.
        """
        if isinstance(frame, SkillStackFrame):
            mantle_restored_type = (
                frame.previous_frame_type or MantleStackFrameType.REGULAR
            )
            restored_frame: DialogueStackFrame = SkillStackFrame(
                frame_id=frame.frame_id,
                skill_id=frame.skill_id,
                frame_type=mantle_restored_type,
                previous_frame_type=None,
            )
            restored_frame_type_value = mantle_restored_type.value
        elif isinstance(frame, OrderedBlockStackFrame):
            mantle_restored_type = (
                frame.previous_frame_type or MantleStackFrameType.REGULAR
            )
            restored_frame = OrderedBlockStackFrame(
                frame_id=frame.frame_id,
                skill_id=frame.skill_id,
                block_id=frame.block_id,
                step_id=frame.step_id,
                frame_type=mantle_restored_type,
                previous_frame_type=None,
            )
            restored_frame_type_value = mantle_restored_type.value
        else:
            user_restored_type = frame.previous_frame_type or FlowStackFrameType.REGULAR
            restored_frame = self._with_frame_type(
                frame,
                user_restored_type,
                previous_frame_type=None,
                preserve_previous=False,
            )
            restored_frame_type_value = user_restored_type.value
        restore_stack = session.stack.copy()
        restore_stack.update(restored_frame)
        structlogger.debug(
            "mantle.skill_executor.restore_inline_reference",
            flow_id=target_id_for_frame(frame),
            step_id=catalog_step_id(frame),
            restored_frame_type=restored_frame_type_value,
        )
        session.apply_events(session.create_stack_update_events(restore_stack))

    def _teardown_inline_family_after_cancel(
        self,
        anchor: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
        session: TrackerHandle,
        *,
        call_main_already_cancelled: bool = False,
    ) -> bool:
        """Finish hybrid cancel: wipe parked family, then outer caller if needed.

        Shared by :meth:`_route_after_cancel` and :meth:`_dismiss_interrupt_frames`
        after the active frame is already gone. Cancels remaining same-family
        parked frames; if that included a ``CALL`` hybrid main (or the walk
        already cancelled that ``CALL`` main under parked ``INLINE`` frames),
        also cancels its outer caller. If the stack is then empty, activates
        ``default_completed``.

        Returns:
            ``True`` when wrap-up was activated (stack empty); ``False`` when
            frames remain (e.g. an older ``INTERRUPT`` digression parent).
        """
        # cancels any remaining same-family parked frames still on the stack
        cancelled_family = self._cancel_remaining_inline_family(anchor, session)
        wrap_up_anchor: (
            UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
        ) = anchor
        call_main_abandoned = call_main_already_cancelled or any(
            self._frame_was_call(frame) for frame in cancelled_family
        )
        if call_main_abandoned:
            # Family wipe removed CALL main (or walk already did); cancel caller.
            # e.g. deepest=sub-flow → wipe main CALL → [caller] —here→ []
            # e.g. walk cancelled main CALL + sub2 → wipe sub1 → [caller] —here→ []
            # Keep caller cleanup out of `_cancel_remaining_inline_family`: the
            # outer caller is not part of the inline family.
            owning_parent = self._cancel_owning_parent_after_call_family_wipe(session)
            if owning_parent is not None:
                wrap_up_anchor = owning_parent
        if session.stack.is_empty():
            self._activate_default_completed_for(wrap_up_anchor, session)
            return True
        return False

    def _cancel_remaining_inline_family(
        self,
        anchor: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
        session: TrackerHandle,
    ) -> List[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame]:
        """Cancel every remaining parked frame in *anchor*'s inline family.

        Used by :meth:`_route_after_cancel` after the active frame is already
        gone. Unlike :meth:`_cancel_parked_inline_sub_flows` (complete-main only
        cancels internals), this also cancels a parked **main** so cancelling
        any family member abandons the whole hybrid skill. Examples::

            [main INLINE | sub-flow REGULAR]  —cancel sub-flow→
            []  (main cancelled too)

            [caller REGULAR | main CALL | sub-flow REGULAR]
                —cancel sub-flow (already gone) / this helper→  [caller REGULAR]
                # then _cancel_owning_parent_after_call_family_wipe → []

        Same-family ``INLINE_REFERENCE`` (parked main / same-skill blocks,
        including a hybrid main with ``previous=CALL``) and any still-active
        ``CALL`` hybrid main are cancelled. Returns the cancelled frames
        (empty when nothing matched).
        """
        new_stack = session.stack.copy()
        cancelled: List[
            UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame
        ] = []
        remaining: List[Any] = []
        anchor_skill_id = owning_skill_id_for_frame(self._skill_catalog, anchor)
        for frame in new_stack.frames:
            if isinstance(frame, UserFlowStackFrame) and frame.frame_type in (
                FlowStackFrameType.INLINE_REFERENCE,
                FlowStackFrameType.CALL,
            ):
                same_user_family = isinstance(
                    anchor, UserFlowStackFrame
                ) and self._skill_catalog.is_same_inline_family(
                    anchor.flow_id, frame.flow_id
                )
                same_skill = (
                    anchor_skill_id is not None
                    and owning_skill_id_for_frame(self._skill_catalog, frame)
                    == anchor_skill_id
                )
                if same_user_family or same_skill:
                    cancelled.append(frame)
            elif (
                isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))
                and anchor_skill_id is not None
                and frame.skill_id == anchor_skill_id
            ):
                cancelled.append(frame)
            else:
                remaining.append(frame)
        if not cancelled:
            return []  # No parked same-family members left.
        new_stack.frames = remaining
        structlogger.debug(
            "mantle.skill_executor.cancel_remaining_inline_family",
            anchor_flow_id=target_id_for_frame(anchor),
            cancelled_flow_ids=[target_id_for_frame(frame) for frame in cancelled],
        )
        session.apply_events(
            [
                *self._cancel_frames(session, cancelled),
                *session.create_stack_update_events(new_stack),
            ]
        )
        return cancelled

    def _cancel_parked_inline_sub_flows(
        self,
        completed_main: UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame,
        session: TrackerHandle,
    ) -> None:
        """Cancel every parked same-skill inline sub-flow after main completes.

        Completing the main while unfinished sub-flows remain as
        ``INLINE_REFERENCE`` must not restore them; cancel all matching
        internals so the skill does not leave orphaned sub-flows. Example::

            [sub_a INLINE | sub_b INLINE | main REGULAR]  —complete main→
            []  (both sub-flows cancelled)
        """
        new_stack = session.stack.copy()
        cancelled: List[UserFlowStackFrame | OrderedBlockStackFrame] = []
        remaining: List[Any] = []
        completed_skill_id = owning_skill_id_for_frame(
            self._skill_catalog, completed_main
        )
        completed_flow_id = target_id_for_frame(completed_main)
        for frame in new_stack.frames:
            is_legacy_inline = (
                isinstance(frame, UserFlowStackFrame)
                and frame.frame_type == FlowStackFrameType.INLINE_REFERENCE
                and self._skill_catalog.is_internal_target(frame.flow_id)
                and self._skill_catalog.is_same_inline_family(
                    completed_flow_id, frame.flow_id
                )
            )
            is_block_inline = (
                isinstance(frame, OrderedBlockStackFrame)
                and frame.frame_type == MantleStackFrameType.INLINE_REFERENCE
                and frame.skill_id == completed_skill_id
            )
            if is_legacy_inline or is_block_inline:
                cancelled.append(frame)
            else:
                remaining.append(frame)
        if not cancelled:
            return
        new_stack.frames = remaining
        structlogger.debug(
            "mantle.skill_executor.cancel_parked_inline_sub_flows",
            main_flow_id=completed_flow_id,
            cancelled_flow_ids=[target_id_for_frame(frame) for frame in cancelled],
        )
        session.apply_events(
            [
                *self._cancel_frames(session, cancelled),
                *session.create_stack_update_events(new_stack),
            ]
        )

    @staticmethod
    def _restore_parked_skill_wrapper(
        stack: DialogueStack,
        resumed_block: OrderedBlockStackFrame,
    ) -> None:
        """Restore the skill wrapper parked with *resumed_block*.

        Family park marks the wrapper ``INTERRUPT`` when the block is
        interrupted. Resuming the block (digression complete, or
        ``activate`` of the skill/block) puts that wrapper back to its
        previous active type. ``SkillResumed`` is emitted for the block.
        """
        under_block = interrupted_skill_wrapper_below_block(stack.frames)
        if under_block is None:
            return
        index, wrapper = under_block
        if wrapper.skill_id != resumed_block.skill_id:
            return
        if wrapper.frame_type != MantleStackFrameType.INTERRUPT:
            return
        # Inline parks have their own restore. A ``CALL`` wrapper parked with
        # its block must come back as ``CALL``.
        if wrapper.previous_frame_type == MantleStackFrameType.INLINE_REFERENCE:
            return
        restored = wrapper.previous_frame_type or MantleStackFrameType.REGULAR
        stack.frames[index] = SkillStackFrame(
            frame_id=wrapper.frame_id,
            skill_id=wrapper.skill_id,
            frame_type=restored,
            previous_frame_type=None,
        )

    def _resume_interrupted_frame(
        self,
        frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
        session: TrackerHandle,
    ) -> None:
        """Restore a parked ``INTERRUPT`` frame and emit ``SkillResumed``.

        Restores ``previous_frame_type`` (e.g. ``CALL``) when set; otherwise
        ``REGULAR``. Clears ``previous_frame_type`` once active again.
        """
        if isinstance(frame, SkillStackFrame):
            restored_skill_type = (
                frame.previous_frame_type or MantleStackFrameType.REGULAR
            )
            resumed_frame: DialogueStackFrame = SkillStackFrame(
                frame_id=frame.frame_id,
                skill_id=frame.skill_id,
                frame_type=restored_skill_type,
                previous_frame_type=None,
            )
        elif isinstance(frame, OrderedBlockStackFrame):
            restored_block_type = (
                frame.previous_frame_type or MantleStackFrameType.REGULAR
            )
            resumed_frame = OrderedBlockStackFrame(
                frame_id=frame.frame_id,
                skill_id=frame.skill_id,
                block_id=frame.block_id,
                step_id=frame.step_id,
                frame_type=restored_block_type,
                previous_frame_type=None,
            )
        else:
            restored_type = frame.previous_frame_type or FlowStackFrameType.REGULAR
            resumed_frame = self._with_frame_type(
                frame,
                restored_type,
                previous_frame_type=None,
                preserve_previous=False,
            )
        resume_stack = session.stack.copy()
        resume_stack.update(resumed_frame)
        if isinstance(resumed_frame, OrderedBlockStackFrame):
            self._restore_parked_skill_wrapper(resume_stack, resumed_frame)
        resume_events: List[Event] = []
        resumed_skill_id = owning_skill_id_for_frame(self._skill_catalog, frame)
        if resumed_skill_id is not None:
            resume_events.append(
                SkillResumed(
                    skill_id=resumed_skill_id,
                    step_id=catalog_step_id(frame),
                )
            )
        resumed_block_id = self._authored_block_id(frame)
        if resumed_skill_id is not None and resumed_block_id is not None:
            resume_events.append(
                OrderedBlockResumed(
                    skill_id=resumed_skill_id,
                    block_id=resumed_block_id,
                    step_id=catalog_step_id(frame),
                )
            )
        session.apply_events(
            [
                *resume_events,
                *session.create_stack_update_events(resume_stack),
            ]
        )

    def _dismiss_interrupt_frames(self, session: TrackerHandle) -> None:
        """Cancel digression frames; abandon any hybrid skill left parked.

        Always removes ``INTERRUPT`` frames (declined digression resume).

        If parked same-family ``INLINE_REFERENCE`` / ``CALL`` frames remain,
        cancel them so declining resume abandons the whole hybrid skill (not
        LIFO restore). If a dismissed frame had ``previous_frame_type == CALL``,
        also abandon the outer caller (cancel callee ⇒ cancel caller) — including
        when parked same-skill INLINE blocks were under that CALL main. Examples::

            [main INLINE | pick_card INTERRUPT]  —decline pick_card→
            []  (main cancelled too)

            [caller | sub INLINE | main INTERRUPT(prev=CALL)]  —decline→
            []  (sub + caller cancelled too)

        When the stack is empty after that teardown, activate
        ``default_completed`` (same wrap-up as ``_cancel_skill`` / completing
        the inline main). Emits cancel events for each removed frame, then
        a stack update.
        """
        interrupt_frames = [
            frame
            for frame in session.stack.frames
            if (
                isinstance(frame, UserFlowStackFrame)
                and frame.frame_type == FlowStackFrameType.INTERRUPT
            )
            or (
                isinstance(frame, SkillStackFrame)
                and frame.frame_type == MantleStackFrameType.INTERRUPT
            )
            or (
                isinstance(frame, OrderedBlockStackFrame)
                and frame.frame_type == MantleStackFrameType.INTERRUPT
            )
        ]
        if not interrupt_frames:
            return

        dismissed_call_callee = any(
            self._frame_was_call(frame) for frame in interrupt_frames
        )

        new_stack = session.stack.copy()
        new_stack.frames = [
            frame
            for frame in new_stack.frames
            if not (
                (
                    isinstance(frame, UserFlowStackFrame)
                    and frame.frame_type == FlowStackFrameType.INTERRUPT
                )
                or (
                    isinstance(frame, SkillStackFrame)
                    and frame.frame_type == MantleStackFrameType.INTERRUPT
                )
                or (
                    isinstance(frame, OrderedBlockStackFrame)
                    and frame.frame_type == MantleStackFrameType.INTERRUPT
                )
            )
        ]

        cancel_events: List[Any] = self._cancel_frames(session, interrupt_frames)
        cancel_events.extend(session.create_stack_update_events(new_stack))
        session.apply_events(cancel_events)

        # Declining resume of any hybrid-family member abandons the whole skill.
        # Topmost INTERRUPT is the digression target the user declined.
        wrap_up_anchor = interrupt_frames[-1]
        if session.stack.is_empty():
            self._activate_default_completed_for(wrap_up_anchor, session)
            return

        new_top = session.stack.top()
        # Parked INLINE / CALL same-skill frames may remain under a declined
        # CALL main. Wipe that family first (with call_main_already_cancelled
        # when the dismissed frame was prev=CALL — the CALL/INTERRUPT main is
        # already gone). Teardown also abandons the outer caller when needed.
        # e.g. [caller | sub INLINE | main INTERRUPT(prev=CALL)] —decline→
        #      [caller | sub INLINE] → wipe sub + caller → [].
        if isinstance(
            new_top,
            (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
        ) and self._should_teardown_family_after_cancel(wrap_up_anchor, new_top):
            self._teardown_inline_family_after_cancel(
                wrap_up_anchor,
                session,
                call_main_already_cancelled=dismissed_call_callee,
            )
            return

        # Digression-from-CALL with no hybrid same-skill frames left on top:
        # [caller REGULAR | callee INTERRUPT(prev=CALL)] —decline→ [caller]
        # → abandon caller the same way cancel-callee does.
        if dismissed_call_callee:
            self._abandon_caller_after_dismissed_call_interrupt(session, wrap_up_anchor)

    def _abandon_caller_after_dismissed_call_interrupt(
        self,
        session: TrackerHandle,
        wrap_up_anchor: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
    ) -> None:
        """Abandon the outer caller after declining a CALL digression.

        Used when interrupt dismiss left no same-family hybrid frames on top
        (e.g. ``[caller REGULAR | callee INTERRUPT(prev=CALL)]``). Cancels the
        owning parent, then wraps up with ``default_completed`` or re-offers
        continue if another ``INTERRUPT`` remains.
        """
        self._cancel_owning_parent_after_call_family_wipe(session)
        if session.stack.is_empty():
            self._activate_default_completed_for(wrap_up_anchor, session)
            return

        new_top_after_caller = session.stack.top()
        if is_parked_frame(new_top_after_caller) and isinstance(
            new_top_after_caller,
            (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
        ):
            self._offer_continue_interrupted(new_top_after_caller, session)

    # ------------------------------------------------------------------
    # Step navigation helpers
    # ------------------------------------------------------------------

    def _advance_or_complete(
        self,
        next_field: str | list[NextBranch] | None,
        frame: UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame,
        tracker_handle: TrackerHandle,
    ) -> None:
        """Resolve *next_field* then advance the step pointer or complete the skill.

        Callers that apply events before calling this (e.g.
        ``_handle_set_memory_step``, ``_handle_execute_step``) should pass
        ``tracker_handle.active_frame or frame`` so the updated frame is used
        after any stack mutations.
        """
        next_id = self._resolve_next_skill(next_field, tracker_handle)
        if next_id is None or next_id == END_STEP or isinstance(frame, SkillStackFrame):
            self._complete_skill(tracker_handle)
        else:
            self._advance_step(frame, next_id, tracker_handle)

    def _advance_step(
        self,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
        next_step_id: str,
        session: TrackerHandle,
    ) -> None:
        """Move the active frame's step_id to *next_step_id* and update stack.

        Preserves all existing frame attributes (including ``skill_id``).
        Each call emits exactly one ``DialogueStackUpdated`` event.

        The ``UserFlowStackFrame`` branch only advances a legacy flow cursor
        still on the stack; new Mantle activates never create one
        (see ``_activate`` fail-closed).
        """
        new_stack = session.stack.copy()
        if isinstance(frame, OrderedBlockStackFrame):
            updated_frame: DialogueStackFrame = OrderedBlockStackFrame(
                frame_id=frame.frame_id,
                skill_id=frame.skill_id,
                block_id=frame.block_id,
                step_id=next_step_id,
                frame_type=frame.frame_type,
                previous_frame_type=frame.previous_frame_type,
            )
        else:
            updated_frame = UserFlowStackFrame(
                frame_id=frame.frame_id,
                flow_id=frame.flow_id,
                step_id=next_step_id,
                skill_id=frame.skill_id,
                frame_type=frame.frame_type,
                previous_frame_type=frame.previous_frame_type,
                suspended_agent_frames=frame.suspended_agent_frames,
            )
        new_stack.update(updated_frame)
        session.apply_events(session.create_stack_update_events(new_stack))

    def _resolve_next_skill(
        self,
        next_field: str | list[NextBranch] | None,
        session: TrackerHandle,
    ) -> Optional[str]:
        """Resolve a ``next`` field to a concrete step ID.

        Handles both plain string IDs and conditional :class:`NextBranch` lists.
        Returns ``None`` (treated as END) when *next_field* is ``None`` or an
        empty branch list with no matching branch.
        """
        if next_field is None:
            return None
        if isinstance(next_field, str):
            return next_field
        # list[NextBranch] — evaluate conditions against current memory values.
        return resolve_next(next_field, self.current_memory_values(session))

    def resolve_response_name(
        self,
        response_name: str,
        tracker_handle: TrackerHandle,
        *,
        substitute_placeholders: bool = True,
    ) -> ResolvedUtterance:
        """Resolve a named response to text, rephrase, and delivery-ready buttons.

        Looks up *response_name* in the :class:`ResponseRegistry`, selects the
        matching variant via :meth:`ResponseRegistry.select_variant`, optionally
        substitutes memory placeholders in text and button titles/payloads,
        fills omitted button payloads from the resolved title, and returns
        whether the variant requests LLM rephrasing.

        Pass ``substitute_placeholders=False`` when the caller must rewrite the
        template before memory substitution (for example filling a
        channel-supplied ``{button_title}`` so a real memory entry of that name
        cannot claim the placeholder).

        When ``select_variant`` returns ``None`` — missing name, empty
        variants, or fail-closed CRV selection (every variant conditioned and
        none match / every condition raises
        :class:`~rasa.mantle.skills.conditions.ConditionEvaluationError`) —
        delivery uses the same pre-existing missing-name fallback: utter
        *response_name* as the template text with no rephrase and no buttons.
        """
        definition = self._response_registry.select_variant(
            response_name, self.current_memory_values(tracker_handle)
        )
        buttons: tuple[ResponseButton, ...]
        button_source: str | None
        variant_metadata: dict[str, Any]
        if definition is None:
            structlogger.debug(
                "mantle.skill_executor.response.missing_definition",
                response_name=response_name,
            )
            template = response_name
            rephrase = None
            buttons = ()
            button_source = None
            variant_metadata = {}
        else:
            template = definition.text
            rephrase = NaturalRephrase() if definition.rephrase else None
            buttons = resolve_response_buttons(definition.buttons, tracker_handle)
            button_source = definition.button_source
            variant_metadata = definition.metadata
        structlogger.debug(
            "mantle.skill_executor.response.resolved",
            response_name=response_name,
            found=definition is not None,
            rephrase=rephrase is not None,
            button_count=len(buttons),
        )
        text = (
            substitute_memory_placeholders(template, tracker_handle)
            if substitute_placeholders
            else template
        )
        return ResolvedUtterance(
            text=text,
            rephrase=rephrase,
            buttons=buttons,
            button_source=button_source,
            variant_metadata=variant_metadata,
        )

    async def expand_button_source(
        self,
        response: AgentResponse,
        tracker_handle: TrackerHandle,
    ) -> AgentResponse:
        """Populate buttons from the response's local source tool."""
        source = response.button_source
        if source is None:
            return response
        if response.buttons:
            return response.model_copy(update={"button_source": None})

        live_skill_id, live_flow_id = tracker_handle.memory_scope()
        skill_id = response.button_source_skill_id or live_skill_id
        flow_id = response.button_source_flow_id or live_flow_id
        tool_func = self.tool_funcs.get(skill_id, {}).get(source)
        collides_with_mcp = (
            self.mcp_runtime is not None
            and self.mcp_runtime.has_mcp_tool(skill_id, source)
        )
        if tool_func is None or collides_with_mcp:
            structlogger.warning(
                "mantle.dynamic_buttons.source_unavailable",
                skill_id=skill_id,
                source=source,
                collides_with_mcp=collides_with_mcp,
            )
            return response.model_copy(update={"button_source": None})

        invocation_scope = (skill_id, flow_id) if skill_id else None
        with capture_source_buttons():
            result = await self.call_tool_func(
                tool_func,
                source,
                {},
                tracker_handle,
                memory_scope=invocation_scope,
            )
            is_error, _ = error_from_tool_payload(result)
            buttons: tuple[ResponseButton, ...]
            if is_error:
                buttons = ()
            else:
                try:
                    buttons = resolve_source_buttons(
                        writable_memory_keys=button_writable_memory_keys_for_skill(
                            self._skill_catalog,
                            tracker_handle.memory.project_memory,
                            skill_id,
                        )
                    )
                except Exception:
                    structlogger.warning(
                        "mantle.dynamic_buttons.source_resolve_failed",
                        skill_id=skill_id,
                        source=source,
                        exc_info=True,
                    )
                    buttons = ()

        if is_error:
            structlogger.warning(
                "mantle.dynamic_buttons.source_failed",
                skill_id=skill_id,
                source=source,
            )
        return response.model_copy(
            update={
                "buttons": buttons,
                "button_source": None,
            }
        )

    @staticmethod
    def _find_collect_ask_index(
        events_list: list,
        ask_text: str,
        start_index: int = 0,
        response_name: Optional[str] = None,
    ) -> Optional[int]:
        """Return the index of the most recent matching collect ask ``BotUttered``.

        A match is either ``BotUttered.text`` equal to *ask_text* (verbatim
        delivery) or, when *response_name* is set,
        ``BotUttered.metadata[utter_action]`` equal to *response_name*
        (rephrased delivery — the tracker stores LLM wording, not the template).
        """
        slice_start = max(0, start_index)
        scoped_events = events_list[slice_start:]
        for index, event in enumerate(reversed(scoped_events)):
            if not isinstance(event, BotUttered):
                continue
            if event.text == ask_text:
                return slice_start + len(scoped_events) - index - 1
            if (
                response_name is not None
                and isinstance(event.metadata, dict)
                and event.metadata.get(UTTER_ACTION_METADATA_KEY) == response_name
            ):
                return slice_start + len(scoped_events) - index - 1
        return None

    @staticmethod
    def _collect_question_was_answered(
        tracker_handle: TrackerHandle,
        ask_text: str,
        *,
        response_name: Optional[str] = None,
        events_list: Optional[list] = None,
        ask_index: Optional[int] = None,
        ask_scan_start: int = 0,
    ) -> bool:
        """True when the collect ask was uttered and the user has replied after it.

        Distinguishes "freshly arrived at a collect step" (ask now, WAIT) from
        "parked on the step since a previous turn" (defer to the LLM instead of
        re-asking in a loop).

        Matching is **not** limited to the latest bot utterance: if the LLM
        answers a follow-up in plain text without ``set_fields``, the last bot
        message is no longer the *ask_text*. Requiring exact last-bot equality
        would re-emit WAIT and skip the LLM — dropping post-completion
        follow-ups (e.g. a concrete task request during ``default_completed``).
        Instead, find the most recent matching bot utterance and treat any
        later user utterance as the answer turn.

        A prior ask matches when ``BotUttered.text`` equals *ask_text* (verbatim
        delivery) or when ``BotUttered.metadata[utter_action]`` equals
        *response_name* (rephrased delivery — the tracker stores LLM wording, not
        the canonical template).

        When *events_list* is omitted, tracker history is materialized. When
        *ask_index* is omitted, the most recent matching ``BotUttered`` is
        searched in *events_list* from *ask_scan_start* (``0`` when
        *events_list* was omitted), using the same verbatim or *response_name*
        rules as :meth:`_find_collect_ask_index`. Callers that scope the search
        (e.g. activation-scoped ``ask_before_filling`` steps in
        :meth:`_handle_collect_step`) should pass *ask_scan_start* together with
        a precomputed *ask_index* when available.

        Trackers without an event history (some test fakes) report ``False``.
        """
        if events_list is None:
            events = getattr(tracker_handle.tracker, "events", None)
            if not events:
                return False
            # ``DialogueStateTracker.events`` is a ``deque`` (no slice); materialize.
            events_list = list(events)
        if ask_index is None:
            ask_index = SkillExecutor._find_collect_ask_index(
                events_list,
                ask_text,
                start_index=ask_scan_start,
                response_name=response_name,
            )
        if ask_index is None:
            return False

        return any(
            isinstance(event, UserUttered) for event in events_list[ask_index + 1 :]
        )

    def _answer_recorded_since_question(
        self,
        tracker_handle: TrackerHandle,
        memory: MemoryManager,
        skill_id: str,
        flow_id: str,
        entry_name: str,
        ask_text: str,
        *,
        response_name: Optional[str] = None,
        events_list: Optional[list] = None,
        ask_index: Optional[int] = None,
        ask_scan_start: int = 0,
    ) -> bool:
        """True when *entry_name*'s slot was written after the most recent ask.

        Used to decide whether an ``ask_before_filling`` collect step may
        advance. ``advance_steps`` runs before the LLM processes the user's
        reply, so at that point the slot may still hold a stale value from an
        earlier step or an ``initial_value``. Advancing on that would treat the
        pre-existing value as the answer and drop a contradicting reply the LLM
        has not yet recorded. This confirms the answer to *this* ask was
        actually written (a memory write for the field after the ask utterance
        in *this* activation — see :func:`find_activation_index`).

        Any post-ask memory write for the field counts — provenance is not
        checked. In normal operation ``set_fields`` is expected to be the writer
        after the user replies; deterministic writes (``SetMemoryStep``, tools)
        between the ask and ``set_fields`` could advance the step before the
        LLM records a contradicting reply.

        The ask utterance matches verbatim *ask_text* or, when *response_name*
        is set, ``BotUttered.metadata[utter_action]`` (rephrased delivery).

        When *events_list* is omitted, tracker history is materialized. When
        *ask_index* is omitted, the most recent matching ``BotUttered`` is
        searched in *events_list* from *ask_scan_start* (``0`` when
        *events_list* was omitted), using the same rules as
        :meth:`_find_collect_ask_index`. Callers that scope the search
        (e.g. activation-scoped ``ask_before_filling`` steps in
        :meth:`_handle_collect_step`) should pass *ask_scan_start* together with
        a precomputed *ask_index* when available.

        Trackers without an event history (some test fakes) report ``False``.
        """
        try:
            slot_name = memory.resolve(skill_id, flow_id, entry_name)
        except ValueError:
            return False

        if events_list is None:
            events = getattr(tracker_handle.tracker, "events", None)
            if not events:
                return False
            events_list = list(events)
        if ask_index is None:
            ask_index = self._find_collect_ask_index(
                events_list,
                ask_text,
                start_index=ask_scan_start,
                response_name=response_name,
            )
        if ask_index is None:
            return False

        return any(
            isinstance(event, MemorySet)
            and event.key == slot_name
            and event.value is not None
            for event in events_list[ask_index + 1 :]
        )

    @staticmethod
    def _memory_scope(tracker_handle: TrackerHandle) -> tuple[str, str]:
        """Return the ``(skill_id, flow_id)`` to scope memory operations for this turn.

        Thin wrapper over :meth:`TrackerHandle.memory_scope` (the single source
        of the frame → scope resolution, ``("", "")`` in routing mode).
        """
        return tracker_handle.memory_scope()

    def current_memory_entries(
        self, tracker_handle: TrackerHandle
    ) -> Dict[str, MemoryEntry]:
        """Return current memory entries keyed by fully-qualified slot name.

        Resolved through :class:`~rasa.mantle.memory.manager.MemoryManager`
        (namespaced, schema-scoped). Each value is a
        :class:`~rasa.mantle.memory.field.MemoryEntry` pairing the field
        declaration with its runtime value — used for prompt population
        (``description`` / ``pii``) as well as value reads.

        Public so the orchestrator builds the active-skill memory listing from
        the same schema-scoped view used at dispatch time.
        """
        memory = tracker_handle.memory
        skill_id, flow_id = self._memory_scope(tracker_handle)
        return memory.read_all(skill_id, flow_id)

    def current_memory_values(self, tracker_handle: TrackerHandle) -> Dict[str, Any]:
        """Return current memory values keyed by fully-qualified slot name.

        Resolved through :meth:`current_memory_entries` so condition evaluation,
        tool gating, and routing all operate on the canonical
        ``session.skill_id.entry`` form.

        Public so the orchestrator builds prompt-time tool/flow gating from the
        same schema-scoped view used here at dispatch time; otherwise the two
        paths can disagree on a ``session.*`` expression.
        """
        return {
            name: entry.value
            for name, entry in self.current_memory_entries(tracker_handle).items()
        }

    # ------------------------------------------------------------------
    # Per-step phase handlers
    # ------------------------------------------------------------------

    def _handle_end_step(
        self,
        tracker_handle: TrackerHandle,
    ) -> _StepLoopSignal:
        """Complete the active skill on a :class:`EndStep`."""
        self._complete_skill(tracker_handle)
        return _StepLoopSignal.CONTINUE

    def _handle_route_step(
        self,
        step: RouteStep,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
        tracker_handle: TrackerHandle,
    ) -> _StepLoopSignal:
        """Evaluate conditional branches and advance the step pointer.

        A ``RouteStep`` carries no user-visible behaviour — it exists to
        structure conditional routing in the flow graph.
        """
        self._advance_or_complete(step.next, frame, tracker_handle)
        return _StepLoopSignal.CONTINUE

    def _handle_set_memory_step(
        self,
        step: SetMemoryStep,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
        tracker_handle: TrackerHandle,
    ) -> _StepLoopSignal:
        """Apply memory-write events and advance the step pointer.

        Memory writes are applied *before* resolving the next step so that
        conditional ``next:`` branches that depend on the values written here
        see the updated state rather than stale ones.

        Writes go through :class:`MemoryManager` (namespaced, schema-scoped).
        A :class:`MemoryWriteError` from an authored ``set_memory`` is a skill
        configuration error (writing an undeclared or otherwise unsettable
        entry) and is allowed to propagate rather than being silently
        swallowed. An already-set
        ``project.*`` field is expected after the first write: log and skip that
        key so the flow can continue.
        """
        memory = tracker_handle.memory
        skill_id, flow_id = memory.resolve_scope(frame)
        for entry_name, value in step.set_memory.items():
            try:
                memory.set(skill_id, flow_id, entry_name, value)
            except ProjectMemoryAlreadySetError:
                structlogger.warning(
                    "mantle.skill_executor.set_memory.project_already_set",
                    skill_id=skill_id,
                    flow_id=flow_id,
                    entry=entry_name,
                )
        # Re-read frame after applying events: a new one may have been pushed.
        self._advance_or_complete(
            step.next, tracker_handle.active_frame or frame, tracker_handle
        )
        return _StepLoopSignal.CONTINUE

    def _pop_block_keeping_skill(self, tracker_handle: TrackerHandle) -> None:
        """Pop the active block and keep the skill frame under it.

        Same-skill ``link:`` uses this so the handoff does not emit
        ``SkillCompleted``. The skill ends later, when its last block ends.
        """
        new_stack = tracker_handle.stack.copy()
        if new_stack.is_empty():
            structlogger.warning("mantle.skill_executor.link_step.no_active_frame")
            return

        popped = new_stack.pop()
        if not isinstance(popped, (UserFlowStackFrame, OrderedBlockStackFrame)):
            structlogger.warning(
                "mantle.skill_executor.link_step.non_block_frame",
                frame_type=type(popped).__name__,
            )
            return

        tracker_handle.clear_pending_tool_confirmation_if_owned_by(
            frame_id=popped.frame_id,
            skill_id=popped.skill_id,
        )
        completed_skill_id = owning_skill_id_for_frame(self._skill_catalog, popped)
        events: List[Any] = []
        completed_block_id = self._authored_block_id(popped)
        if completed_skill_id is not None and completed_block_id is not None:
            events.append(
                OrderedBlockCompleted(
                    skill_id=completed_skill_id,
                    block_id=completed_block_id,
                    step_id=catalog_step_id(popped),
                )
            )
        events.extend(tracker_handle.create_stack_update_events(new_stack))
        tracker_handle.apply_events(events)

    def _handle_link_step(
        self,
        step: LinkStep,
        tracker_handle: TrackerHandle,
    ) -> _StepLoopSignal:
        """Complete the current block and activate the linked target.

        A link to another ordered block of the same skill pops only that
        block. The skill frame stays, and the skill ends when the target
        block ends. A link to another skill completes the source skill
        first. If the target is not found, the source is still completed
        to avoid a stuck stack, and an error is logged.
        """
        # Defensive: train validates this; refuse if validation was skipped.
        if self._skill_catalog.is_internal_target(step.link):
            structlogger.error(
                "mantle.skill_executor.link_step.internal_not_callable",
                link=step.link,
                message=(
                    "Linked flow is an internal sub-flow (routable: false) and "
                    "cannot be reached via link:; source flow was not completed."
                ),
            )
            return _StepLoopSignal.BREAK

        # Capture before the source frame is popped (same-skill link must
        # skip the new-run memory reset).
        source_frame = tracker_handle.active_frame
        caller_skill = skill_for_stack_frame(self._skill_catalog, source_frame)
        target_skill = self._skill_catalog.owning_skill_for_target_id(step.link)
        flow_to_activate = resolve_link_activation_target_id(
            self._skill_catalog, step.link
        )
        same_skill_link = (
            caller_skill is not None
            and target_skill is not None
            and caller_skill.id == target_skill.id
        )
        same_skill_block_link = same_skill_link and (
            self._skill_catalog.ordered_block_id_for_target(flow_to_activate)
            is not None
        )
        if same_skill_block_link:
            self._pop_block_keeping_skill(tracker_handle)
        else:
            self._complete_skill(tracker_handle)
        if not self._activate_with_preconditions(
            flow_to_activate,
            tracker_handle,
            self.current_memory_values(tracker_handle),
            skill_id=target_skill.id if target_skill else None,
            block_id=self._skill_catalog.ordered_block_id_for_target(flow_to_activate),
            reset_memory=not same_skill_link,
        ):
            structlogger.error(
                "mantle.skill_executor.link_step.unknown_target",
                link=step.link,
                message=(
                    "Linked flow not found; source flow was completed but "
                    "the target was not activated. Check the skill.md link target."
                ),
            )
        return _StepLoopSignal.CONTINUE

    def _handle_call_step(
        self,
        step: CallStep,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
        tracker_handle: TrackerHandle,
    ) -> _StepLoopSignal:
        """Advance past the call site and push the called flow as a new frame."""
        # Defensive: train validates this; refuse if validation was skipped.
        if self._skill_catalog.is_internal_target(step.call):
            structlogger.error(
                "mantle.skill_executor.call_step.internal_not_callable",
                call=step.call,
                message=(
                    "Called flow is an internal sub-flow (routable: false) and "
                    "cannot be reached via call:; caller was not advanced."
                ),
            )
            return _StepLoopSignal.BREAK

        # A deterministic call: is not a user digression. Clear a stale INTERRUPT
        # marker (e.g. from a redundant activate) so callee completion does
        # not surface the resume prompt for work that never paused.
        if (
            isinstance(frame, UserFlowStackFrame)
            and frame.frame_type == FlowStackFrameType.INTERRUPT
        ) or (
            isinstance(frame, OrderedBlockStackFrame)
            and frame.frame_type == MantleStackFrameType.INTERRUPT
        ):
            self._resume_interrupted_frame(frame, tracker_handle)
            active = tracker_handle.active_frame
            if isinstance(active, (UserFlowStackFrame, OrderedBlockStackFrame)):
                frame = active

        # Advance the current frame past the CallStep before pushing the callee
        # so we return here when the callee completes. Include END so
        # the referenced block auto-completes after the callee pops
        # (skill executor returns to the prose frame).
        return_id = self._resolve_next_skill(step.next, tracker_handle)
        self._advance_step(frame, return_id or END_STEP, tracker_handle)
        target_skill = self._skill_catalog.owning_skill_for_target_id(step.call)
        flow_to_activate = resolve_call_activation_target_id(
            self._skill_catalog, step.call
        )
        caller_skill = skill_for_stack_frame(self._skill_catalog, frame)
        same_skill_call = (
            caller_skill is not None
            and target_skill is not None
            and caller_skill.id == target_skill.id
        )
        self._activate_with_preconditions(
            flow_to_activate,
            tracker_handle,
            self.current_memory_values(tracker_handle),
            skill_id=target_skill.id if target_skill else None,
            block_id=self._skill_catalog.ordered_block_id_for_target(flow_to_activate),
            new_frame_type=FlowStackFrameType.CALL,
            reset_memory=not same_skill_call,
        )
        return _StepLoopSignal.CONTINUE

    def release_deferred_listen(self, tracker_handle: TrackerHandle) -> None:
        """Release a listen held for the post-activate fill.

        The fill was cancelled before this step ran. Listen with more script
        after it moves to that step so the interrupting message is not
        consumed. Listen that would end the flow cancels the frame instead of
        completing it: completion would start ``default_completed`` and that
        wrap-up ask would take the next turn. A block-only skill ends with
        its block; a hybrid skill keeps its prose frame so the next turn can
        answer in context. The listen action is not recorded. ``hangup`` is
        never held, so it is not released here.
        """
        frame = tracker_handle.active_frame
        step = self._active_catalog_step(tracker_handle)
        if not isinstance(step, ActionStep) or not isinstance(
            frame, (OrderedBlockStackFrame, UserFlowStackFrame)
        ):
            return
        if step.action != ACTION_LISTEN_NAME:
            return
        next_id = self._resolve_next_skill(step.next, tracker_handle)
        if next_id is not None and next_id != END_STEP:
            self._advance_or_complete(step.next, frame, tracker_handle)
            return
        self._cancel_deferred_turn_ending_frame(tracker_handle)

    def _cancel_deferred_turn_ending_frame(self, tracker_handle: TrackerHandle) -> None:
        """Cancel the frame held for the fill instead of completing it.

        Used for a listen whose next step would end the flow. Mirrors
        :meth:`_complete_skill`'s teardown shape but emits cancel events:
        ``FlowCancelled`` / ``OrderedBlockCancelled`` for the frame,
        ``SkillCancelled`` when no other block of that skill remains (including
        a block reached by same-skill ``link:``), and clears any pending
        confirmation the removed frames owned. Does not start
        ``default_completed``.
        """
        new_stack = tracker_handle.stack.copy()
        popped = new_stack.pop()
        if not isinstance(popped, (OrderedBlockStackFrame, UserFlowStackFrame)):
            return
        last_block = self._completing_last_blocks_only_block(new_stack, popped)
        removed: List[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame]
        removed = [
            popped,
            *self._remove_block_only_skill_wrapper(
                new_stack, popped, last_block=last_block
            ),
        ]
        tracker_handle.apply_events(
            [
                *self._cancel_frames(tracker_handle, removed),
                *tracker_handle.create_stack_update_events(new_stack),
            ]
        )

    def _handle_action_step(
        self,
        step: ActionStep,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
        tracker_handle: TrackerHandle,
        defer_listen: bool = False,
    ) -> _StepOutcome:
        """Emit a canned utterance, listen for user input, or signal the LLM.

        ``utter_*`` actions are resolved to text and returned as an
        :class:`AgentResponse` with ``completes_current_step=True``. The
        orchestrator delivers the message first, then
        :meth:`complete_delivered_step` decides ``WAIT`` vs ``CONTINUE`` from
        the residual stack.

        ``action_listen`` and ``hangup`` advance the step and return a
        ``WAIT`` :class:`AgentResponse`. The orchestrator ends the turn
        immediately without calling the LLM. A listen ends the turn whether
        it is the last step or more script follows. ``hangup`` also records
        a turn-local termination request for the processor.

        When *defer_listen* is set and settable fields remain, ``action_listen``
        returns ``WAIT`` without advancing or recording, so the caller can
        write those fields and run ``advance_steps`` again. The next lap runs
        the listen and the turn still ends there. ``hangup`` is never held:
        the call is ending, so nothing later would use a value saved first,
        and holding it would add an LLM call on the way out.

        ``action_*`` steps require an action-server call not yet implemented;
        the loop breaks and the LLM receives the step as context instead.
        """
        if step.action.startswith(_UTTER_PREFIX):
            # The step is deliberately NOT advanced here: the orchestrator
            # delivers the text first and then calls
            # :meth:`complete_delivered_step`, so completion events land
            # after the ``BotUttered`` on the tracker (authored order) and
            # ``{session.*}`` placeholders still resolve against the live
            # frame (completion pops it).
            resolved = self.resolve_response_name(step.action, tracker_handle)
            skill_id, flow_id = tracker_handle.memory_scope()
            return AgentResponse(
                text=resolved.text,
                response_name=step.action,
                rephrase=resolved.rephrase,
                buttons=resolved.buttons,
                button_source=resolved.button_source,
                variant_metadata=resolved.variant_metadata,
                completes_current_step=True,
                **button_source_scope_fields(resolved.button_source, skill_id, flow_id),
            )
        if (
            step.action == ACTION_LISTEN_NAME
            and defer_listen
            and self.settable_fields_for_turn(tracker_handle)[0]
        ):
            return AgentResponse(text="", mode=ResponseMode.WAIT)
        if step.action in {ACTION_LISTEN_NAME, BUILTIN_HANGUP}:
            self._advance_or_complete(step.next, frame, tracker_handle)
            tracker_handle.apply_events([ActionExecuted(step.action)])
            if step.action == BUILTIN_HANGUP:
                self._hangup_requested = True
            return AgentResponse(text="", mode=ResponseMode.WAIT)
        if step.action in SUPPORTED_BUILTIN_ACTIONS:
            structlogger.error(
                "mantle.skill_executor.action.missing_dispatch",
                action_name=step.action,
            )
            return AgentResponse(text="", mode=ResponseMode.WAIT)
        # Custom action_*: TODO action server dispatch; break for now.
        return _StepLoopSignal.BREAK

    async def _handle_execute_step(
        self,
        step: ExecuteStep,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
        tracker_handle: TrackerHandle,
    ) -> _StepOutcome:
        """Dispatch an inline tool call and advance past the execute step.

        ``tool_constraints`` (``requires`` / ``requires_confirmation``) apply here the
        same way as LLM tool dispatch. A ``requires_confirmation`` pause leaves the
        frame on this step, returns a WAIT ask, and stores pending state so
        ``resolve_tool_confirmation`` can run or cancel the tool and then advance.
        On a later turn, while that pending state remains for this step, return
        ``BREAK`` so the orchestrator reaches the LLM (which offers resolve)
        instead of re-entering the gate and ending the turn on an empty WAIT.

        When the named tool is not registered (typo or MCP import did not bind),
        fail closed: stay on the step and return ``BREAK`` so the orchestrator
        reaches the LLM rather than skipping the step.
        """
        # Resolve the tool-registry skill id via the same flow-to-skill mapping
        # used for memory and the LLM schema, so the inline tool is found even
        # when the frame carries no skill_id (otherwise the tool is silently
        # dropped, leaving downstream templates un-rendered and collect steps
        # looping).
        active_skill_id, _ = tracker_handle.memory.resolve_scope(frame)
        tools_for_skill = self._tool_funcs.get(active_skill_id, {})
        tool_func = tools_for_skill.get(step.execute_tool)

        if self._is_builder_defined_tool(active_skill_id, step.execute_tool):
            gated_outcome = await self._tool_constraints.dispatch_execute_step(
                step=step,
                tracker_handle=tracker_handle,
                active_skill_id=active_skill_id,
                tool_func=tool_func,
            )
            if gated_outcome is ExecuteStepControl.YIELD_TO_LLM:
                return _StepLoopSignal.BREAK
            if gated_outcome is not None:
                return gated_outcome
        else:
            structlogger.warning(
                "mantle.skill_executor.advance_steps.execute_tool_missing",
                tool=step.execute_tool,
            )
            return _StepLoopSignal.BREAK

        # Re-read frame after the tool call: the tool may have applied events.
        resumed = tracker_handle.active_frame or frame
        if isinstance(resumed, (UserFlowStackFrame, OrderedBlockStackFrame)):
            self._advance_or_complete(step.next, resumed, tracker_handle)
        # Must follow the advance: activating first would apply ``step.next``
        # to the newly pushed frame and strand this flow on the execute step.
        self.run_pending_tool_instructions(tracker_handle)
        return _StepLoopSignal.CONTINUE

    def _advance_or_break_after_recorded_collect_answer(
        self,
        step: CollectStep,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
        tracker_handle: TrackerHandle,
        memory: MemoryManager,
        skill_id: str,
        flow_id: str,
        slot_value: Any,
        ask_text: str,
        utterance: str,
        events_list: list,
        ask_index: Optional[int],
        collect_scan_start: int,
    ) -> Optional[_StepLoopSignal]:
        """Return CONTINUE/BREAK when the collect ask was already answered."""
        if not self._collect_question_was_answered(
            tracker_handle,
            ask_text,
            response_name=utterance,
            events_list=events_list,
            ask_index=ask_index,
            ask_scan_start=collect_scan_start,
        ):
            return None
        # The answer to that ask was already taken and the field deliberately
        # cleared earlier this turn (a paging loop). The empty field is a new
        # question, not an answer still waiting to be recorded.
        if slot_value is None and self._collect_ask_was_consumed(frame):
            return None
        # An ``ask_before_filling`` step is (re-)asked even when its value is
        # already set, so advancing must not park here forever (the
        # advance-on-filled guard above skips it). But advance only once the
        # answer to *this* ask has actually been recorded (a ``MemorySet`` after
        # the ask, typically from ``set_fields``), never on a stale or
        # ``initial_value`` the LLM has not yet had the chance to overwrite.
        if slot_value is not None and self._answer_recorded_since_question(
            tracker_handle,
            memory,
            skill_id,
            flow_id,
            step.collect,
            ask_text,
            response_name=utterance,
            events_list=events_list,
            ask_index=ask_index,
            ask_scan_start=collect_scan_start,
        ):
            self._consume_collect_ask(frame)
            self._advance_or_complete(step.next, frame, tracker_handle)
            return _StepLoopSignal.CONTINUE
        return _StepLoopSignal.BREAK

    def _abf_confirm_collect_response(
        self,
        step: CollectStep,
        entry: Optional[MemoryEntry],
        slot_value: Any,
        resolved: ResolvedUtterance,
        utterance: str,
        tracker_handle: TrackerHandle,
    ) -> AgentResponse:
        """Emit a confirm-rephrase ask for a prefilled ask_before_filling collect.

        The value was prefilled (e.g. via ``set_fields``) but ``ask_before_filling``
        requires explicit user confirmation before the collect advances.
        """
        skill_id, flow_id = tracker_handle.memory_scope()
        skill = self._skill_catalog.skill_by_id(skill_id)
        field_description = (
            resolved_memory_field_description(skill, step.collect)
            if skill is not None
            else None
        )
        confirm_value = (
            PII_SET_PLACEHOLDER if entry is not None and entry.field.pii else slot_value
        )
        return AgentResponse(
            text=resolved.text,
            mode=ResponseMode.WAIT,
            response_name=utterance,
            rephrase=ConfirmRephrase(
                field=step.collect,
                value=confirm_value,
                field_description=field_description,
            ),
            buttons=resolved.buttons,
            button_source=resolved.button_source,
            variant_metadata=resolved.variant_metadata,
            **button_source_scope_fields(resolved.button_source, skill_id, flow_id),
        )

    def _handle_collect_step(
        self,
        step: CollectStep,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
        tracker_handle: TrackerHandle,
    ) -> _StepOutcome:
        """Skip past a filled collect step or ask the question and pause.

        Outcomes:

        * Memory entry already filled (and ``ask_before_filling`` is off) →
          advance the step pointer and return ``CONTINUE`` so the loop
          processes the next step.
        * ``ask_before_filling`` on, user has replied since the ask, the slot
          is set (including ``False`` for bool fields), and a ``MemorySet``
          for the field appears after the ask utterance
          (:meth:`_answer_recorded_since_question`) → advance and return
          ``CONTINUE``.
        * Advanced with a value earlier this turn and the field is empty again
          → emit the utterance and return ``WAIT``. The parked-ask and
          answered-but-unrecorded deferrals do not apply
          (:meth:`_consume_collect_ask`).
        * Otherwise → emit the configured utterance once (``WAIT``), then defer
          to the LLM on subsequent turns so the reply is processed via
          ``set_fields`` (``BREAK`` when the user has already replied but the
          answer has not yet been recorded after the ask).

          If no utterance is configured the LLM asks naturally (``BREAK``).
        """
        memory = tracker_handle.memory
        skill_id, flow_id = memory.resolve_scope(frame)
        entry = memory.get(skill_id, flow_id, step.collect)
        slot_value = entry.value if entry is not None else None
        if slot_value is not None and not step.ask_before_filling:
            # Mixed-control resumes after skip; record so the prompt can tell
            # the model not to re-ask this field as if it were unknown.
            self._record_skipped_collect(memory, skill_id, flow_id, step.collect, entry)
            self._consume_collect_ask(frame)
            self._advance_or_complete(step.next, frame, tracker_handle)
            return _StepLoopSignal.CONTINUE

        # Need to ask (empty slot, or ABF confirm when already filled). No
        # utterance → LLM asks; otherwise resolve canned text below.
        utterance = step.utterance
        if utterance is None:
            return _StepLoopSignal.BREAK  # LLM asks naturally
        resolved = self.resolve_response_name(utterance, tracker_handle)
        ask_text = resolved.text
        events = getattr(tracker_handle.tracker, "events", None)
        events_list = list(events) if events else []
        collect_scan_start = 0
        if step.ask_before_filling:
            activation_index = find_activation_index(
                events_list,
                skill_id=skill_id,
                block_id=self._authored_block_id(frame),
            )
            # Ask-before-filling still scans from 0 when no activation anchor is
            # present; the completion judge fails closed instead (empty
            # transcript).
            collect_scan_start = 0 if activation_index is None else activation_index
        ask_index = (
            self._find_collect_ask_index(
                events_list,
                ask_text,
                start_index=collect_scan_start,
                response_name=utterance,
            )
            if events_list
            else None
        )
        advance_signal = self._advance_or_break_after_recorded_collect_answer(
            step,
            frame,
            tracker_handle,
            memory,
            skill_id,
            flow_id,
            slot_value,
            ask_text,
            utterance,
            events_list,
            ask_index,
            collect_scan_start,
        )
        if advance_signal is not None:
            return advance_signal
        if self._take_parked_collect_deferral(frame, step, tracker_handle):
            return _StepLoopSignal.BREAK  # message arrived while parked → LLM
        if step.ask_before_filling and slot_value is not None:
            return self._abf_confirm_collect_response(
                step, entry, slot_value, resolved, utterance, tracker_handle
            )
        skill_id, flow_id = tracker_handle.memory_scope()
        return AgentResponse(
            text=ask_text,
            mode=ResponseMode.WAIT,
            response_name=utterance,
            rephrase=resolved.rephrase,
            buttons=resolved.buttons,
            button_source=resolved.button_source,
            variant_metadata=resolved.variant_metadata,
            **button_source_scope_fields(resolved.button_source, skill_id, flow_id),
        )

    def _record_skipped_collect(
        self,
        memory: MemoryManager,
        skill_id: str,
        flow_id: str,
        entry_name: str,
        entry: Optional[MemoryEntry],
    ) -> None:
        """Stash a skip fact on the current turn for the mixed-control prompt."""
        if entry is None or entry.value is None:
            return
        try:
            turn = current_turn_context()
        except LookupError:
            return
        turn.record_skipped_collect(
            field_name=memory.resolve(skill_id, flow_id, entry_name),
            display_value=skipped_collect_display_value(entry),
        )

    def _take_parked_collect_deferral(
        self,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
        step: CollectStep,
        tracker_handle: TrackerHandle,
    ) -> bool:
        """Whether *step* must hand this turn's message to the LLM (consumes flag).

        A collect step the conversation was **already** parked on when the turn
        began has, by definition, had its turn to speak: the incoming message is
        the user's reaction to it. Re-emitting the question here would end the
        turn via ``phase_response_wait`` and drop that message without the model
        ever seeing it — the failure behind ENG-3023, where a follow-up asked
        during the end-of-conversation CSAT question was answered by silently
        repeating the question.

        The stack position is the reliable signal for "already asked":
        :meth:`_collect_question_was_answered` infers it from the event history,
        which stops matching whenever neither the delivered text nor the
        recorded ``utter_action`` identifies the ask (an ask the model phrased
        itself, a send skipped by cancellation) — and then every follow-up is
        dropped. This runs only once that check has come up empty.

        Two conditions keep the deferral to the case it protects:

        * A user message must exist on the tracker. With no message to drop
          there is nothing to rescue, so a step reached with an empty history
          asks deterministically rather than spending an LLM call.
        * It is one-shot per turn: once the model has had the message, or the
          collect advances with a filled value, a later lap of the loop landing
          back on this step falls through to the deterministic ask.
        """
        if self._parked_collect_step != (frame.frame_id, frame.step_id):
            return False
        events = getattr(tracker_handle.tracker, "events", None) or []
        if not any(isinstance(event, UserUttered) for event in events):
            return False
        self._parked_collect_step = None
        structlogger.debug(
            "mantle.skill_executor.collect.deferred_to_llm_while_parked",
            flow_id=target_id_for_frame(frame)
            if isinstance(frame, OrderedBlockStackFrame)
            else frame.flow_id,
            step_id=frame.step_id,
            collect=step.collect,
        )
        return True

    def _consume_collect_ask(
        self,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
    ) -> None:
        """Record that this collect advanced with a value, ending its ask.

        Both signals that route an empty collect to the LLM — the
        parked-at-turn-start marker and the answered-but-unrecorded check —
        describe an ask still waiting for its answer. Once that answer has been
        taken and the step left, a later lap of the same turn landing back here
        is a new question and asks again.
        """
        position = (frame.frame_id, frame.step_id)
        if self._parked_collect_step == position:
            self._parked_collect_step = None
        self._consumed_collect_asks.add(position)

    def _collect_ask_was_consumed(
        self,
        frame: UserFlowStackFrame | OrderedBlockStackFrame,
    ) -> bool:
        """Whether this collect already advanced with a value during this turn."""
        return (frame.frame_id, frame.step_id) in self._consumed_collect_asks

    def _handle_autonomous_step(
        self,
        step: AutonomousStep,
        frame: UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame,
        tracker_handle: TrackerHandle,
    ) -> _StepLoopSignal:
        """Advance past an autonomous step when its condition is met; otherwise break.

        When ``complete_when`` is set and evaluates to ``True`` the step is
        treated as done and the next step is resolved deterministically.
        When the condition is absent or not yet met the LLM handles this step.
        """
        if self._autonomous_step_is_complete(step, tracker_handle):
            self._advance_or_complete(step.next, frame, tracker_handle)
            return _StepLoopSignal.CONTINUE
        return _StepLoopSignal.BREAK

    def _autonomous_step_is_complete(
        self, step: AutonomousStep, tracker_handle: TrackerHandle
    ) -> bool:
        """Whether *step* has a ``complete_when`` condition that already holds.

        Skill-level NL ``criteria`` disable *prose-flow* auto-complete (the
        compiler also clears the synthetic step's ``complete_when``). Ordered-block
        ``instructions:`` steps keep their own step-level conditions so a hybrid
        skill with criteria is not stuck mid-block.
        """
        if not step.complete_when:
            return False
        skill_id, flow_id = tracker_handle.memory_scope()
        if skill_id and flow_id and not is_ordered_block_target_id(skill_id, flow_id):
            skill = self._skill_catalog.skill_by_id(skill_id)
            if (
                skill is not None
                and skill.complete_when is not None
                and skill.complete_when.criteria
            ):
                return False
        memory_values = self.current_memory_values(tracker_handle)
        return bool(evaluate_expression(step.complete_when, memory_values))

    # ------------------------------------------------------------------
    # Public interface — advance phases
    # ------------------------------------------------------------------

    def completing_delivered_step_ends_active_flow(
        self, tracker_handle: TrackerHandle
    ) -> bool:
        """Return whether ``complete_delivered_step`` would pop the active flow.

        Used to tell a mid-flow canned line (more script remains in this flow)
        from a terminal utter. A parent frame may still be underneath, so
        popping this flow is not the same as ending the turn.
        """
        frame = tracker_handle.active_frame
        if frame is None:
            return False
        step = self._resolve_catalog_step(frame)
        if step is None:
            return False
        next_id = self._resolve_next_skill(getattr(step, "next", None), tracker_handle)
        return (
            next_id is None or next_id == END_STEP or isinstance(frame, SkillStackFrame)
        )

    def complete_delivered_step(self, tracker_handle: TrackerHandle) -> ResponseMode:
        """Advance past the step whose response was just delivered.

        Counterpart of an :class:`AgentResponse` returned with
        ``completes_current_step=True``: :meth:`advance_steps` left the frame
        on the producing step so the orchestrator could deliver the message
        first; this applies the deferred advancement/completion and reports
        how the turn should proceed.

        Returns:
            ``WAIT`` when completing emptied the stack, and ``CONTINUE`` when
            more deterministic or LLM-owned work remains.
        """
        frame = tracker_handle.active_frame
        if frame is None:
            return ResponseMode.WAIT
        step = self._resolve_catalog_step(frame)
        if step is None:
            structlogger.warning(
                "mantle.skill_executor.complete_delivered_step.unknown_step",
                flow_id=target_id_for_frame(frame),
                step_id=catalog_step_id(frame),
            )
            return ResponseMode.WAIT
        # Only response-producing steps defer (they all carry ``next``);
        # ``getattr`` keeps the union narrow-safe for step kinds without it.
        self._advance_or_complete(getattr(step, "next", None), frame, tracker_handle)
        residual_step = self._active_catalog_step(tracker_handle)
        if residual_step is None:
            return ResponseMode.WAIT
        return ResponseMode.CONTINUE

    async def advance_steps(
        self,
        tracker_handle: TrackerHandle,
        *,
        defer_listen: bool = False,
    ) -> Optional[AgentResponse]:
        """Advance deterministic steps before invoking the LLM.

        Iterates through the current flow steps and delegates each one to the
        matching ``_handle_*`` method.  The loop continues while handlers
        return :attr:`_StepLoopSignal.CONTINUE` and stops when they return
        :attr:`_StepLoopSignal.BREAK` or an :class:`AgentResponse`.

        Step types handled (see individual ``_handle_*`` methods for details):

        * :class:`EndStep` → complete the active skill.
        * :class:`RouteStep` → evaluate branches, advance.
        * :class:`SetMemoryStep` → write memory entries, advance.
        * :class:`LinkStep` → complete current, activate linked flow.
        * :class:`CallStep` → push called flow frame.
        * :class:`ActionStep` (``utter_*``) → emit utterance (``WAIT`` or
          ``CONTINUE`` depending on the residual top step).
        * :class:`ActionStep` (``action_*``) → TODO action-server; break.
        * :class:`ExecuteStep` → dispatch inline tool, advance.
        * :class:`CollectStep` → skip when filled, else ask/break.
        * :class:`AutonomousStep` → advance when condition met, else break.

        Args:
            tracker_handle: Live tracker wrapper for the current turn.
            defer_listen: When ``True`` and ``action_listen`` is reached with
                settable fields available, return without running it. Listen
                records ``ActionExecuted`` before WAIT; skip that commit when
                the caller still needs the current step. ``hangup`` always
                commits.

        Returns:
            An :class:`AgentResponse` when a pre-LLM utterance was produced,
            or ``None`` when the LLM should decide the next action.
        """
        max_steps = 50  # safety guard against infinite loops in malformed flows
        for _ in range(max_steps):
            frame = tracker_handle.active_frame
            if frame is None:
                break

            if isinstance(
                frame,
                (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
            ):
                self._correction.clear_note_if_caught_up(tracker_handle, frame)
            else:
                break

            compiled_flow_id = target_id_for_frame(frame)
            target = self.resolve_activation_target(compiled_flow_id)
            if target is None:
                structlogger.warning(
                    "mantle.skill_executor.advance_steps.unknown_flow",
                    flow_id=compiled_flow_id,
                )
                break

            step = self._resolve_catalog_step(frame)
            if step is None:
                structlogger.warning(
                    "mantle.skill_executor.advance_steps.unknown_step",
                    flow_id=compiled_flow_id,
                    step_id=catalog_step_id(frame),
                )
                break

            structlogger.debug(
                "mantle.skill_executor.advance_steps.step",
                flow_id=compiled_flow_id,
                step_id=catalog_step_id(frame),
                step_type=type(step).__name__,
            )

            # Dispatch to per-step handler.
            outcome: _StepOutcome
            if isinstance(step, EndStep):
                outcome = self._handle_end_step(tracker_handle)
            elif isinstance(step, AutonomousStep):
                outcome = self._handle_autonomous_step(step, frame, tracker_handle)
            elif isinstance(frame, SkillStackFrame):
                structlogger.warning(
                    "mantle.skill_executor.advance_steps.unhandled_skill_step_type",
                    step_type=type(step).__name__,
                )
                break
            elif isinstance(step, RouteStep):
                outcome = self._handle_route_step(step, frame, tracker_handle)
            elif isinstance(step, SetMemoryStep):
                outcome = self._handle_set_memory_step(step, frame, tracker_handle)
            elif isinstance(step, LinkStep):
                outcome = self._handle_link_step(step, tracker_handle)
            elif isinstance(step, CallStep):
                outcome = self._handle_call_step(step, frame, tracker_handle)
            elif isinstance(step, ActionStep):
                outcome = self._handle_action_step(
                    step,
                    frame,
                    tracker_handle,
                    defer_listen=defer_listen,
                )
            elif isinstance(step, ExecuteStep):
                outcome = await self._handle_execute_step(step, frame, tracker_handle)
            elif isinstance(step, CollectStep):
                outcome = self._handle_collect_step(step, frame, tracker_handle)
            else:
                structlogger.warning(
                    "mantle.skill_executor.advance_steps.unhandled_step_type",
                    step_type=type(step).__name__,
                )
                break

            if isinstance(outcome, AgentResponse):
                return outcome
            if outcome == _StepLoopSignal.BREAK:
                break
            # _StepLoopSignal.CONTINUE → next iteration

        return None

    # ------------------------------------------------------------------
    # Public interface — dispatch tool calls
    # ------------------------------------------------------------------

    def find_correctable_fields(
        self, tracker_handle: TrackerHandle
    ) -> List[CorrectableMemoryItem]:
        """Return the fields eligible for cross-phase correction this turn.

        Delegates to :meth:`CorrectionExecutor.find_correctable_memory_items` so
        the orchestrator can build the per-turn ``correct`` tool schema from the
        same source the dispatcher validates against.
        """
        return self._correction.find_correctable_memory_items(tracker_handle)

    async def dispatch_tool_call(
        self,
        tool_name: str,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
        tool_call_id: Optional[str] = None,
    ) -> Optional[str]:
        """Route one LLM tool call to the matching lifecycle handler.

        When *tool_call_id* is provided (the orchestrator passes the LLM tool
        call's id), the dispatch runs inside
        :meth:`TrackerHandle.recording_tool_call` so every memory write it
        produces — builder-tool writes, ``set_fields`` direct writes, and
        memory-validation-tool writes — carries the id in its write-provenance,
        joining it exactly to the ``ToolExecuted`` event the orchestrator
        appends. ``None`` marks engine-invoked dispatches, whose writes stay
        unstamped with an id.

        Args:
            tool_name: Name of the tool the LLM called.
            tool_args: Arguments extracted from the LLM tool call.
            tracker_handle: Live tracker wrapper for the current turn.
            tool_call_id: Id of the dispatching LLM tool call, or ``None``
                when the dispatch does not originate from an LLM tool call.

        Returns:
            The serialised tool-result string to append to the LLM message
            list, or ``None`` when the call produces no meaningful result text.
        """
        if tool_call_id is None:
            return await self._route_tool_call(tool_name, tool_args, tracker_handle)
        with tracker_handle.recording_tool_call(tool_call_id):
            return await self._route_tool_call(tool_name, tool_args, tracker_handle)

    def run_pending_tool_instructions(self, tracker_handle: TrackerHandle) -> None:
        """Apply queued ``ToolResult.next`` instructions in the order they were queued.

        Call once the producing tools' results are on the tracker (and, for an
        ``execute_tool`` step, after the step advanced). See
        :meth:`run_tool_instructions` for the rules applied.

        Args:
            tracker_handle: Live tracker wrapper for the current turn.
        """
        self.run_tool_instructions(
            self.take_pending_tool_instructions(), tracker_handle
        )

    def take_pending_tool_instructions(self) -> list[PendingInstruction]:
        """Remove and return the ``ToolResult.next`` instructions queued so far.

        The orchestrator takes them per tool call so a result hook that marks
        the call as failed can veto them before :meth:`run_tool_instructions`.
        """
        return self._tool_invoker.drain_pending_instructions()

    def run_tool_instructions(
        self,
        instructions: Sequence[PendingInstruction],
        tracker_handle: TrackerHandle,
    ) -> None:
        """Apply *instructions* in order once their producing tools are recorded.

        Each ``ActivateSkill`` goes through the same validation and activation
        as the LLM ``activate`` tool. Instructions that cannot be applied are
        logged and skipped. At most ``_MAX_TOOL_DRIVEN_ACTIVATIONS_PER_TURN``
        instructions run per turn; the rest are dropped with one error log.

        While a ``requires_confirmation`` ask is pending on the active frame
        the instructions are stored on that pending record instead of running:
        activating another skill would move the frame the pending state
        belongs to. They are re-queued once the user confirms or declines.

        Args:
            instructions: Queued instructions, oldest first.
            tracker_handle: Live tracker wrapper for the current turn.
        """
        if not instructions:
            return
        pending_confirmation = (
            tracker_handle.pending_tool_confirmation_for_active_frame()
        )
        if pending_confirmation is not None:
            self._defer_until_confirmation_resolved(
                instructions, pending_confirmation, tracker_handle
            )
            return
        pending = list(instructions)
        for index, item in enumerate(pending):
            if (
                self._tool_driven_activation_count
                >= _MAX_TOOL_DRIVEN_ACTIVATIONS_PER_TURN
            ):
                self._log_tool_driven_cap_exceeded(
                    item.tool_name, dropped_count=len(pending) - index
                )
                return
            self._tool_driven_activation_count += 1
            self._dispatch_activate_skill_instruction(
                item.tool_name, item.instruction, tracker_handle
            )

    @staticmethod
    def _defer_until_confirmation_resolved(
        instructions: Sequence[PendingInstruction],
        pending_confirmation: PendingToolConfirmation,
        tracker_handle: TrackerHandle,
    ) -> None:
        """Store *instructions* on the pending confirmation until it resolves."""
        deferred = [
            DeferredInstruction(tool_name=item.tool_name, instruction=item.instruction)
            for item in instructions
        ]
        tracker_handle.set_pending_tool_confirmation(
            pending_confirmation.model_copy(
                update={
                    "deferred_next": [*pending_confirmation.deferred_next, *deferred]
                }
            )
        )
        structlogger.info(
            "mantle.skill_executor.tool.next.deferred_pending_confirmation",
            tools=sorted({item.tool_name for item in instructions}),
            count=len(instructions),
            pending_tool=pending_confirmation.tool_name,
        )

    def _log_tool_driven_cap_exceeded(self, tool_name: str, dropped_count: int) -> None:
        """Log the per-turn instruction cap being hit, once per turn."""
        if self._tool_driven_cap_logged:
            return
        self._tool_driven_cap_logged = True
        structlogger.error(
            "mantle.skill_executor.tool.next.cap_exceeded",
            tool=tool_name,
            max_activations=_MAX_TOOL_DRIVEN_ACTIVATIONS_PER_TURN,
            dropped_count=dropped_count,
        )

    async def _route_tool_call(
        self,
        tool_name: str,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
    ) -> Optional[str]:
        """Match one tool call to its lifecycle handler and invoke it.

        Tool categories handled, in priority order:

        * ``listen`` — no-op: the orchestrator ends the turn. Stack and memory
          are unchanged.
        * ``activate`` — push a new flow frame onto the stack, but only
          when the requested flow is activatable for the current memory state
          and active stack frame.
        * ``complete`` — pop the active frame and route post-completion.
        * ``cancel`` — when confirmation is enabled and a skill is active,
          pause on the same confirmation step as a skill tool. A pending
          confirmation for another tool, or a cancel ask parked on another
          frame, is replaced by this pause. Calling cancel again while its
          own question is open on the active frame must resolve that
          question. Otherwise pop the active frame and route to post-cancel
          wrap-up, including when another tool confirmation is pending. This
          tool takes no arguments.
          A call with no active frame stays a no-op: the tool is not offered
          then, but an unoffered call still reaches this handler.
        * ``resolve_tool_confirmation`` — resume or cancel a paused builder
          tool waiting on ``requires_confirmation``.
        * Builder-defined tools — dispatch through the tool-constraints runtime,
          including schema validation and any ``requires_confirmation`` pause.
        * ``set_fields`` — batch collect setter: writes every field the
          LLM provided that is settable for the active skill this turn (see
          :meth:`settable_fields_for_turn`).

        Any remaining tool name is unexpected and logged as a warning.

        Returns the serialised tool-result string to append to the LLM message
        list, or ``None`` when the call produces no meaningful result text.

        ``ToolResult.next`` instructions from builder tools are queued, not
        applied. The caller runs them with
        :meth:`run_pending_tool_instructions`.
        """
        structlogger.debug(
            "mantle.skill_executor.dispatch",
            tool_name=tool_name,
            tool_args=tool_args,
        )

        if tool_name == TOOL_LISTEN:
            return None

        memory_values = self.current_memory_values(tracker_handle)

        if (
            tool_name != TOOL_CANNOT_HELP
            and lifecycle_skill_id_for_frame(
                self._skill_catalog, tracker_handle.active_frame
            )
            == DEFAULT_UNSUPPORTED_REQUEST_HANDLER
        ):
            structlogger.debug(
                "mantle.skill_executor.dispatch.tool_refused_while_declining",
                tool_name=tool_name,
            )
            return format_error_as_json(
                "Cannot run other tools while declining the request."
            )

        if not builtin_tool_enabled(self._builtin_tool_constraints, tool_name):
            structlogger.warning(
                "mantle.skill_executor.dispatch.disabled_tool",
                tool_name=tool_name,
            )
            return format_error_as_json(f"Tool '{tool_name}' is disabled.")

        if tool_name == TOOL_ACTIVATE:
            return self._dispatch_activate(tool_args, tracker_handle, memory_values)
        if tool_name == TOOL_COMPLETE:
            refuse = await self._completion_gate.refuse_complete_tool(
                tracker_handle, memory_values
            )
            if refuse is not None:
                return refuse
            self._complete_skill(tracker_handle)
            return None
        if tool_name == TOOL_CANCEL:
            # Not offered without an active frame, but dispatch still runs a
            # call the model was not shown. Skip the pause so it stays a no-op.
            confirmation = self._cancel_skill_confirmation
            if (
                is_confirmation_gate_active(confirmation)
                and tracker_handle.active_frame is not None
                and confirmation is not None
            ):
                return self._tool_constraints.run_cancel_skill(
                    confirmation=confirmation,
                    tracker_handle=tracker_handle,
                )
            self._cancel_skill(tracker_handle)
            return None
        if tool_name == TOOL_CORRECT:
            return await self._correction.dispatch(tool_args, tracker_handle)
        if tool_name == TOOL_SEARCH_KNOWLEDGE:
            return await self._dispatch_search_knowledge(tool_args, tracker_handle)
        if tool_name == TOOL_CANNOT_HELP:
            return self._dispatch_cannot_help(tool_args, tracker_handle)
        if tool_name == TOOL_RESOLVE_TOOL_CONFIRMATION:
            return await self._tool_constraints.resolve_and_advance(
                tool_args, tracker_handle
            )

        active_skill_id, _ = tracker_handle.memory_scope()
        active_target_id = tracker_handle.active_flow_id or ""
        tools_for_skill = self._tool_funcs.get(active_skill_id, {})
        if self._is_builder_defined_tool(active_skill_id, tool_name):
            return await self._dispatch_builder_defined_tool(
                tool_name=tool_name,
                tool_args=tool_args,
                tracker_handle=tracker_handle,
                memory_values=memory_values,
                active_skill_id=active_skill_id,
                active_target_id=active_target_id,
                tools_for_skill=tools_for_skill,
            )
        if tool_name == TOOL_SET_FIELDS:
            return await self._dispatch_set_fields(tool_args, tracker_handle)

        structlogger.warning(
            "mantle.skill_executor.dispatch.unexpected_tool",
            tool_name=tool_name,
        )
        return format_error_as_json(
            f"Unknown tool '{tool_name}' — no handler registered."
        )

    async def _dispatch_builder_defined_tool(
        self,
        *,
        tool_name: str,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
        memory_values: Mapping[str, Any],
        active_skill_id: str,
        active_target_id: str,
        tools_for_skill: Mapping[str, Callable[..., Any]],
    ) -> str:
        """Delegate a gated builder tool to the tool execution runtime."""
        if is_memory_validation_tool(tool_name):
            structlogger.warning(
                "mantle.skill_executor.dispatch.memory_validation_tool.blocked",
                tool_name=tool_name,
            )
            return format_error_as_json(
                f"Tool '{tool_name}' is internal and cannot be called directly."
            )
        if tool_name in button_source_names_for_skill(
            self._skill_catalog,
            self._response_registry,
            active_skill_id,
        ):
            structlogger.warning(
                "mantle.skill_executor.dispatch.button_source.blocked",
                tool_name=tool_name,
            )
            return format_error_as_json(
                f"Tool '{tool_name}' is internal and cannot be called directly."
            )
        return await self._tool_constraints.dispatch_builder_tool(
            tool_name=tool_name,
            tool_args=tool_args,
            tracker_handle=tracker_handle,
            memory_values=memory_values,
            active_skill_id=active_skill_id,
            active_target_id=active_target_id,
            tool_func=tools_for_skill.get(tool_name),
        )

    async def _dispatch_search_knowledge(
        self,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
    ) -> str:
        """Retrieve from the local references index for a ``search_knowledge`` call.

        Queries the packaged FAISS index (via
        :attr:`ToolModelContext.references_index`) and returns the results as a
        JSON tool message. Retrieval failures degrade to an empty result set
        rather than raising: knowledge search runs on the message path, which
        must never crash the turn.

        Knowledge hooks run after the empty-query guard and around the index
        call: ``modify_knowledge_query`` may rewrite the query (fail-closed on
        crash); ``modify_knowledge_results`` may filter/reorder passages
        (fail-open on crash). Neither point accepts intentional control signals.
        """
        # TODO(ENG-2981): two sources of truth for "is knowledge available" — the
        # schema gate reads Orchestrator._static_data.references_index while
        # dispatch reads it off model_context here. They agree today (both derive
        # from the same ModelBootstrap), but the retriever registry in ENG-2981
        # should reconcile them so "offered" and "dispatchable" cannot drift.
        index: Optional[InformationRetrieval] = (
            tracker_handle.model_context.references_index
        )
        if index is None:
            # Defensive: the tool is only offered when an index is present, so a
            # call without one means a knowledge base is not configured.
            return format_error_as_json("No knowledge base is configured.")

        query = str(tool_args.get("query", "")).strip()
        if not query:
            return _search_result_note(_EMPTY_QUERY_NOTE)

        try:
            query = await apply_knowledge_query_hooks(self._hooks, query)
        except HookExecutionError:
            # Fail-closed: do not search with the unprotected query.
            return _search_result_note(_NO_KNOWLEDGE_FOUND_NOTE)

        query = query.strip()
        if not query:
            return _search_result_note(_EMPTY_QUERY_NOTE)

        try:
            results = await index.search(query, tracker_state={})
        except InformationRetrievalException as exc:
            structlogger.warning(
                "mantle.skill_executor.search_knowledge.failed",
                error_type=type(exc.__cause__ or exc).__name__,
            )
            return _search_result_note(_NO_KNOWLEDGE_FOUND_NOTE)

        results = await apply_knowledge_results_hooks(
            self._hooks,
            query=query,
            results=results,
        )

        structlogger.debug(
            "mantle.skill_executor.search_knowledge.retrieved",
            result_count=len(results.results),
        )
        return _format_search_results(results)

    def _dispatch_activate(
        self,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
        memory_values: Dict[str, Any],
    ) -> Optional[str]:
        """Handle an LLM ``activate`` tool call.

        Reads ``target_id`` from tool args (LLM boundary), resolves the internal
        flow id, and validates activatability for the current memory/stack state.

        Returns an error string on validation failure, or ``None`` on success.
        """
        flow_id = str(tool_args.get("target_id", ""))

        # Parked task below the live skill — resume in place before validation.
        # Otherwise ``_validate_activate_args`` no-ops ("already on stack") and
        # leaves the live skill on top.
        if flow_id:
            resume_note = self._try_resume_suspended_flow_in_place(
                flow_id, tracker_handle
            )
            if resume_note is not None:
                structlogger.debug(
                    "mantle.skill_executor.dispatch.activate.resume_in_place_handled",
                    flow_id=flow_id,
                    event_info=("activate resume-in-place path handled the request."),
                )
                return resume_note

        validation_error = self._validate_activate_args(
            flow_id, tracker_handle, memory_values
        )
        if validation_error is not None:
            return validation_error

        owning_skill = self._skill_catalog.owning_skill_for_target_id(flow_id)
        active_target_id = tracker_handle.active_flow_id

        # Runs when the LLM calls activate and the stack already has the
        # target as a same-skill family member below the top: reactivate that
        # frame instead of pushing a duplicate (preserves step_id).
        if (
            active_target_id is not None
            and self._skill_catalog.is_same_inline_family(active_target_id, flow_id)
            and self._is_flow_frame_below_top(tracker_handle, flow_id)
            and self._promotes_stacked_same_skill_target(flow_id)
        ):
            if self._reactivate_stacked_same_skill_block(flow_id, tracker_handle):
                return None
            return format_error_as_json(
                f"activate failed: could not reactivate '{flow_id}'."
            )

        if should_discard_default_before_activate(
            self._skill_catalog, tracker_handle.active_frame, owning_skill
        ):
            if not self._discard_active_lifecycle_default(tracker_handle):
                return format_error_as_json(
                    "activate failed: could not discard the active default skill."
                )
            frame_type = FlowStackFrameType.REGULAR
        else:
            parent_skill_id, _ = tracker_handle.memory_scope()
            resolved_frame_type, frame_type_error = self._resolve_activate_frame_type(
                active_target_id, flow_id, owning_skill, parent_skill_id
            )
            if frame_type_error is not None:
                return frame_type_error
            if resolved_frame_type is None:
                return format_error_as_json(
                    f"activate failed: could not resolve frame type for '{flow_id}'."
                )
            frame_type = resolved_frame_type

        activated = self._activate_with_preconditions(
            flow_id,
            tracker_handle,
            memory_values,
            frame_type=frame_type,
            skill_id=owning_skill.id if owning_skill else None,
            block_id=self._skill_catalog.ordered_block_id_for_target(flow_id),
        )
        if not activated:
            return format_error_as_json(
                f"activate failed: entry '{flow_id}' not found."
            )
        return None

    def _promotes_stacked_same_skill_target(self, target_id: str) -> bool:
        """Return whether a stacked same-skill id may be lifted to the top.

        A skill id promotes only when that skill has prose, so the model can
        return to it from an internal block. A blocks-only skill id is the
        wrapper frame; lifting it leaves the called block. A compiled block
        id still promotes.
        """
        skill = self._skill_catalog.skill_by_id(target_id)
        if skill is None:
            return True
        return skill_has_prose(skill)

    def _dispatch_activate_skill_instruction(
        self,
        tool_name: str,
        instruction: ActivateSkill,
        tracker_handle: TrackerHandle,
    ) -> None:
        """Start the skill named by a tool's ``ActivateSkill`` instruction.

        Pushes the target as a ``CALL`` frame, the same way a ``call:`` step
        does: the current frame is left untouched and regains control when the
        callee completes. Never raises: an unresolvable target, a target
        already on the stack, or an unexpected error is logged and the turn
        continues.
        """
        target_id = self._activate_skill_target_id(tool_name, instruction)
        if target_id is None:
            return
        log_context = {
            "tool": tool_name,
            "skill_id": instruction.skill_id,
            "target_id": target_id,
        }
        if self._is_target_on_stack(target_id, tracker_handle):
            structlogger.info(
                "mantle.skill_executor.tool.next.already_on_stack", **log_context
            )
            return
        target_skill = self._skill_catalog.owning_skill_for_target_id(target_id)
        caller_skill_id, _ = tracker_handle.memory_scope()
        same_skill_call = (
            target_skill is not None and target_skill.id == caller_skill_id
        )
        try:
            activated = self._activate_with_preconditions(
                target_id,
                tracker_handle,
                self.current_memory_values(tracker_handle),
                skill_id=target_skill.id if target_skill else None,
                block_id=self._skill_catalog.ordered_block_id_for_target(target_id),
                new_frame_type=FlowStackFrameType.CALL,
                reset_memory=not same_skill_call,
            )
        except Exception:
            structlogger.exception(
                "mantle.skill_executor.tool.next.activate_failed", **log_context
            )
            return
        if not activated:
            structlogger.warning(
                "mantle.skill_executor.tool.next.activate_skipped",
                reason="entry not found",
                **log_context,
            )
            return
        structlogger.info("mantle.skill_executor.tool.next.activated", **log_context)

    @staticmethod
    def _is_target_on_stack(target_id: str, tracker_handle: TrackerHandle) -> bool:
        """Return whether *target_id* already has a frame anywhere on the stack."""
        stack_target_ids = {
            frame.flow_id for frame in tracker_handle.user_flow_frames()
        }
        stack_target_ids.update(
            target_id_for_frame(frame)
            for frame in tracker_handle.skill_and_block_frames()
        )
        return target_id in stack_target_ids

    def _activate_skill_target_id(
        self, tool_name: str, instruction: ActivateSkill
    ) -> Optional[str]:
        """Return the target id an ``ActivateSkill`` addresses, or ``None``.

        ``ordered_block`` names an ordered block of the skill; without it the
        skill's entry target is used. ``None`` (logged) when the skill is
        unknown or disabled, has no entry target, does not own the requested
        block, or the block is internal (``routable: false``), which ``call:``
        steps refuse as well.
        """
        skill = self._skill_catalog.skill_by_id(instruction.skill_id)
        if skill is None or skill.disabled:
            target_id = None
        elif instruction.ordered_block is None:
            target_id = entry_target_id_for_skill(skill)
        elif any(
            block.block_id == instruction.ordered_block
            for block in ordered_blocks_in_body(skill)
        ):
            target_id = format_ordered_block_target_id(
                skill.id, instruction.ordered_block
            )
        else:
            target_id = None
        if target_id is None:
            structlogger.warning(
                "mantle.skill_executor.tool.next.unknown_target",
                tool=tool_name,
                skill_id=instruction.skill_id,
                ordered_block=instruction.ordered_block,
            )
            return None
        if self._skill_catalog.is_internal_target(target_id):
            structlogger.warning(
                "mantle.skill_executor.tool.next.internal_target",
                tool=tool_name,
                skill_id=instruction.skill_id,
                target_id=target_id,
            )
            return None
        return target_id

    def _validate_activate_args(
        self,
        target_id: str,
        tracker_handle: TrackerHandle,
        memory_values: Dict[str, Any],
    ) -> Optional[str]:
        """Validate an ``activate`` request before stack mutation.

        ``target_id`` is a skill id, or ``{skill_id}__{block_id}`` for an
        ordered block. Returns a tool response string when the call should
        stop early, or ``None`` when activation may proceed.
        """
        # Re-activating a target already on the user stack is a no-op, unless
        # it is a same-family frame parked below the top — dispatch will
        # promote that frame instead of pushing a duplicate. Comparing only
        # against the top frame misses parent prose underneath an ordered
        # block (stack pollution). The LLM occasionally re-issues activate
        # for a skill or block already running.
        active_target_id = tracker_handle.active_flow_id
        if target_id and target_id == active_target_id:
            structlogger.debug(
                "mantle.skill_executor.dispatch.activate.already_on_stack",
                target_id=target_id,
                active_target_id=active_target_id,
            )
            return f"'{target_id}' is already on the stack; continuing it."

        stack_target_ids = {f.flow_id for f in tracker_handle.user_flow_frames()}
        stack_target_ids.update(
            target_id_for_frame(frame)
            for frame in tracker_handle.skill_and_block_frames()
        )
        if target_id and target_id in stack_target_ids:
            same_skill_below_top = (
                active_target_id is not None
                and self._skill_catalog.is_same_inline_family(
                    active_target_id, target_id
                )
                and self._is_flow_frame_below_top(tracker_handle, target_id)
            )
            if same_skill_below_top and self._promotes_stacked_same_skill_target(
                target_id
            ):
                return None
            if not same_skill_below_top:
                structlogger.debug(
                    "mantle.skill_executor.dispatch.activate.already_on_stack",
                    target_id=target_id,
                    active_target_id=active_target_id,
                )
                return f"'{target_id}' is already on the stack; continuing it."

        allowed_target_ids = set(
            self._skill_catalog.get_startable_candidate_target_ids(
                memory_values,
                active_target_id=active_target_id,
                paused_block_ids=paused_ordered_block_target_ids(
                    tracker_handle.tracker, self._skill_catalog
                ),
            )
        )
        # (A same-skill activate while the engine-managed decline is
        # active is refused centrally in dispatch_tool_call, before this
        # method runs.)
        if target_id not in allowed_target_ids:
            structlogger.warning(
                "mantle.skill_executor.dispatch.activate.not_activatable",
                target_id=target_id,
            )
            return format_error_as_json(
                f"Cannot activate '{target_id}': not a routable flow."
            )
        return None

    def _resolve_activate_frame_type(
        self,
        active_target_id: Optional[str],
        flow_id: str,
        owning_skill: Optional[Skill],
        parent_skill_id: Optional[str],
    ) -> tuple[Optional[FlowStackFrameType], Optional[str]]:
        """Choose the stack frame type for a new ``activate`` push.

        Returns ``(frame_type, None)`` on success, or ``(None, error)`` when the
        requested flow is not a valid entry for a delegated skill.
        """
        # Same-skill internal: park current top inline, except prose → ordered
        # block (both stay ``regular``). Same-skill block↔block / main↔sub
        # still park (same-skill block switch).
        if self._skill_catalog.is_inline_sub_target_activation(
            active_target_id, flow_id
        ):
            if (
                active_target_id is not None
                and not self._skill_catalog.is_internal_target(active_target_id)
                and self._skill_catalog.ordered_block_id_for_target(active_target_id)
                is None
                and self._skill_catalog.ordered_block_id_for_target(flow_id) is not None
            ):
                return FlowStackFrameType.REGULAR, None
            return FlowStackFrameType.INLINE_REFERENCE, None
        if active_target_id is None:
            return FlowStackFrameType.REGULAR, None
        if is_wrap_up_or_csat_block(self._skill_catalog, active_target_id):
            return FlowStackFrameType.REGULAR, None
        if parent_skill_id and self._skill_catalog.is_referenced_skill_target(
            parent_skill_id, flow_id
        ):
            return FlowStackFrameType.REGULAR, None
        if parent_skill_id and self._skill_catalog.is_referenced_block_target(
            parent_skill_id, flow_id
        ):
            return FlowStackFrameType.REGULAR, None
        # Do not activate a block that is not the skill's entry block.
        if (
            owning_skill is not None
            and parent_skill_id
            and owning_skill.id != parent_skill_id
            and self._skill_catalog.is_referenced_skill_id(
                parent_skill_id, owning_skill.id
            )
        ):
            entry_target_id = entry_target_id_for_skill(owning_skill)
            structlogger.warning(
                "mantle.skill_executor.dispatch.activate.wrong_entry_flow",
                flow_id=flow_id,
                skill_id=owning_skill.id,
                entry_flow_id=entry_target_id,
            )
            return None, format_error_as_json(
                f"Cannot activate '{flow_id}': delegated skill "
                f"'{owning_skill.id}' must be entered via entry flow "
                f"'{entry_target_id}'."
            )
        return FlowStackFrameType.INTERRUPT, None

    def _is_flow_frame_below_top(
        self, tracker_handle: TrackerHandle, flow_id: str
    ) -> bool:
        """Verify whether *flow_id* already has a user frame under the active top.

        Used before an inline family switch: if the target is already on the
        stack below the current top, :meth:`_reactivate_stacked_same_skill_block`
        can reorder it instead of pushing a duplicate frame. Returns ``False``
        when the stack has fewer than two user frames or *flow_id* is absent
        below the top.

        Matches legacy ``UserFlowStackFrame``, ``OrderedBlockStackFrame``, and
        hybrid prose ``SkillStackFrame`` (``skill_id`` equals *flow_id*).

        Works among main and any same-skill sub-flows, for example
        (``INLINE`` = ``INLINE_REFERENCE``):

        * ``[main INLINE | sub_a INLINE | sub_b REGULAR]`` +
          ``activate(main)`` → reactivate main
          (``[sub_a INLINE | sub_b INLINE | main REGULAR]``).
        * ``[sub_a INLINE | main INLINE | sub_b REGULAR]`` +
          ``activate(sub_a)`` → reactivate sub_a
          (``[main INLINE | sub_b INLINE | sub_a REGULAR]``).
        * ``[Skill REGULAR | Block REGULAR]`` + ``activate(skill_id)`` →
          promote the skill (``[Block INLINE | Skill REGULAR]``).
        """
        frames = tracker_handle.stack.frames
        if len(frames) <= 1:
            return False
        return any(
            isinstance(
                frame,
                (UserFlowStackFrame, OrderedBlockStackFrame, SkillStackFrame),
            )
            and target_id_for_frame(frame) == flow_id
            for frame in frames[:-1]
        )

    def _dispatch_cannot_help(
        self,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
    ) -> Optional[str]:
        """Handle a ``cannot_help`` tool call by declining the request.

        Activates the builder-customizable decline skill, interrupting any active
        skill exactly as a digression would. Seeds the request type so the
        override can distinguish in-domain from out-of-domain requests, and
        records an ``UnsupportedRequestClassified`` audit event for offline
        evaluation and analytics.

        Returns an error string when the decline skill cannot be activated, or
        ``None`` on success.
        """
        # The decline is already running (e.g. a second cannot_help in the same
        # LLM response). Re-activating would mark the first decline frame
        # INTERRUPT and surface a spurious resume prompt, so treat it as a no-op.
        if (
            lifecycle_skill_id_for_frame(
                self._skill_catalog, tracker_handle.active_frame
            )
            == DEFAULT_UNSUPPORTED_REQUEST_HANDLER
        ):
            return "Already declining the request; no further action needed."

        decline_entry_id = entry_id_for_skill_id(
            self._skill_catalog, DEFAULT_UNSUPPORTED_REQUEST_HANDLER
        )
        if decline_entry_id is None:
            return format_error_as_json(
                "cannot_help failed: decline skill is not available."
            )

        # Coerce defensively: a JSON boolean arrives as a Python bool, but a
        # string like "false" must not be truthy-coerced (bool("false") is True).
        raw_in_domain = tool_args.get("in_domain", False)
        in_domain = (
            raw_in_domain
            if isinstance(raw_in_domain, bool)
            else str(raw_in_domain).strip().lower() == "true"
        )
        request_type = (
            REQUEST_TYPE_IN_DOMAIN_OUT_OF_SCOPE
            if in_domain
            else REQUEST_TYPE_OUT_OF_DOMAIN_OUT_OF_SCOPE
        )

        # Seed the request type before activating so gate_request_type reads
        # exactly this turn's value. Decline activation skips the new-run
        # memory reset so this seed survives (see ``reset_memory`` on
        # :meth:`_activate`).
        #
        # If the write is denied — e.g. a project override of the decline skill
        # replaced memory.yml and dropped the request_type field — we do NOT fail
        # the call: the handler is engine_managed, so cannot_help is the only
        # decline path and hard-failing would leave the user with no decline at
        # all. Instead we degrade gracefully. The skill's gate still declines via
        # its else branch; we audit the value the gate will actually read (the
        # slot we could not overwrite) so analytics match what the user hears.
        try:
            tracker_handle.memory.set(
                DEFAULT_UNSUPPORTED_REQUEST_HANDLER,
                decline_entry_id,
                REQUEST_TYPE_ENTRY,
                request_type,
            )
            effective_request_type = request_type
        except MemoryWriteError:
            effective_request_type = self._effective_request_type_on_write_failure(
                tracker_handle, decline_entry_id
            )
            structlogger.warning(
                "mantle.skill_executor.cannot_help.request_type_write_failed",
                requested=request_type,
                effective=effective_request_type,
            )

        # Audit reason mirrors the *effective* request type (what the gate utters),
        # not the intended one, so label and reason never disagree on a degraded
        # write.
        reason = (
            "in domain but not a supported task"
            if effective_request_type == REQUEST_TYPE_IN_DOMAIN_OUT_OF_SCOPE
            else "outside the agent's domain"
        )

        frame_type = (
            FlowStackFrameType.INTERRUPT
            if tracker_handle.active_flow_id is not None
            else FlowStackFrameType.REGULAR
        )
        activated = self._activate(
            decline_entry_id,
            tracker_handle,
            frame_type=frame_type,
            skill_id=DEFAULT_UNSUPPORTED_REQUEST_HANDLER,
            block_id=self._skill_catalog.ordered_block_id_for_target(decline_entry_id),
            reset_memory=False,
        )
        if not activated:
            return format_error_as_json(
                "cannot_help failed: decline skill is not available."
            )

        tracker_handle.apply_events(
            [
                UnsupportedRequestClassified(
                    label=effective_request_type,
                    reason=reason,
                    user_message=_latest_user_message_text(
                        tracker_handle.tracker.events
                    ),
                )
            ]
        )
        return None

    def _effective_request_type_on_write_failure(
        self, tracker_handle: TrackerHandle, decline_entry_id: str
    ) -> str:
        """Request type the decline gate will use when the seed write is denied.

        Mirrors ``gate_request_type`` in the decline skill: the gate routes to the
        out-of-domain decline only when the slot already equals
        ``out_of_domain_out_of_scope``; anything else (including an unset or
        undeclared slot) falls through to the in-domain out-of-scope decline. The
        audit event is stamped with this value so analytics match the uttered
        decline even though the intended value could not be written.
        """
        entry = tracker_handle.memory.get(
            DEFAULT_UNSUPPORTED_REQUEST_HANDLER,
            decline_entry_id,
            REQUEST_TYPE_ENTRY,
        )
        existing = entry.value if entry is not None else None
        if existing == REQUEST_TYPE_OUT_OF_DOMAIN_OUT_OF_SCOPE:
            return REQUEST_TYPE_OUT_OF_DOMAIN_OUT_OF_SCOPE
        return REQUEST_TYPE_IN_DOMAIN_OUT_OF_SCOPE

    async def _dispatch_set_fields(
        self,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
    ) -> str:
        """Handle a batch ``set_fields`` tool call.

        Writes each field the LLM provided that matches the skill's settable
        set for this turn (``llm_settable`` fields plus collect targets,
        see :meth:`settable_fields_for_turn`) — the same source the schema was
        built from, so schema and dispatch always agree on what is eligible.
        Fields outside that set are rejected *per field* rather than failing
        the whole call, so the model sees exactly what happened and can retry
        just the rest.

        Deliberately does **not** advance the step pointer itself:
        ``advance_steps`` already skips a filled :class:`CollectStep` the
        next time it reaches it (``_handle_collect_step``), and the
        orchestrator re-runs ``advance_steps`` before every LLM call — so
        writing the value here is sufficient for the active step and every
        upcoming one; no separate advancement logic is needed.

        Returns a single human-readable, semicolon-joined per-field result
        string to append to the LLM message list. When no field was written the
        result is a structured error instead, so the call is recorded as failed
        and the model can retry the write through ``correct``.
        """
        frame = tracker_handle.active_frame
        if frame is None:
            return format_error_as_json("Cannot set fields: no active flow.")
        if not tool_args:
            return format_error_as_json("No fields provided to set_fields.")

        memory = tracker_handle.memory
        skill_id, flow_id = memory.resolve_scope(frame)
        eligible_fields, _descriptions = self.settable_fields_for_turn(tracker_handle)
        eligible = set(eligible_fields)
        # The active ``ask_before_filling`` collect field is always asked at its
        # step, so it may overwrite an existing value here (every other field is
        # first-write-only; corrections go through the ``correct`` tool).
        overwrite_ok_field = self._ask_before_filling_field_at_step(tracker_handle)

        memory_values_before = snapshot_accessible_memory(memory, skill_id, flow_id)
        any_field_written = False

        results: Dict[str, str] = {}
        for field_name, value in tool_args.items():
            outcome, written = await self._apply_one_set_field(
                tracker_handle=tracker_handle,
                memory=memory,
                skill_id=skill_id,
                flow_id=flow_id,
                field_name=field_name,
                value=value,
                eligible=eligible,
                overwrite_ok_field=overwrite_ok_field,
            )
            results[field_name] = outcome
            if written:
                any_field_written = True

        if any_field_written:
            self._verbatim_trigger_evaluator.evaluate_when_triggers(
                skill_id,
                flow_id,
                tracker_handle,
                memory_values_before=memory_values_before,
            )

        summary = "; ".join(f"{name}: {outcome}" for name, outcome in results.items())
        if any_field_written:
            return summary
        return format_error_as_json(summary)

    async def _apply_one_set_field(
        self,
        *,
        tracker_handle: TrackerHandle,
        memory: MemoryManager,
        skill_id: str,
        flow_id: str,
        field_name: str,
        value: Any,
        eligible: set[str],
        overwrite_ok_field: Optional[str],
    ) -> tuple[str, bool]:
        """Write one ``set_fields`` entry; return ``(outcome, wrote)``."""
        if field_name not in eligible:
            return (
                self._ineligible_set_field_outcome(
                    memory, skill_id, flow_id, field_name
                ),
                False,
            )

        if value is None:
            return f"not set: '{field_name}' requires a non-null value", False

        existing = self._memory_entry_or_none(memory, skill_id, flow_id, field_name)
        if (
            existing is not None
            and existing.value is not None
            and field_name != overwrite_ok_field
        ):
            return self._already_set_outcome(field_name, existing.value), False

        write_result = await write_settable_field(
            tracker_handle,
            skill_id,
            flow_id,
            field_name,
            value,
            self._tool_funcs,
            self.call_tool_func,
        )
        if write_result.ok:
            return f"set to {value!r}", True
        return self._failed_set_field_outcome(field_name, write_result), False

    @staticmethod
    def _already_set_outcome(field_name: str, existing_value: Any) -> str:
        """Explain a refused overwrite and name the tool that can do it."""
        return (
            f"not set: '{field_name}' is already set to {existing_value!r} "
            f"(call '{TOOL_CORRECT}' to change a value captured earlier)"
        )

    @staticmethod
    def _memory_entry_or_none(
        memory: MemoryManager, skill_id: str, flow_id: str, field_name: str
    ) -> Optional[MemoryEntry]:
        """Return a memory entry, or ``None`` when the entry is undeclared."""
        try:
            return memory.get(skill_id, flow_id, field_name)
        except ValueError:
            return None

    def _ineligible_set_field_outcome(
        self,
        memory: MemoryManager,
        skill_id: str,
        flow_id: str,
        field_name: str,
    ) -> str:
        """Explain why a field was rejected as not settable this turn."""
        existing = self._memory_entry_or_none(memory, skill_id, flow_id, field_name)
        if existing is not None and existing.value is not None:
            outcome = self._already_set_outcome(field_name, existing.value)
        else:
            outcome = (
                f"not set: '{field_name}' is not a settable memory "
                "field for this skill right now"
            )
        structlogger.warning(
            "mantle.skill_executor.dispatch.set_fields.not_eligible",
            field_name=field_name,
        )
        return outcome

    @staticmethod
    def _failed_set_field_outcome(
        field_name: str, write_result: SettableWriteResult
    ) -> str:
        """Format a denied or validation-failed ``set_fields`` write for the LLM."""
        reason = write_result.error or "write rejected"
        if write_result.memory_validation_failed:
            structlogger.warning(
                "mantle.skill_executor.dispatch.set_fields.memory_validation_failed",
                field_name=field_name,
                reason=reason,
            )
            return f"not set: memory validation tool failed: {reason}"

        structlogger.warning(
            "mantle.skill_executor.dispatch.set_fields.denied",
            field_name=field_name,
            reason=reason,
        )
        return reason

    # ------------------------------------------------------------------
    # Private helpers
    # ------------------------------------------------------------------

    async def call_tool_func(
        self,
        func: Optional[Callable[..., Any]],
        tool_name: str,
        tool_args: Dict[str, Any],
        session: TrackerHandle,
        memory_scope: Optional[tuple[str, str]] = None,
    ) -> str:
        """Invoke a local or MCP tool through the shared tool runtime.

        This public adapter is used by memory validation tools, static memory buttons,
        correction replay, and builder-tool dispatch.
        """
        return await self._tool_invoker.call_tool_func(
            func,
            tool_name,
            tool_args,
            session,
            memory_scope,
        )
